                                                                foreach ($ticket['child_ranges'] as $range) {
                                                                    $saved_child_count += (int)($range['count'] ?? 0);
                                                                }
                                                            }
                                                            if ($saved_child_count == $child_num) {
                                                                return $ticket;
                                                            }
                                                        }
