                                                    // For group tickets
                                                    if ($ticket_type === 'group' || (isset($ticket['ticket_type']) && $ticket['ticket_type'] === 'group')) {
                                                        if ($skip_count_check) return $ticket;
                                                        if (isset($ticket['group_size'], $ticket['group_count'])) {
                                                            $total_capacity = $ticket['group_size'] * $ticket['group_count'];
                                                            $total_persons = $adults_num + $child_num;
