                                        $all_days_total += $day_total;
                                    } 
                                }
                            }
                            ?>
        

                    <?php 
                    if ($route_change == 'yes' || $day_trip == 'yes') 
                    {
                        // Decode and group route change data
                        $routeChangeDataRaw = $this->input->get('routeChangeData');
                        $routeChangeData = json_decode($routeChangeDataRaw, true) ?? [];
                        $sectionsByDay = [];
                        foreach ($routeChangeData as $section) {
                            $day = (int)$section['day'];
                            $sectionsByDay[$day][] = $section;
                        }

                        $dayNumber = $key + 1; 
                        $sections = $sectionsByDay[$dayNumber] ?? [];

                        if (!empty($sections)) {
                            // Pre‑fetch common data once per day (vehicles, quantities, etc.)
                            $transportIds = [];
                            if (!empty($transportation_cost)) {
                                foreach ($transportation_cost as $row) {
                                    $transportIds[] = $row->transport_id;
                                }
                            }
                            $vehicleQuantities = $this->input->get('vehicle_quantity');
                            $adultCount = $this->input->get('number_of_adults') ?? 1;
                            $childCount = $this->input->get('number_of_child') ?? 0;

                            // Pre‑fetch full‑day periods for Uzbekistan train logic
                            $fullDayPeriods = [];
                            if (!empty($transportIds) && $country == 'uzbekistan') {
                                $fullDayQuery = $this->db
                                    ->where_in('transport_id', $transportIds)
                                    ->where('type', 'full-day')
                                    ->where('valid_from <=', $list->date)
                                    ->where('valid_to >=', $list->date)
                                    ->get('transportation_costs')
                                    ->result();
                                foreach ($fullDayQuery as $fd) {
                                    $fullDayPeriods[$fd->transport_id][] = [
                                        'start' => $fd->start_time,
                                        'end'   => $fd->end_time
                                    ];
                                }
                            }

                            // Pre‑fetch saved data for this day (from $saved_daywise_road, $saved_daywise_train_transport, $saved_daywise_train)
                            $savedRoadDataForDay = [];
                            foreach ($saved_daywise_road as $saved) {
                                if (isset($saved['day']) && $saved['day'] == $dayNumber) {
                                    $savedRoadDataForDay = $saved['vehicles'] ?? [];
                                    break;
                                }
                            }
                            $savedTrainTransportDataForDay = [];
                            foreach ($saved_daywise_train_transport as $saved) {
                                if (isset($saved['day']) && $saved['day'] == $dayNumber) {
                                    $savedTrainTransportDataForDay = $saved['vehicles'] ?? [];
                                    break;
                                }
                            }
                            $savedTrainDataForDay = [];
                            foreach ($saved_daywise_train as $saved) {
                                if (isset($saved['day']) && $saved['day'] == $dayNumber) {
                                    $savedTrainDataForDay = $saved['trains'] ?? [];
                                    break;
                                }
                            }

                            // Track cities to determine first road segment in a city (for toll)
                            $citiesInDay = []; // array of to_city in order of sections

                            // Process each section
                            foreach ($sections as $sectionIdx => $section) {
                                $transferMode = $section['transfer_mode'] ?? '';

                                if ($transferMode === 'road') {
                                    // --- ROAD SECTION (mirrors $isRoadDay logic) ---
                                    $fromCity = strtolower($section['from_city'] ?? '');
                                    $toCity   = strtolower($section['to_city'] ?? '');
                                    $overnightType = $section['overnight_type'] ?? '';

                                    // Determine if this is the first road section in this city (for toll)
                                    $isFirstRoadDayInCity = true;
                                    if (in_array($toCity, $citiesInDay)) {
                                        $isFirstRoadDayInCity = false;
                                    }
                                    $citiesInDay[] = $toCity;

                                    // --- Fetch costs and vehicle data (same as in 'no' branch) ---
                                    $baseCosts = $tollCosts = $parkingCosts = [];
                                    $routeData = [];
                                    $vehicleNames = [];

                                    if (!empty($transportIds)) {
                                        // transportation_costs
                                        $costQuery = $this->db
                                            ->where_in('transport_id', $transportIds)
                                            ->where('valid_from <=', $list->date)
                                            ->where('valid_to >=', $list->date)
                                            ->get('transportation_costs')
                                            ->result();
                                        foreach ($costQuery as $c) {
                                            switch ($c->type) {
                                                case 'transfer-cost': $baseCosts[$c->transport_id] = $c->price; break;
                                                case 'transfer-cost-toll': $tollCosts[$c->transport_id] = $c->price; break;
                                                case 'transfer-cost-parking': $parkingCosts[$c->transport_id] = $c->price; break;
                                            }
                                        }

                                        // transfer_routes (using section's from/to cities)
                                        $routeQuery = $this->db
                                            ->where_in('transport_id', $transportIds)
                                            ->where('from_city', $fromCity)
                                            ->where('to_city', $toCity)
                                            ->where('valid_from <=', $list->date)
                                            ->where('valid_to >=', $list->date)
                                            ->where('status', 'active')
                                            ->get('transfer_routes')
                                            ->result();
                                        foreach ($routeQuery as $r) {
                                            $routeData[$r->transport_id] = [
                                                'cost'    => $r->cost,
                                                'toll'    => $r->toll ?? 0,
                                                'parking' => $r->parking ?? 0
                                            ];
                                        }

                                        // vehicle names
                                        $vehicles = $this->db->where_in('id', $transportIds)->get('transportation')->result();
                                        foreach ($vehicles as $v) {
                                            $vehicleNames[$v->id] = $v->vehicle_name;
                                        }
                                    }

                                    // Prepare saved road data for this section (if any)
                                    $savedRoadDataForSection = [];
                                    if (!empty($savedRoadDataForDay)) {
                                        foreach ($savedRoadDataForDay as $sv) {
                                            // If saved data has a section field, filter; otherwise assume it's for this day (no section)
                                            if (!isset($sv['section']) || $sv['section'] == $sectionIdx) {
                                                $savedRoadDataForSection[] = $sv;
                                            }
                                        }
                                    }

                                    $totalTransferCost = 0;
                                    $roadVehiclesData = [];

                                    // Start HTML block
                                    ?>
                                    <div class="alert alert-dark mt-2" data-day="<?= $dayNumber ?>" data-section="<?= $sectionIdx ?>" style="margin-bottom:2px !important;padding:4px;text-transform:capitalize;font-size:12px;text-align:center;">
                                        <div class="row" style="line-height: 10px;margin-top: 2px;font-weight:600;margin-bottom:6px;">
                                            <div class="col-md-3"><span style="color:#ef2100;"><i class="fa fa-car"></i> <?= ucfirst(str_replace('_', ' ', $overnightType) ?: 'Overnight') ?> <?= ucfirst($toCity); ?><?= $fromCity ? " ({$fromCity} → {$toCity})" : '' ?></span></div>
                                            <div class="col-md-3">Vehicle Name</div>
                                            <div class="col-md-2">Price</div>
                                            <div class="col-md-1">Parking</div>
                                            <div class="col-md-1">Qty.</div>
                                            <div class="col-md-2">Total</div>
                                        </div>

                                        <?php
                                        $index = 0;
                                        foreach ($transportIds as $transportId):
                                            $vehicleName = '';
                                            $price = $toll = $parking = 0;
                                            $quantity = 1;

                                            // Check saved data first
                                            $savedVehicle = null;
                                            foreach ($savedRoadDataForSection as $sv) {
                                                if ($sv['transport_id'] == $transportId) {
                                                    $savedVehicle = $sv;
                                                    break;
                                                }
                                            }

                                            if ($savedVehicle) {
                                                $price = (float)$savedVehicle['price'];
                                                $toll = (float)($savedVehicle['toll'] ?? 0);
                                                $parking = (float)($savedVehicle['parking'] ?? 0);
                                                $quantity = (int)$savedVehicle['qty'];
                                                $vehicleName = $savedVehicle['vehicle_name'] ?? '';
                                            } else {
                                                // Quantity from input
                                                if (isset($vehicleQuantities[$index]) && is_numeric($vehicleQuantities[$index])) {
                                                    $quantity = (int)$vehicleQuantities[$index];
                                                }

                                                // Price: routeData first, then baseCosts
                                                $price = $routeData[$transportId]['cost'] ?? $baseCosts[$transportId] ?? 0;
                                                $toll = $routeData[$transportId]['toll'] ?? $tollCosts[$transportId] ?? 0;
                                                $parking = $routeData[$transportId]['parking'] ?? $parkingCosts[$transportId] ?? 0;
                                                $vehicleName = $vehicleNames[$transportId] ?? 'Vehicle';
                                            }

                                            // Toll only on first road segment in this city
                                            if (!$isFirstRoadDayInCity) {
                                                $toll = 0;
                                            }

                                            $vehicleTotal = ($price + $parking) * $quantity;
                                            $totalTransferCost += $vehicleTotal;

                                            if ($price >= 0 && !empty(trim($vehicleName))) {
                                                $roadVehiclesData[] = [
                                                    'transport_id' => $transportId,
                                                    'vehicle_name' => trim($vehicleName),
                                                    'price'        => (float)$price,
                                                    'toll'         => (float)$toll,
                                                    'parking'      => (float)$parking,
                                                    'qty'          => (int)$quantity,
                                                    'total'        => (float)$vehicleTotal,
                                                    'section'      => $sectionIdx
                                                ];
                                            }
                                            ?>

                                            <div class="row road-transfer-row"
                                                data-day="<?= $dayNumber ?>"
                                                data-section="<?= $sectionIdx ?>"
                                                data-transport-id="<?= $transportId ?>"
                                                data-index="<?= $index ?>"
                                                style="line-height: 15px;margin-top: 2px;">
                                                <div class="col-md-3"></div>
                                                <div class="col-md-3">
                                                    <?= htmlspecialchars($vehicleName); ?>&nbsp;
                                                    <?php if ($isFirstRoadDayInCity): ?>
                                                        <br><strong>Toll</strong>
                                                        <input type="text" class="road_toll form-control form-control-sm" value="<?=$toll; ?>">
                                                        <input type="hidden" class="road_toll_perunit" value="<?= $toll ?>">
                                                    <?php else: ?>
                                                        <input type="hidden" class="road_toll" value="0">
                                                        <input type="hidden" class="road_toll_perunit" value="0">
                                                    <?php endif; ?>
                                                </div>
                                                <div class="col-md-2">
                                                    <input type="text" class="road_price form-control form-control-sm" value="<?= $price; ?>">
                                                </div>
                                                <div class="col-md-1">
                                                    <input type="text" class="road_parking form-control form-control-sm" value="<?= $parking; ?>">
                                                </div>
                                                <div class="col-md-1">
                                                    <input type="text" class="road_qty form-control form-control-sm" value="<?= $quantity; ?>">
                                                </div>
                                                <div class="col-md-2">
                                                    <input type="text" class="road_total form-control form-control-sm" value="<?= $vehicleTotal; ?>" readonly>
                                                </div>
                                            </div>

                                            <?php
                                            $index++;
                                        endforeach;
                                        ?>
                                    </div>

                                    <?php if (!empty($roadVehiclesData)): ?>
                                        <input type="hidden"
                                            id="daywiseRoadData_<?= $dayNumber ?>_section_<?= $sectionIdx ?>"
                                            class="daywise-road-data"
                                            data-day="<?= $dayNumber ?>"
                                            data-section="<?= $sectionIdx ?>"
                                            value='<?= json_encode(['day' => (int)$dayNumber, 'section' => $sectionIdx, 'type' => 'road', 'vehicles' => $roadVehiclesData]); ?>'>
                                    <?php endif; ?>
                                    <?php
                                } // end if road

                                elseif ($transferMode === 'train') 
                                {
                                    // --- TRAIN SECTION (mirrors $isTrainDay logic) ---
                                    $fromCity = strtolower($section['from_city'] ?? '');
                                    $toCity   = strtolower($section['to_city'] ?? '');
                                    $trainId  = $section['train_id'] ?? '';
                                    $ticketType = $section['ticket_type'] ?? '';
                                    $trainDepart = $section['train_depart'] ?? '';
                                    $trainArrive = $section['train_arrive'] ?? '';
                                    $overnightType = $section['overnight_type'] ?? '';
                                    $route_travel_with_guide = $section['travel_with_guide'] ?? '';

                                    if (empty($fromCity) || empty($toCity) || empty($trainId) || empty($ticketType)) {
                                        continue; // skip incomplete sections
                                    }

                                    // Fetch train schedule
                                    $trainSchedule = $this->db->select('train_schedule.*, train.train_name')
                                        ->from('train_schedule')
                                        ->join('train', 'train.id = train_schedule.train_id', 'left')
                                        ->where('train_schedule.id', $trainId)
                                        ->get()
                                        ->row();

                                    if (!$trainSchedule) {
                                        continue;
                                    }

                                    // ---- 1. STATION TRANSFER VEHICLES (same as 'no' branch) ----
                                    $costs = [];
                                    $routeCosts = [];
                                    $vehicleNames = [];

                                    if (!empty($transportIds)) {
                                        // transportation_costs (train-transfer-cost)
                                        $costQuery = $this->db
                                            ->where_in('transport_id', $transportIds)
                                            ->where('type', 'train-transfer-cost')
                                            ->where('valid_from <=', $list->date)
                                            ->where('valid_to >=', $list->date)
                                            ->get('transportation_costs')
                                            ->result();
                                        foreach ($costQuery as $c) {
                                            $costs[$c->transport_id] = $c->price;
                                        }

                                        // train_transfer_routes (fallback)
                                        $routeQuery = $this->db
                                            ->where_in('transport_id', $transportIds)
                                            ->where('from_city', $fromCity)
                                            ->where('to_city', $toCity)
                                            ->where('valid_from <=', $list->date)
                                            ->where('valid_to >=', $list->date)
                                            ->where('status', 'active')
                                            ->get('train_transfer_routes')
                                            ->result();
                                        foreach ($routeQuery as $r) {
                                            $routeCosts[$r->transport_id] = $r->cost;
                                        }

                                        // vehicle names
                                        $vehicles = $this->db->where_in('id', $transportIds)->get('transportation')->result();
                                        foreach ($vehicles as $v) {
                                            $vehicleNames[$v->id] = $v->vehicle_name;
                                        }
                                    }

                                    // Saved station transfer data for this section
                                    $savedTrainTransportForSection = [];
                                    if (!empty($savedTrainTransportDataForDay)) {
                                        foreach ($savedTrainTransportDataForDay as $sv) {
                                            if (!isset($sv['section']) || $sv['section'] == $sectionIdx) {
                                                $savedTrainTransportForSection[] = $sv;
                                            }
                                        }
                                    }

                                    $totalTransferCost = 0;
                                    $trainTransportVehiclesData = [];

                                    // Start station transfer HTML
                                    ?>
                                    <div class="alert alert-dark mt-2" data-day="<?= $dayNumber ?>" data-section="<?= $sectionIdx ?>" style="margin-bottom:2px !important;padding:4px;text-transform:capitalize;font-size:12px;text-align:center;">
                                        <div class="row" style="line-height: 10px;margin-top: 2px;font-weight:600;margin-bottom:6px;">
                                            <div class="col-md-2"><span style="color:#ef2100;"><i class="fa fa-car"></i> Station Transfer</span></div>
                                            <div class="col-md-3">Vehicle Name</div>
                                            <div class="col-md-2"><?= ($country == 'uzbekistan') ? 'One/Two Way' : 'Two Way' ?></div>
                                            <div class="col-md-2">Price</div>
                                            <div class="col-md-1">Qty.</div>
                                            <div class="col-md-2">Total</div>
                                        </div>

                                        <?php
                                        $index = 0;
                                        foreach ($transportIds as $transportId):
                                            $vehicleName = '';
                                            $price = 0;
                                            $quantity = 1;
                                            $savedVehicleFound = false;

                                            // Check saved data
                                            foreach ($savedTrainTransportForSection as $savedVehicle) {
                                                if ($savedVehicle['transport_id'] == $transportId) {
                                                    $price = (float)$savedVehicle['price'];
                                                    $quantity = (int)$savedVehicle['qty'];
                                                    $vehicleName = $savedVehicle['vehicle_name'] ?? '';
                                                    $savedVehicleFound = true;
                                                    break;
                                                }
                                            }

                                            if (!$savedVehicleFound) {
                                                if (isset($vehicleQuantities[$index]) && is_numeric($vehicleQuantities[$index])) {
                                                    $quantity = (int)$vehicleQuantities[$index];
                                                }
                                                $price = $costs[$transportId] ?? $routeCosts[$transportId] ?? 0;
                                                $vehicleName = $vehicleNames[$transportId] ?? 'Vehicle';
                                            }

                                            // Determine multiplier (One/Two Way) for Uzbekistan
                                            $multiplier = 2;
                                            $isOneWay = false;
                                            if ($country == 'uzbekistan') {
                                                if (!empty($train_arrival) && isset($fullDayPeriods[$transportId])) {
                                                    $arrivalTime = date('H:i:s', strtotime($train_arrival));
                                                    $departureTime = date('H:i:s', strtotime($train_departure));
                                                    foreach ($fullDayPeriods[$transportId] as $period) {
                                                        if (($arrivalTime >= $period['start'] && $arrivalTime <= $period['end']) ||
                                                            ($departureTime >= $period['start'] && $departureTime <= $period['end'])) {
                                                            $multiplier = 1;
                                                            $isOneWay = true;
                                                            break;
                                                        }
                                                    }
                                                }
                                            }

                                            $vehicleTotal = $price * $quantity * $multiplier;
                                            $totalTransferCost += $vehicleTotal;

                                            if ($price >= 0 && !empty(trim($vehicleName))) {
                                                // $trainTransportVehiclesData[] = [
                                                //     'transport_id' => $transportId,
                                                //     'vehicle_name' => trim($vehicleName),
                                                //     'price'        => (float)$price,
                                                //     'qty'          => (int)$quantity,
                                                //     'total'        => (float)$vehicleTotal,
                                                //     'section'      => $sectionIdx
                                                // ];
                                                $trainTransportVehiclesData[] = [
                                                    'transport_id' => $transportId,
                                                    'vehicle_name' => trim($vehicleName),
                                                    'price' => (float)$price,
                                                    'qty' => (int)$quantity,
                                                    'total' => (float)$vehicleTotal
                                                ];
                                            }
                                            ?>

                                            <div class="row train-transport-transfer-row"
                                                data-day="<?= $dayNumber ?>"
                                                data-section="<?= $sectionIdx ?>"
                                                data-transport-id="<?= $transportId ?>"
                                                data-multiplier="<?= $multiplier ?>"
                                                data-index="<?= $index ?>"
                                                style="line-height: 15px;margin-top: 2px;">
                                                <div class="col-md-2"></div>
                                                <div class="col-md-3"><?= htmlspecialchars($vehicleName); ?>&nbsp;</div>
                                                <div class="col-md-2">X<?= $multiplier ?></div>
                                                <div class="col-md-2">
                                                    <input type="text" class="train_transport_price form-control form-control-sm" value="<?=$price; ?>">
                                                </div>
                                                <div class="col-md-1">
                                                    <input type="text" class="train_transport_qty form-control form-control-sm" value="<?= $quantity; ?>">
                                                </div>
                                                <div class="col-md-2">
                                                    <input type="text" class="train_transport_total form-control form-control-sm" value="<?=$vehicleTotal; ?>" readonly>
                                                </div>
                                            </div>

                                            <?php
                                            $index++;
                                        endforeach;
                                        ?>
                                    </div>

                                    <?php if (!empty($trainTransportVehiclesData)): ?>
                                        <input type="hidden"
                                            id="daywiseTrainTransportData_<?= $dayNumber ?>"
                                            class="daywise-train-transport-data"
                                            data-day="<?= $dayNumber ?>"
                                            value='<?= json_encode(['day' => (int)$dayNumber, 'type' => 'train', 'vehicles' => $trainTransportVehiclesData]); ?>'>
                                    <?php endif; ?>

                                    <?php
                                    // ---- 2. TRAIN SCHEDULE (Railway Transfer) ----
                                    // Saved train data for this section
                                    $savedTrainForSection = [];
                                    if (!empty($savedTrainDataForDay)) {
                                        foreach ($savedTrainDataForDay as $st) {
                                            if (!isset($st['section']) || $st['section'] == $sectionIdx) {
                                                $savedTrainForSection[] = $st;
                                            }
                                        }
                                    }

                                    // Determine adult/child counts (same as in 'no' branch)
                                    if ($this->input->get('guide') === 'yes') {
                                        
                                        if ($route_travel_with_guide === 'yes') {
                                            $adultCount = $this->input->get('number_of_adults') + 1;
                                        } else {
                                            $adultCount = $this->input->get('number_of_adults');
                                        }
                                    } else {
                                        $adultCount = $this->input->get('number_of_adults');
                                    }
                                    $childCount = $this->input->get('number_of_child') ?? 0;

                                    $typePriceMap = [
                                        'economy_class'  => 'economy_ticket_price',
                                        'business_class' => 'ticket_price',
                                        'first_class'    => 'first_class_ticket_price',
                                        'second_class'   => 'second_class_ticket_price',
                                        'sitting'        => 'sitting_ticket_price',
                                        'vip'            => 'vip_ticket_price',
                                        'sleeper'        => 'sleeper_class_ticket_price',
                                        'coupe'          => 'coupe_class_ticket_price',
                                        'sv'             => 'sv_class_ticket_price',
                                    ];
                                    $childTypePriceMap = [
                                        'economy_class'  => 'economy__child_ticket_price',
                                        'business_class' => 'business_child_ticket_price',
                                        'first_class'    => 'first_class_child_ticket_price',
                                        'second_class'   => 'second_class_child_ticket_price',
                                        'sitting'        => 'sitting_child_ticket_price',
                                        'vip'            => 'vip_child_ticket_price',
                                        'sleeper'        => 'sleeper_class_child_ticket_price',
                                        'coupe'          => 'coupe_class_child_ticket_price',
                                        'sv'             => 'sv_class_child_ticket_price',
                                    ];

                                    $priceColumn = $typePriceMap[$ticketType] ?? null;
                                    $childPriceColumn = $childTypePriceMap[$ticketType] ?? null;

                                    $savedAdult = null;
                                    $savedChild = null;
                                    foreach ($savedTrainForSection as $st) {
                                        if (isset($st['train_id']) && $st['train_id'] == $trainId) {
                                            $passType = $st['passenger_type'] ?? 'adult';
                                            if ($passType === 'adult') {
                                                $savedAdult = $st;
                                            } elseif ($passType === 'child') {
                                                $savedChild = $st;
                                            }
                                        }
                                    }

                                    $trainGrandTotal = 0;
                                    $trainVehiclesData = [];

                                    // Adult processing
                                    if ($savedAdult) {
                                        $trainPrice = (float)($savedAdult['price'] ?? 0);
                                        $adultQty   = (int)($savedAdult['qty'] ?? $adultCount);
                                    } else {
                                        $trainPrice = $priceColumn ? ($trainSchedule->$priceColumn ?? 0) : 0;
                                        $adultQty   = $adultCount;
                                    }
                                    $trainTotal = $trainPrice * $adultQty;
                                    $trainGrandTotal += $trainTotal;

                                    $trainVehiclesData[] = [
                                        'train_id'          => $trainId,
                                        'train_name'        => $trainSchedule->train_name ?? '',
                                        'ticket_type'       => $ticketType,
                                        'ticket_type_label' => ucwords(str_replace('_', ' ', $ticketType)),
                                        'passenger_type'    => 'adult',
                                        'price'             => (float)$trainPrice,
                                        'qty'               => (int)$adultQty,
                                        'total'             => (float)$trainTotal,
                                        'section'           => $sectionIdx
                                    ];

                                    // Start train schedule HTML
