                                        ->result();
                                    foreach ($costQuery as $c) {
                                        $costs[$c->transport_id] = $c->price;
                                    }
                                    
                                    $getFrom_City = strtolower($prev_day_city == strtolower($day_city) ? $this->input->get('arrival_city') : $prev_day_city);

                                    // Fetch from train_transfer_routes table (fallback)
                                    $routeCosts = [];
                                    $routeQuery = $this->db
                                        ->where_in('transport_id', $transportIds)
                                        ->where('from_city', strtolower($getFrom_City))
                                        ->where('to_city', strtolower($day_city))
                                        ->where('valid_from <=', $list->date)
                                        ->where('valid_to >=', $list->date)
                                        ->where('status', 'active')
                                        ->get('train_transfer_routes')
                                        ->result();
                                    foreach ($routeQuery as $r) {
                                        $routeCosts[$r->transport_id] = $r->cost;
                                    }
                                    
                                    // Fetch vehicle names for all transport IDs (if not already in saved data)
                                    $vehicleNames = [];
                                    $vehicles = $this->db
                                        ->where_in('id', $transportIds)
                                        ->get('transportation')
                                        ->result();
                                    foreach ($vehicles as $v) {
                                        $vehicleNames[$v->id] = $v->vehicle_name;
                                    }
                                    ?>
                                    
                                    <div class="alert alert-dark mt-2" data-day="2" style="margin-bottom:2px !important;padding:4px;text-transform:capitalize;font-size:12px;text-align:center;">
                                        <div class="row" style="line-height: 10px;margin-top: 2px;font-weight:600;margin-bottom:6px;">
                                            <div class="col-md-2"><span style="color:#ef2100;"><i class="fa fa-car"></i> Station Transfer</span></div>
                                            <div class="col-md-3">Vehicle Name</div>
                                            <div class="col-md-2">One/Two Way</div>
                                            <div class="col-md-2">Price</div>
                                            <div class="col-md-1">Qty.</div>
                                            <div class="col-md-2">Total</div>
                                        </div>
                                        
                                        <?php
                                        $index = 0;
                                        foreach ($transportIds as $transportId) {
                                            $vehicleName = '';
                                            $price = 0;
                                            $quantity = 1;
                                            $savedVehicleFound = false;
                                            
                                            // Check saved data first
                                            foreach ($savedTrainTransportData as $savedVehicle) {
                                                if (isset($savedVehicle['transport_id']) && $savedVehicle['transport_id'] == $transportId) {
                                                    $price = (float)$savedVehicle['price'];
                                                    $quantity = (int)$savedVehicle['qty'];
                                                    $vehicleName = $savedVehicle['vehicle_name'] ?? '';
                                                    $savedVehicleFound = true;
                                                    break;
                                                }
                                            }
                                            
                                            // If not saved, get from pre-fetched data
                                            if (!$savedVehicleFound) {
                                                // Quantity from input
                                                if (isset($vehicleQuantities[$index]) && is_numeric($vehicleQuantities[$index])) {
                                                    $quantity = (int)$vehicleQuantities[$index];
                                                }
                                                
                                                // Price from transportation_costs
                                                if (isset($costs[$transportId])) {
                                                    $price = $costs[$transportId];
                                                }
                                                // Fallback to train_transfer_routes
                                                elseif (isset($routeCosts[$transportId])) {
                                                    $price = $routeCosts[$transportId];
                                                }
                                                
                                                // Vehicle name from transportation table
                                                $vehicleName = $vehicleNames[$transportId] ?? 'Vehicle';
                                            }
                                            
                                            $multiplier = 2;
                                            $isOneWay = false;
                                            if($country == 'uzbekistan'){
                                                if (!empty($train_arrival) && isset($fullDayPeriods[$transportId])) {
                                                    $arrivalTime = date('H:i:s', strtotime($train_arrival));
                                                    $departureTime = date('H:i:s', strtotime($train_departure));
                                                    foreach ($fullDayPeriods[$transportId] as $period) {
                                                        if (($arrivalTime >= $period['start'] && $arrivalTime <= $period['end']) || ($departureTime >= $period['start'] && $departureTime <= $period['end'])) {
                                                            $multiplier = 1;
                                                            $isOneWay = true;
                                                            break;
                                                        }
                                                    }
                                                }
                                            }
                                            
                                            // Calculate total for this vehicle
                                            $vehicleTotal = $price * $quantity * $multiplier;
                                            $totalTransferCost += $vehicleTotal;
                                            
                                            // Add to data array ONLY if price > 0 and name not empty
                                            if ($price >= 0 && !empty(trim($vehicleName))) {
                                                $trainTransportVehiclesData[] = [
                                                    'transport_id' => $transportId,
                                                    'vehicle_name' => trim($vehicleName),
                                                    'price' => (float)$price,
                                                    'qty' => (int)$quantity,
                                                    'total' => (float)$vehicleTotal
                                                ];
                                            }
                                            ?>
                                            
                                            <!-- Display the vehicle row (always show, even if invalid for hidden data) -->
                                            <div class="row train-transport-transfer-row" 
                                                data-day="<?php echo $key + 1; ?>" 
                                                data-transport-id="<?php echo $transportId; ?>"                        
                                                data-multiplier="<?php echo $multiplier; ?>"
                                                data-index="<?php echo $index; ?>" 
                                                style="line-height: 15px;margin-top: 2px;">
                                                <div class="col-md-2"></div>
                                                <div class="col-md-3"><?php echo htmlspecialchars($vehicleName); ?>&nbsp;</div>
                                                <div class="col-md-2">X<?php echo $multiplier; ?></div>
                                                <div class="col-md-2">
                                                    <input type="text" class="train_transport_price form-control form-control-sm" value="<?php echo $price ?>">
                                                </div>
                                                <div class="col-md-1">
                                                    <input type="text" class="train_transport_qty form-control form-control-sm" value="<?php echo $quantity; ?>">
                                                </div>
                                                <div class="col-md-2">
                                                    <input type="text" class="train_transport_total form-control form-control-sm" value="<?php echo $vehicleTotal ?>" readonly>
                                                </div>
                                            </div>
                                            
                                            <?php 
                                            $index++;
                                        }
                                        ?>
