                                            id="daywiseTrainTransportData_<?php echo $key + 1; ?>" 
                                            class="daywise-train-transport-data" 
                                            data-day="<?php echo $key + 1; ?>"
                                            value='<?php echo json_encode(['day' => (int)$key + 1, 'type' => 'train', 'vehicles' => $trainTransportVehiclesData]); ?>'>
                                    <?php endif; ?>
                                <?php endif; ?>
                            
                            <?php if ($isTrainDay && $trainSchedule): ?>
                                <?php 
                                    if($this->input->get('guide') === 'yes'){
                                        if($travel_with_guide === 'yes'){
                                            $adultCount = $this->input->get('number_of_adults') + 1 ?? 1;
                                        }else{
                                            $adultCount = $this->input->get('number_of_adults') ?? 1;
                                        }
                                    }else{
                                        $adultCount = $this->input->get('number_of_adults') ?? 1;
                                    }
                                    $childCount = $this->input->get('number_of_child') ?? 0;
                                    
                                    $savedTrainData = [];
                                    $useSavedData = true;

                                    foreach ($saved_daywise_train as $saved) {
                                        if (isset($saved['day']) && $saved['day'] == ($key + 1) && isset($saved['trains'])) {

                                            $savedTrainData = $saved['trains'];

                                            // --- Extract saved values ---
                                            $savedTrainId = null;
                                            $savedTicketType = null;
                                            $savedAdultQty = 0;
                                            $savedChildQty = 0;

                                            foreach ($savedTrainData as $train) {
                                                if (!$savedTrainId) {
                                                    $savedTrainId = $train['train_id'] ?? null;
                                                    $savedTicketType = $train['ticket_type'] ?? null;
                                                }

                                                if (($train['passenger_type'] ?? '') === 'adult') {
                                                    $savedAdultQty += (int)$train['qty'];
                                                }

                                                if (($train['passenger_type'] ?? '') === 'child') {
                                                    $savedChildQty += (int)$train['qty'];
                                                }
                                            }

                                            if (
                                                (string)$savedTrainId !== (string)$trainId ||
                                                (string)$savedTicketType !== (string)$ticketType ||
                                                (int)$savedAdultQty !== (int)$adultCount ||
                                                (int)$savedChildQty !== (int)$childCount
                                            ) {
                                                $useSavedData = false;
                                            }

                                            break;
                                        }
                                    }

                                    // Force recalculation if mismatch
                                    if (!$useSavedData) {
                                        $savedTrainData = [];
                                    }
                                    

                                    $trainGrandTotal = 0;
                                    $trainVehiclesData = [];

                                    if ($isTrainDay && $trainSchedule):
                                        $typePriceMap = [
                                            'economy_class'  => 'economy_ticket_price',
                                            'business_class' => 'ticket_price',
                                            'first_class'    => 'first_class_ticket_price',
                                            'second_class'   => 'second_class_ticket_price',
                                            'sitting'        => 'sitting_ticket_price',
                                            'vip'            => 'vip_ticket_price',
                                            'sleeper'        => 'sleeper_class_ticket_price',
                                            'coupe'          => 'coupe_class_ticket_price',
                                            'sv'             => 'sv_class_ticket_price',
                                        ];

                                        $childTypePriceMap = [
                                            'economy_class'  => 'economy__child_ticket_price',
                                            'business_class' => 'business_child_ticket_price',
                                            'first_class'    => 'first_class_child_ticket_price',
                                            'second_class'   => 'second_class_child_ticket_price',
                                            'sitting'        => 'sitting_child_ticket_price',
                                            'vip'            => 'vip_child_ticket_price',
                                            'sleeper'        => 'sleeper_class_child_ticket_price',
                                            'coupe'          => 'coupe_class_child_ticket_price',
                                            'sv'             => 'sv_class_child_ticket_price',
                                        ];

                                        $priceColumn = $typePriceMap[$ticketType] ?? null;
                                        $childPriceColumn = $childTypePriceMap[$ticketType] ?? null;

                                        // Get adult and child counts from input
                                        // $adultCount = $this->input->get('number_of_adults') ?? 1;
                                        // $childCount = $this->input->get('number_of_child') ?? 0;

                                        // --- Locate saved entries for this train (adult and child) ---
                                        $savedAdult = null;
                                        $savedChild = null;
                                        foreach ($savedTrainData as $savedTrain) {
                                            if (isset($savedTrain['train_id']) && $savedTrain['train_id'] == $trainId) {
                                                // Determine passenger type (default to 'adult' for backward compatibility)
                                                $passType = $savedTrain['passenger_type'] ?? 'adult';
                                                if ($passType === 'adult') {
                                                    $savedAdult = $savedTrain;
                                                } elseif ($passType === 'child') {
                                                    $savedChild = $savedTrain;
                                                }
                                            }
                                        }

                                        // --- ADULT PROCESSING ---
                                        if ($savedAdult) {
                                            $trainPrice = (float)($savedAdult['price'] ?? 0);
                                            $adultQty   = (int)($savedAdult['qty'] ?? $adultCount);
                                        } else {
                                            $trainPrice = $priceColumn ? ($trainSchedule->$priceColumn ?? 0) : 0;
                                            $adultQty   = $adultCount;
                                        }
                                        $trainTotal = $trainPrice * $adultQty;
                                        $trainGrandTotal += $trainTotal;

                                        // Prepare adult train data for JSON
                                        $trainVehiclesData[] = [
                                            'train_id'          => $trainId,
                                            'train_name'        => $trainSchedule->train_name ?? '',
                                            'ticket_type'       => $ticketType,
                                            'ticket_type_label' => ucwords(str_replace('_', ' ', $ticketType)),
                                            'passenger_type'    => 'adult',
                                            'price'             => (float)$trainPrice,
                                            'qty'               => (int)$adultQty,
                                            'total'             => (float)$trainTotal
                                        ];
                                        ?>

                                        <!-- Adult row -->
                                        <div class="alert alert-dark mt-2 outside-section train-section"
                                            data-day="<?= $key + 1 ?>"
                                            style="margin-bottom:2px !important;padding:4px;text-transform:capitalize;font-size:12px;text-align:center;">

                                            <div class="row" style="line-height:10px;margin-top:2px;font-weight:600;margin-bottom:2px;">
