                                                </div>
                                            </div>

                                        

                                                <div class="row train-row"
                                                    data-day="<?= $key + 1 ?>"
                                                    data-train-id="<?= $trainId ?>"
                                                    data-train-type="<?= $ticketType ?>"
                                                    data-passenger-type="adult"
                                                    data-train-total="<?= $trainTotal ?>">

                                                    <div class="col-md-3"></div>

                                                    <div class="col-md-3">
                                                        <strong><b>Train Name</b></strong><br>
                                                        <?= $trainSchedule->train_name ?><br>
                                                        <small><?= ucwords(str_replace('_',' ', $ticketType)) ?></small>
                                                    </div>

                                                    <div class="col-md-2">
                                                        <strong><b>Adult Price</b></strong>
                                                        <input type="text"
                                                            class="form-control form-control-sm train-price"
                                                            value="<?= $trainPrice ?>"
