                                                    </div>

                                                    <div class="col-md-2">
                                                        <strong><b>Adult Qty</b></strong>
                                                        <input type="text"
                                                            class="form-control form-control-sm train-qty"
                                                            value="<?= $adultQty ?>" 
                                                            readonly>
                                                    </div>

                                                    <div class="col-md-2">
                                                        <strong><b>Adult Total</b></strong>
                                                        <input type="text"
                                                            class="form-control form-control-sm train-total"
                                                            value="<?= $trainTotal ?>" 
                                                            readonly>
                                                    </div>
                                                </div>

                                            <?php if ($childCount > 0):
                                                // Collect all saved child entries for this train (multiple possible after change)
                                                $savedChildren = [];
                                                foreach ($savedTrainData as $savedTrain) {
                                                    if (isset($savedTrain['train_id']) && $savedTrain['train_id'] == $trainId) {
                                                        $passType = $savedTrain['passenger_type'] ?? 'adult';
                                                        if ($passType === 'child') {
                                                            $savedChildren[] = $savedTrain;
                                                        }
                                                    }
                                                }

                                                $childRows = [];

                                                if (!empty($savedChildren)) {
                                                    // Use saved data directly (backward compatible)
                                                    foreach ($savedChildren as $savedChild) {
                                                        $childRows[] = [
                                                            'label' => $savedChild['ticket_type_label'] ?? 'Child',
                                                            'price' => (float)($savedChild['price'] ?? 0),
                                                            'qty'   => (int)($savedChild['qty'] ?? 0),
                                                            'total' => (float)($savedChild['total'] ?? 0)
                                                        ];
                                                    }
                                                } else {
                                                    $ticketType = str_replace(['_class'], '', $ticketType);
                                                    // No saved child data – compute fresh
                                                    $flagColumn = $ticketType . '_child_age';
                                                    $useAgeBased = isset($trainSchedule->$flagColumn) && strtolower($trainSchedule->$flagColumn) == 'yes';

                                                    if ($useAgeBased) {
                                                        // Age‑based pricing enabled
                                                        $inputAges = $this->input->get('child_ages');
                                                        if (!empty($inputAges)) {
                                                            if (is_array($inputAges)) {
                                                                $ages = array_map('intval', $inputAges);
                                                            } else {
                                                                // Assume comma-separated string
                                                                $ages = array_map('intval', explode(',', $inputAges));
                                                            }
                                                        }else{
                                                                $ages = [];
                                                        }
                                                        // Fetch all age‑price records for this train schedule and class type
                                                        $agePriceRecords = $this->db
                                                            ->select('id, age_from, age_to, price')
                                                            ->from('train_child_age_price')
                                                            ->where('train_schedule_id', $trainId)
                                                            ->where('class_type', $ticketType)
                                                            ->where('status', 'active')
                                                            ->get()
                                                            ->result();

                                                        // Group children by the age range they fall into
                                                        $groups = [];
                                                        for ($d = 0; $d < $childCount; $d++) {
                                                            $childAge = $ages[$d % count($ages)];
                                                            $matchedRecord = null;
                                                            foreach ($agePriceRecords as $record) {
                                                                if ($childAge >= $record->age_from && $childAge <= $record->age_to) {
                                                                    $matchedRecord = $record;
                                                                    break;
                                                                }
                                                            }

                                                            if ($matchedRecord) {
                                                                $groupKey = $matchedRecord->id;
                                                                if (!isset($groups[$groupKey])) {
                                                                    $groups[$groupKey] = [
                                                                        'price' => (float)$matchedRecord->price,
                                                                        'label' => $matchedRecord->age_from . '-' . $matchedRecord->age_to,
                                                                        'qty'   => 0,
                                                                        'total' => 0
                                                                    ];
                                                                }
                                                                $groups[$groupKey]['qty']++;
                                                                $groups[$groupKey]['total'] += $matchedRecord->price;
                                                            } else {
                                                                $groupKey = 'no_range';  
                                                                if (!isset($groups[$groupKey])) {
                                                                    $groups[$groupKey] = [
                                                                        'price' => 0,
                                                                        'label' => 'Other (no price)',
                                                                        'qty'   => 0,
                                                                        'total' => 0
                                                                    ];
                                                                }
                                                                $groups[$groupKey]['qty']++;
                                                            }
                                                        }

                                                        // Convert groups to child rows
                                                        foreach ($groups as $group) {
                                                            $childRows[] = [
                                                                'label' => 'Child (' . $group['label'] . ')',
                                                                'price' => $group['price'],
                                                                'qty'   => $group['qty'],
                                                                'total' => $group['total']
                                                            ];
                                                        }
                                                    } else {
                                                        // Use fixed child price column
                                                        $fixedPrice = $childPriceColumn ? ($trainSchedule->$childPriceColumn ?? 0) : 0;
                                                        $childRows[] = [
                                                            'label' => 'Child',
                                                            'price' => (float)$fixedPrice,
                                                            'qty'   => (int)$childCount,
                                                            'total' => (float)$fixedPrice * $childCount
                                                        ];
                                                    }
                                                }

                                                if (!empty($childRows)) { ?>
                                                    <div class="row">
                                                        <div class="col-md-3"></div>
                                                        <div class="col-md-3"><strong><b>Age Range</b></strong></div>
                                                        <div class="col-md-2"><strong><b>Price</b></strong></div>
                                                        <div class="col-md-2"><strong><b>Qty</b></strong></div>
                                                        <div class="col-md-2"><strong><b>Total</b></strong></div>
                                                    <?php
                                                }

                                                // Now output each child row and accumulate totals
                                                foreach ($childRows as $row) {
                                                    $trainGrandTotal += $row['total'];
                                                    $trainVehiclesData[] = [
                                                        'train_id'          => $trainId,
                                                        'train_name'        => $trainSchedule->train_name ?? '',
                                                        'ticket_type'       => $ticketType,
                                                        'ticket_type_label' => $row['label'],
                                                        'passenger_type'    => 'child',
                                                        'price'             => $row['price'],
                                                        'qty'               => $row['qty'],
                                                        'total'             => $row['total']
                                                    ];
                                                    ?>
                                                    <!-- Child row HTML (one per group) -->
                                                        <div class="row train-row mt-2"
                                                            data-day="<?= $key + 1 ?>"
                                                            data-train-id="<?= $trainId ?>"
                                                            data-train-name="<?= htmlspecialchars($trainSchedule->train_name) ?>"
                                                            data-train-type="<?= $ticketType ?>"
                                                            data-passenger-type="child"
                                                            data-label="<?= htmlspecialchars($row['label']) ?>"
                                                            data-train-total="<?= $row['total'] ?>">

                                                            <div class="col-md-3"></div>
                                                            <div class="col-md-3"><?= htmlspecialchars($row['label']) ?></div>
                                                            <div class="col-md-2">
                                                                <input type="text"
                                                                    class="form-control form-control-sm train-child-price"
                                                                    value="<?= $row['price'] ?>"
                                                                    data-original-price="<?= $row['price'] ?>">
                                                            </div>
                                                            <div class="col-md-2">
                                                                <input type="text"
                                                                    class="form-control form-control-sm train-child-qty"
                                                                    value="<?= $row['qty'] ?>" 
                                                                    readonly>
                                                            </div>
                                                            <div class="col-md-2">
                                                                <input type="text"
                                                                    class="form-control form-control-sm train-child-total"
                                                                    value="<?= $row['total']?>" 
                                                                    readonly>
                                                            </div>
                                                        </div>
                                                    <?php
                                                }
                                            endif; ?>
                                            </div>
                                            
                                        <!--</div>-->

                                        <!-- Hidden input for daywise train data JSON (includes both adult and child) -->
                                        <?php if (!empty($trainVehiclesData)): ?>
                                            <input type="hidden" 
                                                id="daywiseTrainData_<?php echo $key + 1; ?>" 
                                                class="daywise-train-data" 
                                                data-day="<?php echo $key + 1; ?>"
