                                                        $hasRealSightseeing = false;

                                                        if (!empty($itinerary_sites_id[$lastIndex])) {

                                                            foreach ($itinerary_sites_id[$lastIndex] as $sId) {

                                                                if (empty($sId)) continue;

                                                                // ❌ skip misc / transfer without cost
                                                                $whereCheck = 'sites.id=' . $sId . ' 
                                                                    AND NOT ((category="miscellaneous" OR category="transfers") 
                                                                    AND miscellaneous_cost="withoutcost")';

                                                                $checkSite = $this->common_model->get_data('sites', '', '', '*', $whereCheck);

                                                                if (!empty($checkSite)) {
                                                                    $hasRealSightseeing = true;
                                                                    break;
                                                                }
                                                            }
                                                        }

                                                        // ==============================
                                                        // ✅ CHECK OVERNIGHT FLOW
                                                        // ==============================
                                                        $isInOvernightFlow = false;

                                                        if (!empty($transferByDay)) {

                                                            ksort($transferByDay); // ensure correct order

                                                            foreach ($transferByDay as $tDay => $tData) {

                                                                if ($tDay >= $currentDay) break;

                                                                // ✅ ONLY overnight allowed
                                                                if (isset($tData['overnight_type']) && $tData['overnight_type'] === 'overnight') {

                                                                    $isInOvernightFlow = true;

                                                                }
                                                                // ❌ drop_off OR anything → break flow
                                                                elseif (isset($tData['overnight_type']) && $tData['overnight_type'] === 'drop_off') {

                                                                    $isInOvernightFlow = false;

                                                                } else {

                                                                    $isInOvernightFlow = false;
