                                            // First night bhi empty hai aur koi previous
                                            // category available nahi hai
                                            // echo ">>> NO PREVIOUS CATEGORY FOUND <<<\n";
                                            // echo "HOTEL ID: ".$hotel_id."\n";
                                            // echo "NIGHT: ".$night."\n";
                                            // echo "------------------------\n";

                                            continue;
                                        }
                                    }


                                    // ============================================================
                                    // SAVE VALID DATA
                                    // NEXT EMPTY NIGHT IS DATA KO COPY KAREGI
                                    // ============================================================

                                    $last_categories = $current_categories;
                                    $last_prices = $current_prices;


                                    // ============================================================
                                    // CREATE FIRST GROUP
                                    // ============================================================

                                    if(empty($current_group)) {

                                        $current_group = [
                                            'nights' => [$night],
                                            'categories' => $current_categories,
                                            'prices' => $current_prices,
                                            'start_night' => $night
                                        ];

                                    } else {

                                        // Compare categories AND prices INLINE
                                        $cats1 = $current_categories;
                                        $cats2 = $current_group['categories'];

                                        $prices1 = $current_prices;
                                        $prices2 = $current_group['prices'];

                                        // ========================================================
                                        // COMPARE CATEGORIES
                                        // ========================================================

                                        $categories_same = false;

                                        if(empty($cats1) && empty($cats2)) {

                                            $categories_same = true;

                                        } elseif(empty($cats1) || empty($cats2)) {

                                            $categories_same = false;

                                        } else {

                                            $cats1_copy = $cats1;
                                            $cats2_copy = $cats2;

                                            sort($cats1_copy);
                                            sort($cats2_copy);

                                            $categories_same = ($cats1_copy == $cats2_copy);
                                        }


                                        $are_same = $categories_same;


                                        // ========================================================
                                        // IF CATEGORIES SAME → COMPARE PRICES
                                        // ========================================================

                                        if($categories_same) {

                                            $prices_same = false;

                                            if(empty($prices1) && empty($prices2)) {

                                                $prices_same = true;

                                            } elseif(empty($prices1) || empty($prices2)) {

                                                $prices_same = false;

                                            } else {

                                                $sorted_prices1 = [];
                                                $sorted_prices2 = [];


                                                foreach($prices1 as $key => $price_array1) {

                                                    $sorted1 = [];

                                                    if(is_array($price_array1)) {

                                                        foreach($price_array1 as $inner_array1) {

                                                            if(is_array($inner_array1)) {

                                                                sort($inner_array1);
                                                                $sorted1[] = $inner_array1;

                                                            } else {

                                                                $sorted1[] = $inner_array1;
                                                            }
                                                        }

                                                        sort($sorted1);

                                                    } else {

                                                        $sorted1[] = $price_array1;
                                                    }

                                                    $sorted_prices1[$key] = $sorted1;
                                                }


                                                foreach($prices2 as $key => $price_array2) {

                                                    $sorted2 = [];

                                                    if(is_array($price_array2)) {

                                                        foreach($price_array2 as $inner_array2) {

                                                            if(is_array($inner_array2)) {

                                                                sort($inner_array2);
                                                                $sorted2[] = $inner_array2;

                                                            } else {

                                                                $sorted2[] = $inner_array2;
                                                            }
                                                        }

                                                        sort($sorted2);

                                                    } else {

                                                        $sorted2[] = $price_array2;
                                                    }

                                                    $sorted_prices2[$key] = $sorted2;
                                                }


                                                $prices_same =
                                                    (json_encode($sorted_prices1) == json_encode($sorted_prices2));
                                            }

                                            $are_same = $prices_same;
                                        }


                                        // ========================================================
                                        // SAME DATA → SAME GROUP
                                        // ========================================================

                                        if($are_same) {

                                            $current_group['nights'][] = $night;

                                        } else {

                                            // Different category/price
                                            $category_groups[] = $current_group;

                                            $current_group = [
                                                'nights' => [$night],
                                                'categories' => $current_categories,
                                                'prices' => $current_prices,
                                                'start_night' => $night
                                            ];
                                        }
                                    }

                                    
                                    if(!empty($current_categories)) {
                                        $last_categories = $current_categories;
                                        $last_prices = $current_prices;
                                    }
                                }
                                
                                if(!empty($current_group)) {
                                    $category_groups[] = $current_group;
                                }
                                // ---pj----
                                
                                $weekday_group = null;
                                $weekend_group = null;

                                foreach ($category_groups as $group) {

                                    if (empty($group['nights'])) {
                                        continue;
                                    }

                                    $group_weekday_nights = [];
                                    $group_weekend_nights = [];

                                    foreach ($group['nights'] as $group_night) {

                                        $night_date = date(
                                            'Y-m-d',
                                            strtotime(
                                                $details->check_in_date .
                                                ' +' . ($group_night - 1) . ' days'
                                            )
                                        );

                                        $day_name = strtolower(
                                            date('l', strtotime($night_date))
                                        );

                                        $is_weekend = false;

                                        // Get hotel weekend configuration
                                        $weekend_data = $this->common_model->get_data(
                                            'hotel_weekend',
                                            '',
                                            '',
                                            '*',
                                            'hotel_id = ' . (int)$hotel_id . ' AND status = 1',
                                            '',
                                            false
                                        );

                                        if (!empty($weekend_data)) {

                                            foreach ($weekend_data as $weekend_row) {

                                                $weekends = array_map(
                                                    'trim',
                                                    array_map(
                                                        'strtolower',
                                                        explode(',', $weekend_row->weekends)
                                                    )
                                                );

                                                if (in_array($day_name, $weekends)) {

                                                    $is_weekend = true;
                                                    break;
                                                }
                                            }
                                        }

                                        if ($is_weekend) {

                                            $group_weekend_nights[] = $group_night;

                                        } else {

                                            $group_weekday_nights[] = $group_night;
                                        }
                                    }


                                    // ========================================================
                                    // MERGE ALL WEEKDAY NIGHTS
                                    // ========================================================

                                    if (!empty($group_weekday_nights)) {

                                        if ($weekday_group === null) {

                                            $weekday_group = $group;

                                            $weekday_group['nights'] = [];

                                        }

                                        $weekday_group['nights'] = array_merge(
                                            $weekday_group['nights'],
                                            $group_weekday_nights
                                        );
                                    }


                                    // ========================================================
                                    // MERGE ALL WEEKEND NIGHTS
                                    // ========================================================

                                    if (!empty($group_weekend_nights)) {

                                        if ($weekend_group === null) {

                                            $weekend_group = $group;

                                            $weekend_group['nights'] = [];

                                        }

                                        $weekend_group['nights'] = array_merge(
                                            $weekend_group['nights'],
                                            $group_weekend_nights
                                        );
                                    }
                                }


                                // ============================================================
                                // SORT NIGHTS
                                // ============================================================

                                $merged_category_groups = [];

                                if ($weekday_group !== null) {

                                    $weekday_group['nights'] = array_values(
                                        array_unique($weekday_group['nights'])
                                    );

                                    sort($weekday_group['nights']);

                                    $weekday_group['start_night'] =
                                        min($weekday_group['nights']);

                                    $weekday_group['end_night'] =
                                        max($weekday_group['nights']);

                                    $merged_category_groups[] = $weekday_group;
                                }


                                if ($weekend_group !== null) {

                                    $weekend_group['nights'] = array_values(
                                        array_unique($weekend_group['nights'])
                                    );

                                    sort($weekend_group['nights']);

                                    $weekend_group['start_night'] =
                                        min($weekend_group['nights']);

                                    $weekend_group['end_night'] =
                                        max($weekend_group['nights']);

                                    $merged_category_groups[] = $weekend_group;
                                }


                                // ============================================================
                                // IMPORTANT
                                // Replace old groups with merged groups
                                // ============================================================

                                $category_groups = $merged_category_groups;
                                // ---pj---
                                // Check if this hotel has the same price for ALL nights it appears
                                if(count($category_groups) == 1) {
                                    $group = $category_groups[0];
                                    
                                    // Check if this hotel appears for all nights (1 to number_of_nights)
                                    $expected_nights = range(1, $number_of_nights);
                                    $hasAllNights = empty(array_diff($expected_nights, $group['nights']));
                                    
                                    if($hasAllNights) {
                                        $hotels_with_same_price_all_nights[$hotel_id] = true;
                                    }
                                }
                                
                                // Create groups for display
                                foreach($category_groups as $group_index => $group) {
                                    // echo'<pre>';print_r($group);die;
                                    if(empty($group['nights']) || empty($group['categories'])) continue;
                                    
                                    $group_nights = $group['nights'];
                                    $night_count = count($group_nights);
                                    $start_night = min($group_nights);
                                    $end_night = max($group_nights);
                                    // print_r($night_count);die;
                                    // Check for early checkin and late checkout
                                    $hasEarlyCheckin = in_array($hotel_id, $earlyCheckinHotels) && $start_night == 1;
                                    $hasLateCheckout = in_array($hotel_id, $lateCheckoutHotels) && $end_night == $number_of_nights;
                                    
                                    // Adjust night count for early checkin/late checkout - ADD FULL NIGHT FOR EACH
                                    $adjusted_night_count = $night_count;
                                    // echo'<pre>';print_r($adjusted_night_count);die;
                                    $extra_nights_text = '';
                                    
                                    if ($hasEarlyCheckin) {
                                        $adjusted_night_count += 1; // Add full night for early checkin
                                        $extra_nights_text .= ' + Early Checkin';
                                    }
                                    if ($hasLateCheckout) {
                                        $adjusted_night_count += 1; // Add full night for late checkout
                                        $extra_nights_text .= ' + Late Checkout';
                                    }
                                    
                                    // Prepare nights array with special indicators for early checkin/late checkout
                                    $nights_with_special = $group_nights;
                                    
                                    if ($hasEarlyCheckin) {
                                        // Add 0 for early checkin at the beginning
                                        array_unshift($nights_with_special, 0);
                                    }
                                    if ($hasLateCheckout) {
                                        // Add -1 for late checkout at the end
                                        $nights_with_special[] = -1;
                                    }
                                    
                                    $all_hotel_groups[] = [
                                        'hotel_id' => $hotel_id,
                                        'hotel_name' => $hotel_name,
                                        'hotel_city' => $hotel_city,
                                        'nights' => $group_nights,
                                        'nights_with_special' => $nights_with_special,
                                        'night_count' => $night_count,
                                        'adjusted_night_count' => $adjusted_night_count,
                                        'start_night' => $start_night,
                                        'end_night' => $end_night,
                                        'categories' => $group['categories'],
                                        'prices' => $group['prices'], // Store prices in group
                                        'first_night' => $group_nights[0],
                                        'isOutsideDestination' => (strtolower($hotel_details_cache[$hotel_id]['destination']) !== strtolower($main_arrival_city)),
                                        'sort_key' => $hotel_name . '_' . $start_night,
                                        'hasEarlyCheckin' => $hasEarlyCheckin,
                                        'hasLateCheckout' => $hasLateCheckout,
                                        'extra_nights_text' => $extra_nights_text,
                                        'has_same_price_all_nights' => isset($hotels_with_same_price_all_nights[$hotel_id])
                                    ];
                                }
                            }
                            
                            // ====== NEW NIGHT-WISE PROCESSING ======
                            // Create array to organize hotels by night
                            $hotels_by_night = [];
                            
                            // Initialize array for all nights
                            for ($night = 1; $night <= $number_of_nights; $night++) {
                                $hotels_by_night[$night] = [];
                            }
                            
                            // Get selection order from night 1
                            $selection_order_night1 = [];
                            $night1_hotels = $this->input->get('hdn_night_1_'.str_replace(' ', '_', strtolower($category)).'_ids');
                            if (!empty($night1_hotels)) {
                                foreach ($night1_hotels as $hotel_id) {
                                    if ($hotel_id != '' && !in_array($hotel_id, $selection_order_night1)) {
                                        $selection_order_night1[] = $hotel_id;
                                    }
                                }
                            }
                            
                            // Process each night separately to organize hotels
                            for ($night = 1; $night <= $number_of_nights; $night++) {
                                $hdn_hotel_ids = $this->input->get('hdn_night_'.$night.'_'.str_replace(' ', '_', strtolower($category)).'_ids');
                                
                                if (!empty($hdn_hotel_ids)) {
                                    // Sort hotels by selection order from night 1
                                    $sorted_hotel_ids = [];
                                    
                                    // First, add hotels in selection order
                                    foreach ($selection_order_night1 as $ordered_hotel_id) {
                                        if (in_array($ordered_hotel_id, $hdn_hotel_ids)) {
                                            $sorted_hotel_ids[] = $ordered_hotel_id;
                                        }
                                    }
                                    
                                    // Then add any remaining hotels not in selection order
                                    foreach ($hdn_hotel_ids as $hotel_id) {
                                        if ($hotel_id == '0' || $hotel_id == 0) {
                                            $sorted_hotel_ids[] = $hotel_id;
                                        } else {
                                            if (!in_array($hotel_id, $selection_order_night1) && !in_array($hotel_id, $sorted_hotel_ids)) {
                                                $sorted_hotel_ids[] = $hotel_id;
                                            }
                                        }
                                    }
                                    
                                    // Store sorted hotels for this night
                                    $hotels_by_night[$night] = $sorted_hotel_ids;
                                }
                            }
                            
                            // Get total unique hotels count for pricing logic
                            $total_unique_hotels_in_category = count($all_category_hotel_ids);
                            
                            // Check if ALL hotels have same price for all nights
                            $all_hotels_same_price = true;

                            $category_any_hotel_has_different_prices = false;

                            if ($total_unique_hotels_in_category > 0) {
                                foreach($all_category_hotel_ids as $check_hotel_id) {
                                    if (!isset($hotels_with_same_price_all_nights[$check_hotel_id])) {
                                        $all_hotels_same_price = false;
                                        $category_any_hotel_has_different_prices = true;
                                        $global_any_hotel_has_different_prices = true; // Update global flag
                                        break;
                                    }
                                }
                            }
                            
                            // Now create quotation_hotel_details in NIGHT-WISE order
                            $category_quotation_hotel_details = [];
                            
                            // Process each night
                            for ($night = 1; $night <= $number_of_nights; $night++) {
                                if (empty($hotels_by_night[$night])) continue;
                                
                                // For each hotel in this night
                                foreach ($hotels_by_night[$night] as $hotel_id) {
                                    // FIX: Don't skip hotel_id = 0, but handle it differently
                                    if ($hotel_id == '' || !isset($hotel_details_cache[$hotel_id])) continue;
                                    
                                    $hotel_name = $hotel_details_cache[$hotel_id]['name'];
                                    $hotel_city = $hotel_details_cache[$hotel_id]['city'];
                                    
                                    // Check if this hotel has same price for all nights
                                    $has_same_price_all_nights = isset($hotels_with_same_price_all_nights[$hotel_id]);
                                    
                                    // Determine if we should add this hotel for this night
                                    $should_add = true;
                                    
                                    // CASE C: Single hotel, same price all nights → Only add for Night 1
                                    if ($total_unique_hotels_in_category == 1 && $has_same_price_all_nights && $night > 1) {
                                        $should_add = false;
                                    }
                                    // CASE A: Multiple hotels, ALL have same price → Only add for Night 1
                                    else if ($total_unique_hotels_in_category > 1 && $all_hotels_same_price && $night > 1) {
                                        $should_add = false;
                                    }
                                    // CASE B & D: Add for all nights
                                    
                                    if (!$should_add) {
                                        continue;
                                    }
                                    
                                    // Get room details for this specific night
                                    $hotel_room_details = [];
                                    $current_categories = $this->input->get('night_'.$night.'_category_ids_'.$hotel_id);
                                    
                                    // FIX: For hotel_id = 0, we don't have categories or prices
                                    if ($hotel_id == '0' || $hotel_id == 0) {
                                        // For hotel_id = 0, create empty room details
                                        $hotel_room_details = '[]';
                                    } 
                                    else if(!empty($current_categories)) {
                                        foreach($current_categories as $c) {
                                            $category_arr = explode('_', $c);
                                            $room_name = $category_arr[1];
                                            
                                            // Get prices for this category
                                            $prices_key = 'night_'.$night.'_'.$category_arr[0].'_'.$hotel_id.'_hotel_prices';
                                            $price_data = $this->input->get($prices_key);
                                            
                                            if(!empty($price_data)) {
                                                $room_details = [];
                                                foreach($price_data as $price_array) {
                                                    $room_types = [];
                                                    foreach($price_array as $pr) {
                                                        $room_types[] = $pr;
                                                    }
                                                    
                                                    $room_details[] = [
                                                        'room_type' => $room_types,
                                                        'room_count' => ''
                                                    ];
                                                }
                                                
                                                $hotel_room_details[$category_arr[0].'_'.$room_name] = $room_details;
                                            }
                                        }
                                    } else {
                                        // If no categories for this specific night, try to find from night 1
                                        $current_categories = $this->input->get('night_1_category_ids_'.$hotel_id);
                                        
                                        if(!empty($current_categories)) {
                                            foreach($current_categories as $c) {
                                                $category_arr = explode('_', $c);
                                                $room_name = $category_arr[1];
                                                
                                                // Get prices from night 1
                                                $prices_key = 'night_1_'.$category_arr[0].'_'.$hotel_id.'_hotel_prices';
                                                $price_data = $this->input->get($prices_key);
                                                
                                                if(!empty($price_data)) {
                                                    $room_details = [];
                                                    foreach($price_data as $price_array) {
                                                        $room_types = [];
                                                        foreach($price_array as $pr) {
                                                            $room_types[] = $pr;
                                                        }
                                                        
                                                        $room_details[] = [
                                                            'room_type' => $room_types,
                                                            'room_count' => ''
                                                        ];
                                                    }
                                                    
                                                    $hotel_room_details[$category_arr[0].'_'.$room_name] = $room_details;
                                                }
                                            }
                                        }
                                    }
                                    
                                    // Add to quotation_hotel_details
                                    // FIX: Encode hotel_room_details properly
                                    $category_quotation_hotel_details[] = [
                                        'hotel_category' => $category,
                                        'night' => $night,
                                        'hotel_name' => $hotel_name,
                                        'hotel_city' => $hotel_city,
                                        'hotel_id' => $hotel_id,
                                        'hotel_room_details' => (is_array($hotel_room_details) && !empty($hotel_room_details)) ? 
                                                                json_encode($hotel_room_details) : $hotel_room_details
                                    ];
                                }
                            }
                            
                            // Merge with main array
                            $quotation_hotel_details = array_merge($quotation_hotel_details, $category_quotation_hotel_details);
                            // echo '<prev'; print_r($quotation_hotel_details); echo '</prev>';
                            // Sort groups for display by selection order
                            $sorted_hotel_groups = [];
                            foreach($selection_order_night1 as $hotel_id) {
                                foreach($all_hotel_groups as $group) {
                                    if ($group['hotel_id'] == $hotel_id) {
                                        $sorted_hotel_groups[] = $group;
                                    }
                                }
                            }
                            
                            // Add any remaining groups not in selection order
                            foreach($all_hotel_groups as $group) {
                                if (!in_array($group['hotel_id'], $selection_order_night1)) {
                                    $sorted_hotel_groups[] = $group;
                                }
                            }
                            
                            $all_hotel_groups = $sorted_hotel_groups;
                            
                            // Distribute groups across rows of 3
                            $rows = [];
                            $current_row = [];
                            foreach($all_hotel_groups as $group) {
                                $current_row[] = $group;
                                
                                if(count($current_row) == 3) {
                                    $rows[] = $current_row;
                                    $current_row = [];
                                }
                            }
                            
                            // Add remaining groups if any
                            if(!empty($current_row)) {
                                $rows[] = $current_row;
                            }
                            
                            // Display each row
                            foreach($rows as $row_index => $row_groups) {
                                ?>
                                <div class="row mb-3">
                                    <?php
                                    foreach($row_groups as $group_index => $group) {
                                        $hotel_id = $group['hotel_id'];
                                        $nights_array = $group['nights'];
                                        $nights_with_special = $group['nights_with_special'];
                                        $night_count = $group['night_count'];
                                        $adjusted_night_count = $group['adjusted_night_count'];
                                        $start_night = $group['start_night'];
                                        $end_night = $group['end_night'];
                                        $first_night = $group['first_night'];
                                        $hasEarlyCheckin = $group['hasEarlyCheckin'];
                                        $hasLateCheckout = $group['hasLateCheckout'];
                                        $extra_nights_text = $group['extra_nights_text'];
                                        
                                        // Night text for display
                                    // =====================================================
                                        // DISPLAY SELECTED NIGHTS
                                        // =====================================================

                                        $night_text_display = '';

                                        if (!empty($nights_array)) {

                                            $display_nights = array_map('intval', $nights_array);
                                            sort($display_nights);

                                            if (count($display_nights) == 1) {

                                                $night_text_display = 'Night ' . $display_nights[0];

                                            } else {

                                                // Check whether nights are continuous
                                                $is_continuous = true;

                                                for ($i = 1; $i < count($display_nights); $i++) {
                                                    if ($display_nights[$i] != $display_nights[$i - 1] + 1) {
                                                        $is_continuous = false;
                                                        break;
                                                    }
                                                }

                                                if ($is_continuous) {

                                                    $night_text_display =
                                                        'Nights ' . $display_nights[0] .
                                                        ' to ' . end($display_nights);

                                                } else {

                                                    $night_text_display =
                                                        'Nights ' . implode(', ', $display_nights);
                                                }
                                            }
                                        }

                                        // =====================================================
                                        // FINAL DISPLAY
                                        // =====================================================

                                        $display_text =
                                            $night_text_display .
                                            $extra_nights_text .
                                            ' (' . $adjusted_night_count . ' nights)';
                                        
                                        // Add extra nights text for early checkin/late checkout
                                        // $display_text = $night_text_display .''. $extra_nights_text .' (' . $adjusted_night_count . ' nights)' ;
                                        
                                        $grand_total = 0;
                                        
                                        // FIX: Check if this is hotel_id = 0
                                        if ($hotel_id == '0' || $hotel_id == 0) {
                                            ?>
                                            <!-- Card for No Hotel Selected -->
                                            <!-- <div class="col-md-4 mb-1 mt-2">
                                                <div class="card h-100" style="border:2px solid #020202ff;">
                                                    <div class="card-header bg-warning text-white text-center">
                                                        <h4>No Hotel Selected</h4>
                                                        <small style="font-size:12px;"><?php echo $display_text; ?></small>
                                                    </div>
                                                    <div class="card m-2 p-3 text-center">
                                                        <p><i class="fa fa-hotel fa-2x text-muted"></i></p>
                                                        <p class="text-muted">No hotel was selected for this option.</p>
                                                        <p class="text-muted small">Hotel ID: 0</p>
                                                    </div>
                                                </div>
                                            </div> -->
                                            <?php
                                        } else {
                                            ?>
                                            <!-- Card for Hotel Group -->
                                            <div class="col-md-4 mb-1 mt-2">
                                                <div class="card h-100" style="border:2px solid #020202ff;">
                                                    <div class="card-header bg-info text-white text-center">
                                                        <h4><?php echo ucfirst($group['hotel_name']); ?></h4>
                                                        <small style="font-size:12px;"><?php echo $display_text; ?></small>
                                                    </div>
                                                    <div class="card m-2">
                                                        <?php   
                                                            foreach($group['categories'] AS $c) {
                                                                $category_arr = explode('_', $c);
                                                                
