                                                $site_ids_str = implode(',', $filtered);
                                                $where2 = "sites.id IN ($site_ids_str) AND (category='miscellaneous' OR category='transfers') AND miscellaneous_cost='withoutcost'";
                                                $matching_sites = $this->common_model->get_data('sites', '', '', '*', $where2, '', '', '');
                                                $matching_ids = [];
                                                foreach ($matching_sites as $site) {
                                                    $matching_ids[] = $site->id;
                                                }
                                                $non_matching_ids = array_diff($filtered, $matching_ids);
                                                if (count($non_matching_ids) == 0) {
                                                    $total_guest = (int)$this->input->get('number_of_child');
                                                    $bottle = $total_guest * 2;
                                                } else {
                                                    $bottle = 0;
                                                }
                                            }
                                        }

                                        // --------------------------------------------------------------
                                        // 2. Retrieve child ages and number of nights
                                        // --------------------------------------------------------------
                                        $child_ages = $this->input->get('child_ages');
                                        if (is_string($child_ages) && !empty($child_ages)) {
                                            $decoded = json_decode($child_ages, true);
                                            if (is_array($decoded)) {
                                                $child_ages = $decoded;
                                            } else {
                                                $child_ages = array_map('intval', explode(',', $child_ages));
                                            }
                                        } elseif (!is_array($child_ages)) {
                                            $child_ages = [];
                                        }
                                        $expected_child_count = (int)$this->input->get('number_of_child');
                                        if (count($child_ages) !== $expected_child_count) {
                                            $child_ages = []; // disable age-based pricing if ages mismatch
                                        }
                                        $number_of_nights = (int)$this->input->get('number_of_nights') + 1; // get nights from request

                                        // --------------------------------------------------------------
                                        // 3. Get mandatory services IDs from request
                                        // --------------------------------------------------------------
                                        $child_mandatory_services_ids = $this->input->get('child_hdn_mandatory_services_ids'); // array of auxiliary_service_id
                                        $service_names = $this->input->get('child_hdn_mandatory_services'); // array of "Name_|_Price"

                                        if (!empty($child_mandatory_services_ids) && is_array($child_mandatory_services_ids)) {
                                            // --------------------------------------------------------------
                                            // 4. Fetch auxiliary_miscellaneous records (includes quantity, cost_by, with_age)
                                            // --------------------------------------------------------------
                                            $this->db->where_in('id', $child_mandatory_services_ids);
                                            $aux_services = $this->db->get('auxiliary_miscellaneous')->result();
                                            $aux_map = [];
                                            foreach ($aux_services as $aux) {
                                                $aux_map[$aux->id] = $aux;
                                            }

                                            // --------------------------------------------------------------
                                            // 5. Fetch age-based pricing rules for services with with_age = 'yes'
                                            // --------------------------------------------------------------
                                            $age_price_rules = [];
                                            $services_with_age = [];
                                            foreach ($child_mandatory_services_ids as $aux_id) {
                                                if (isset($aux_map[$aux_id]) && $aux_map[$aux_id]->with_age == 'yes') {
                                                    $services_with_age[] = $aux_id;
                                                }
                                            }
                                            if (!empty($services_with_age)) {
                                                $this->db->where_in('auxiliary_service_id', $services_with_age);
                                                $this->db->where('status', 'active');
                                                $rules = $this->db->get('mandatory_services_child_age_cost')->result();
                                                foreach ($rules as $rule) {
                                                    $age_price_rules[$rule->auxiliary_service_id][] = $rule;
                                                }
                                            }

                                            // --------------------------------------------------------------
                                            // 6. Build display rows (using actual quantity from DB, not pre-multiplied input)
                                            // --------------------------------------------------------------
                                            $display_rows = [];
                                            $total_services = count($child_mandatory_services_ids);
                                            $grand_total = 0;

                                            foreach ($child_mandatory_services_ids as $idx => $aux_id) {
                                                $aux = isset($aux_map[$aux_id]) ? $aux_map[$aux_id] : null;
                                                if (!$aux) continue;

                                                // --- Get service name and default (fallback) price from request ---
                                                $service_name = '';
                                                $default_price = 0;
                                                if (isset($service_names[$idx])) {
                                                    $parts = explode('_|_', $service_names[$idx]);
                                                    $service_name = $parts[0];
                                                    $default_price = isset($parts[1]) ? (float)$parts[1] : 0;
                                                }

                                                // --- Base quantity per child per day from auxiliary table ---
                                                $base_quantity = (int)$aux->quantity; // e.g., 2 bottles
                                                $cost_by = isset($aux->cost_by) ? strtolower($aux->cost_by) : 'entire_trip';
                                                $group_type = isset($aux->group_type) ? strtolower($aux->group_type) : 'per_person';

                                                // Calculate quantity per child for the whole trip
                                                $per_child_quantity = $base_quantity;
                                                if ($cost_by === 'per_day') {
                                                    $per_child_quantity *= $number_of_nights;
                                                }
                                                // For per_person, we will multiply by child count later

                                                $total_children = count($child_ages);
                                                $use_age_based = ($aux->with_age == 'yes' && !empty($child_ages) && !empty($age_price_rules[$aux_id]));

                                                if ($use_age_based) {
                                                    // ----- Age‑based: group children by age range -----
                                                    // $rules = $age_price_rules[$aux_id];
                                                    // usort($rules, function($a, $b) { return $a->agefrom - $b->agefrom; });

                                                    // Filter rules: only keep those with a valid numeric amount (not empty, not "NA", >0 if desired)
                                                    $valid_rules = array_filter($age_price_rules[$aux_id], function($rule) {
                                                        $amount = trim($rule->amount ?? '');
                                                        return is_numeric($amount) && $amount !== '' && $amount !== 'NA' && (float)$amount > 0;
                                                    });
                                                    if (empty($valid_rules)) {
                                                        continue; // skip this entire service – no valid price ranges
                                                    }
                                                    usort($valid_rules, function($a, $b) { return $a->agefrom - $b->agefrom; });

                                                    // Count children per age range
                                                    $range_counts = [];
                                                    foreach ($valid_rules as $rule) {
                                                        $range_counts[$rule->id] = 0;
                                                    }
                                                    foreach ($child_ages as $age) {
                                                        foreach ($valid_rules as $rule) {
                                                            if ($age >= $rule->agefrom && $age <= $rule->ageto) {
                                                                $range_counts[$rule->id]++;
                                                                break;
                                                            }
                                                        }
                                                    }

                                                    // Calculate total quantity before bottle adjustment
                                                    $total_quantity_before_bottle = 0;
                                                    $range_data = [];
                                                    foreach ($valid_rules as $rule) {
                                                        $child_count = $range_counts[$rule->id];
                                                        if ($child_count == 0) continue;
                                                        $range_qty = $per_child_quantity * $child_count; // quantity for this range
                                                        $range_data[$rule->id] = [
                                                            'child_count' => $child_count,
                                                            'quantity'    => $range_qty,
                                                            'price'       => (float)$rule->amount,
                                                            'name_suffix' => " (age {$rule->agefrom}-{$rule->ageto})"
                                                        ];
                                                        $total_quantity_before_bottle += $range_qty;
                                                    }

                                                    // Apply bottle adjustment if this is the last service and no saved itinerary
                                                    $adjusted_total_quantity = $total_quantity_before_bottle;
                                                    if ($idx === $total_services - 1 && empty($saved_itinerary_details)) {
                                                        $adjusted_total_quantity = max(0, $total_quantity_before_bottle - (int)$bottle);
                                                    }

                                                    // Distribute the adjustment proportionally (if any)
                                                    $factor = ($total_quantity_before_bottle > 0) ? $adjusted_total_quantity / $total_quantity_before_bottle : 0;

                                                    foreach ($range_data as $rule_id => $data) {
                                                        $final_quantity = (int)round($data['quantity'] * $factor);
                                                        if ($final_quantity == 0) continue;

                                                        $line_total = $final_quantity * $data['price'];
                                                        $display_rows[] = [
                                                            'name'     => $service_name . $data['name_suffix'],
                                                            'cost'     => $data['price'],
                                                            'quantity' => $final_quantity,
                                                            'total'    => $line_total
                                                        ];
                                                        $grand_total += $line_total;
                                                    }
                                                } else {
                                                    // ----- Non‑age‑based: single row -----
                                                    // Total quantity = per_child_quantity * total_children (if per_person)
                                                    $total_quantity = $per_child_quantity;
                                                    if ($group_type === 'per_person') {
                                                        $total_quantity *= $total_children;
                                                    }

                                                    // Apply bottle adjustment for last service
                                                    if ($idx === $total_services - 1 && empty($saved_itinerary_details)) {
                                                        $total_quantity = max(0, $total_quantity - (int)$bottle);
                                                    }
                                                    
                                                    $line_cost = $default_price;
                                                    // Check if the price is "NA" or otherwise invalid
                                                    $price_clean = trim($line_cost);
                                                    if ($price_clean === '' || $price_clean === 'NA' || !is_numeric($price_clean) || (float)$price_clean == 0) {
                                                        continue; // skip this mandatory service entirely
                                                    }
                                                    $line_cost = (float)$price_clean;
                                                    $line_total = $total_quantity * $line_cost;

                                                    // $line_cost = $default_price; // fallback price (could also use aux->child_price)
                                                    // $line_total = $total_quantity * $line_cost;

                                                    $display_rows[] = [
                                                        'name'     => $service_name,
                                                        'cost'     => $line_cost,
                                                        'quantity' => $total_quantity,
                                                        'total'    => $line_total
                                                    ];
                                                    $grand_total += $line_total;
                                                }
                                            }

                                            // --------------------------------------------------------------
                                            // 7. Render the rows
                                            // --------------------------------------------------------------
                                            foreach ($display_rows as $row): ?>
                                                <div class="row p-2 bg-grey mandatory-row" style="line-height:1.2">             
                                                    <div class="col-md-4" style="font-weight:600;"><?= htmlspecialchars($row['name']) ?></div>
                                                    <div class="col-md-3">
                                                        <input type="text" name="child_mandatory_services_cost[]" value="<?= $row['cost'] ?>" class="child-mandatory-cost">
                                                    </div>
                                                    <div class="col-md-2">
                                                        <input type="text" name="child_mandatory_services_qnty[]" value="<?= $row['quantity'] ?>" class="child-mandatory-qty">
                                                        <input type="hidden" name="child_mandatory_services_name[]" value="<?= htmlspecialchars($row['name']) ?>">
                                                    </div>
                                                    <div class="col-md-3">
                                                        <input type="text" value="<?= $row['total'] ?>" class="child-mandatory-total" readonly>
                                                    </div>
                                                </div>
                                            <?php endforeach; ?>

                                            <!-- Grand total -->
                                            <div class="row p-1" style="background:#6bafba7a;font-weight:600;border-top:1px solid;">
                                                <div class="offset-9 col-md-3">
                                                    <input type="text" value="<?= $grand_total; ?>" id="child_mandatory_grand_total" readonly>
                                                </div>
                                            </div>

                                        <?php } else { ?>
                                            <div class="alert alert-info">No child mandatory services available.</div>
                                        <?php } ?>
                                    </div>     
                                </div>
                            <?php }

                                } else{
                                    if(($this->input->get('saved_created_date') > '2026-03-17 17:19:31' && $this->input->get('saved_child_mandatory_services') !='[]' && $this->input->get('number_of_child') > 0) || $this->input->get('saved_created_date') =='' && $this->input->get('number_of_child') > 0){ ?>
                                    <div class="card-body row mandatory-services-card">
                                        <div class="col-md-9">
                                            <h5 class="bold text-center" style="font-weight: 600;font-size:1.3rem;">Child Mandatory Services</h5>
                                            <div class="row mb-2 p-1" style="color:#FFF;font-weight:600;background-color:#207da6;">    
                                                <div class="col-md-4" style="font-weight:600;">Name</div>
                                                <div class="col-md-3" style="font-weight:600;">Cost</div>
                                                <div class="col-md-2" style="font-weight:600;">Quantity</div>
                                                <div class="col-md-3" style="font-weight:600;">Total</div>
                                            </div>
                                            <?php
                                            // Bottle calculation based on last day sites (same logic as adult)
                                            if (!empty($template_content)) {
                                                $lastIndex = count($template_content) - 1;
                                                $allSiteIds = (array) ($this->input->get('hdn_site_id') ?? []);
                                                $lastDaySiteIds = isset($allSiteIds[$lastIndex]) ? (array) $allSiteIds[$lastIndex] : [];
                                                $filtered = array_values(array_filter($lastDaySiteIds, fn($v) => $v !== '' && is_numeric($v)));
                                                if (!empty($filtered)) {
                                                    $site_ids_str = implode(',', $filtered);
                                                    $where2 = "sites.id IN ($site_ids_str) AND (category='miscellaneous' OR category='transfers') AND miscellaneous_cost='withoutcost'";
                                                    $matching_sites = $this->common_model->get_data('sites', '', '', '*', $where2, '', '', '');
                                                    $matching_ids = [];
                                                    foreach ($matching_sites as $site) {
                                                        $matching_ids[] = $site->id;
                                                    }
                                                    $non_matching_ids = array_diff($filtered, $matching_ids);
                                                    if (count($non_matching_ids) == 0) {
                                                        $total_guest = (int)$this->input->get('number_of_child');
                                                        $bottle = $total_guest * 2;
                                                    } else {
                                                        $bottle = 0;
                                                    }
                                                }
                                            }

                                            $child_mandatory_grand_total = 0;
                                            $j = 0;
                                            $child_mandatory_services = $this->input->get('child_hdn_mandatory_services');
                                            $child_mandatory_services_ids = $this->input->get('child_hdn_mandatory_services_ids');
                                            $total_items = count($child_mandatory_services);
                                            $index = 0;
                                            foreach ($child_mandatory_services as $services_list) { 
                                                $arr = explode('_|_', $services_list);
                                                $cost = $arr[1];
                                                $qnty = $this->input->get('child_mandatory_services_qnty')[$index];

                                                // Adjust quantity for the last item if no saved itinerary
                                                if ($index === $total_items - 1) {
                                                    if (empty($saved_itinerary_details)) {
                                                        $qnty = (int)$qnty - (int)$bottle;
                                                    } else {
                                                        $qnty = (int)$qnty;
                                                    }
                                                    if ($qnty < 0) $qnty = 0;
                                                }

                                                $total = $cost * $qnty;
                                                $index++;
                                            ?>
                                                <div class="row p-2 bg-grey mandatory-row" data-index="<?= $j ?>" style="line-height:1.2">             
                                                    <div class="col-md-4" style="font-weight:600;"><?= $arr[0]; ?></div>
                                                    <div class="col-md-3" style="font-weight:600;">
