<!-- ADD daywise meal data for mix meal option -->
<script>
    let cutoff_meal_sitescene = '2026-05-24 00:00:00';
    let saved_last_meal_quotation_date = "<?= $first_created_date ?? '' ?>";

    if (saved_last_meal_quotation_date === '' || new Date(saved_last_meal_quotation_date) >= new Date(cutoff_meal_sitescene)) {
        document.addEventListener('DOMContentLoaded', function() {
            // Load initial data from PHP
            let allMealData = <?= json_encode($all_day_meal_prices) ?>;
            let allEntertainmentData = <?= json_encode($all_day_entertainment) ?>;

            const mealHidden = document.getElementById('meal_type_daywise_price');
            const entHidden  = document.getElementById('entertainment_daywise_data');
            const childMealHidden = document.getElementById('childMealCost');

            // Helper: sort object keys naturally
            function sortObjectByKeys(obj) {
                if (!obj || typeof obj !== 'object') return obj;
                return Object.keys(obj)
                    .sort((a, b) => {
                        const numA = parseInt(a.replace(/\D/g, ''), 10);
                        const numB = parseInt(b.replace(/\D/g, ''), 10);
                        return numA - numB;
                    })
                    .reduce((sorted, key) => {
                        sorted[key] = obj[key];
                        return sorted;
                    }, {});
            }

            function updateMealHidden() {
                allMealData = sortObjectByKeys(allMealData);
                mealHidden.value = JSON.stringify(allMealData);
                Object.keys(allMealData).forEach(dayKey => {
                    const dayHidden = document.getElementById(`meal_type_daywise_price_${dayKey}`);
                    if (dayHidden) dayHidden.value = JSON.stringify(allMealData[dayKey]);
                });
            }

            function updateEntertainmentHidden() {
                allEntertainmentData = sortObjectByKeys(allEntertainmentData);
                entHidden.value = JSON.stringify(allEntertainmentData);
            }

            // ------------------------------------------------------------------
            // Set adult meal data (ALWAYS with ctype)
            // ------------------------------------------------------------------
            function setMealData(dayKey, ctype, mealId, price, adultCount) {
                if (!allMealData[dayKey]) allMealData[dayKey] = {};
                if (!allMealData[dayKey][ctype]) allMealData[dayKey][ctype] = {};
                if (!allMealData[dayKey][ctype][mealId]) {
                    allMealData[dayKey][ctype][mealId] = { adult: {}, child_groups: [] };
                }
                allMealData[dayKey][ctype][mealId].adult = {
                    price: price,
                    count: adultCount,
                    total: price * adultCount
                };
                updateMealHidden();
            }

            // ------------------------------------------------------------------
            // Set child group data (ALWAYS with ctype)
            // ------------------------------------------------------------------
            function setChildGroupData(dayKey, ctype, mealId, groupRange, price, count) {
                if (!allMealData[dayKey]) allMealData[dayKey] = {};
                if (!allMealData[dayKey][ctype]) allMealData[dayKey][ctype] = {};
                if (!allMealData[dayKey][ctype][mealId]) {
                    allMealData[dayKey][ctype][mealId] = { adult: {}, child_groups: [] };
                }
                let groups = allMealData[dayKey][ctype][mealId].child_groups || [];
                let existing = groups.find(g => g.range === groupRange);
                if (existing) {
                    existing.price = price;
                    existing.count = count;
                    existing.total = price * count;
                } else {
                    groups.push({ range: groupRange, price: price, count: count, total: price * count });
                }
                allMealData[dayKey][ctype][mealId].child_groups = groups;
                updateMealHidden();
            }

            // Set entertainment data
            function setEntertainmentData(dayKey, mealId, entName, price, qty) {
                if (!allEntertainmentData[dayKey]) allEntertainmentData[dayKey] = {};
                if (!allEntertainmentData[dayKey][mealId]) allEntertainmentData[dayKey][mealId] = {};
                allEntertainmentData[dayKey][mealId][entName] = { price, qty, total: price * qty };
                updateEntertainmentHidden();
            }

            // Helper: update belly dance row total
            function updateBellyRow($row) {
                const price = parseFloat($row.find('.meal-dance-price').val()) || 0;
                const qty = parseFloat($row.find('.meal-price-qty').val()) || 0;
                const total = price * qty;
                $row.find('.meal-total').val(total);
                return { price, qty, total };
            }

            // Helper: update child row total
            function updateChildRow($row) {
                const price = parseFloat($row.find('.child-price').val()) || 0;
                const count = parseInt($row.find('.child-count-input').val()) || 0;
                const total = price * count;
                $row.find('.child-total').val(total);
                return { price, count, total, range: $row.data('group') };
            }

            // Update grand total
            function updateGrandTotal() {
                let grandTotal = 0;
                document.querySelectorAll('.meal-total').forEach(el => {
                    grandTotal += parseFloat(el.value) || 0;
                });
                document.querySelectorAll('.grandTotalMeal').forEach(el => {
                    if (el.tagName === 'INPUT') el.value = grandTotal;
                    else el.textContent = grandTotal.toLocaleString();
                });
                if (childMealHidden) {
                    let childTotal = 0;
                    document.querySelectorAll('.child-total').forEach(el => {
                        childTotal += parseFloat(el.value) || 0;
                    });
                    childMealHidden.value = childTotal;
                }
            }

            // ------------------------------------------------------------------
            // Event: adult meal price change
            // ------------------------------------------------------------------
            $(document).on('input', '.meal-price', function() {
                const $row = $(this).closest('tr');
                const price = parseFloat($(this).val()) || 0;
                const adultCount = parseInt($(this).data('persons')) || 0;
                const adultTotal = price * adultCount;
                $row.find('.meal-total').first().val(adultTotal);

                // Try to get ctype from the row's data-ctype (new) OR from input name
                let ctype = $row.data('ctype');
                let dayKey = null;
                let mealId = null;

                if (!ctype) {
                    // Fallback: parse input name (for "all days" case)
                    const match = $(this).attr('name').match(/meal_price\[(.*?)\](\[(.*?)\])?\[(.*?)\]/);
                    if (match) {
                        dayKey = match[1];
                        ctype = match[3] || null;
                        mealId = match[4];
                    }
                } else {
                    // For day-specific case, get dayKey and mealId from table and row data
                    dayKey = $row.closest('table').data('day-key');
                    mealId = $row.data('meal-id');
                }

                if (dayKey && ctype && mealId) {
                    setMealData(dayKey, ctype, mealId, price, adultCount);
                }
                updateGrandTotal();
            });

            // ------------------------------------------------------------------
            // Event: child price / count change
            // ------------------------------------------------------------------
            $(document).on('input', '.child-price, .child-count-input', function() {
                const $row = $(this).closest('tr');
                const mealId = $row.data('meal-id');
                const groupRange = $row.data('group');
                const { price, count } = updateChildRow($row);

                // Get ctype from row's data-ctype (which should be inherited from parent row)
                let ctype = $row.data('ctype');
                let dayKey = $row.closest('table').data('day-key');

                if (!ctype) {
                    // Fallback: try to find the parent meal row's ctype
                    const parentRow = $row.prevAll('tr[data-meal-id="' + mealId + '"]').first();
                    if (parentRow.length) ctype = parentRow.data('ctype');
                }

                if (dayKey && ctype && mealId && groupRange) {
                    setChildGroupData(dayKey, ctype, mealId, groupRange, price, count);
                }
                updateGrandTotal();
            });

            // ------------------------------------------------------------------
            // Event: belly dance price/quantity change
            // ------------------------------------------------------------------
            $(document).on('input', '.meal-dance-price, .meal-price-qty', function() {
                const $row = $(this).closest('tr');
                const { price, qty } = updateBellyRow($row);
                const nameAttr = $(this).hasClass('meal-dance-price') ? $(this).attr('name') : $row.find('.meal-dance-price').attr('name');
                const match = nameAttr.match(/entertainment_price\[(.*?)\]\[(.*?)\]\[(.*?)\]/);
                if (match) {
                    const dayKey = match[1];
                    const mealId = match[2];
                    const entName = match[3];
                    setEntertainmentData(dayKey, mealId, entName, price, qty);
                }
                updateGrandTotal();
            });

            // ------------------------------------------------------------------
            // Initialize on page load
            // ------------------------------------------------------------------
            allMealData = sortObjectByKeys(allMealData);
            allEntertainmentData = sortObjectByKeys(allEntertainmentData);
            mealHidden.value = JSON.stringify(allMealData);
            entHidden.value = JSON.stringify(allEntertainmentData);

            // Initialize adult meal rows
            $('.meal-price').each(function() {
                const $row = $(this).closest('tr');
                const price = parseFloat($(this).val()) || 0;
                const adultCount = parseInt($(this).data('persons')) || 0;
                const adultTotal = price * adultCount;
                $row.find('.meal-total').first().val(adultTotal);

                let ctype = $row.data('ctype');
                let dayKey = null;
                let mealId = null;
                if (!ctype) {
                    const match = $(this).attr('name').match(/meal_price\[(.*?)\](\[(.*?)\])?\[(.*?)\]/);
                    if (match) {
                        dayKey = match[1];
                        ctype = match[3] || null;
                        mealId = match[4];
                    }
                } else {
                    dayKey = $row.closest('table').data('day-key');
                    mealId = $row.data('meal-id');
                }
                if (dayKey && ctype && mealId) {
                    setMealData(dayKey, ctype, mealId, price, adultCount);
                }
            });

            // Initialize child rows
            $('.child-price, .child-count-input').each(function() {
                const $row = $(this).closest('tr');
                const mealId = $row.data('meal-id');
                const groupRange = $row.data('group');
                const price = parseFloat($row.find('.child-price').val()) || 0;
                const count = parseInt($row.find('.child-count-input').val()) || 0;
                $row.find('.child-total').val(price * count);

                let ctype = $row.data('ctype');
                let dayKey = $row.closest('table').data('day-key');
                if (!ctype) {
                    const parentRow = $row.prevAll('tr[data-meal-id="' + mealId + '"]').first();
                    if (parentRow.length) ctype = parentRow.data('ctype');
                }
                if (dayKey && ctype && mealId && groupRange) {
                    setChildGroupData(dayKey, ctype, mealId, groupRange, price, count);
                }
            });

            // Initialize belly dance rows
            $('.meal-dance-price').each(function() {
                const $row = $(this).closest('tr');
                const { price, qty } = updateBellyRow($row);
                const nameAttr = $(this).attr('name');
                const match = nameAttr.match(/entertainment_price\[(.*?)\]\[(.*?)\]\[(.*?)\]/);
                if (match) {
                    const dayKey = match[1];
                    const mealId = match[2];
                    const entName = match[3];
                    setEntertainmentData(dayKey, mealId, entName, price, qty);
                }
            });

            updateGrandTotal();
        });                                     
    }else
    {
        
         document.addEventListener('DOMContentLoaded', function() {
            // Load initial data from PHP (may already contain buffet, cuisine, child_with_age)
            let allMealData = <?= json_encode($all_day_meal_prices) ?>;
            let allEntertainmentData = <?= json_encode($all_day_entertainment) ?>;

            const mealHidden = document.getElementById('meal_type_daywise_price');
            const entHidden  = document.getElementById('entertainment_daywise_data');
            const childMealHidden = document.getElementById('childMealCost');

            // ------------------------------------------------------------------
            // Helper: sort object keys naturally (Day_1, Day_2, ...)
            // ------------------------------------------------------------------
            function sortObjectByKeys(obj) {
                return Object.keys(obj)
                    .sort((a, b) => {
                        const numA = parseInt(a.replace(/\D/g, ''), 10);
                        const numB = parseInt(b.replace(/\D/g, ''), 10);
                        return numA - numB;
                    })
                    .reduce((sorted, key) => {
                        sorted[key] = obj[key];
                        return sorted;
                    }, {});
            }

            function updateMealHidden() {
                allMealData = sortObjectByKeys(allMealData);
                mealHidden.value = JSON.stringify(allMealData);
                // Update per‑day hidden fields if they exist
                Object.keys(allMealData).forEach(dayKey => {
                    const dayHidden = document.getElementById(`meal_type_daywise_price_${dayKey}`);
                    if (dayHidden) dayHidden.value = JSON.stringify(allMealData[dayKey]);
                });
            }

            function updateEntertainmentHidden() {
                allEntertainmentData = sortObjectByKeys(allEntertainmentData);
                entHidden.value = JSON.stringify(allEntertainmentData);
            }

            // ------------------------------------------------------------------
            // Extract buffet, cuisine, child_with_age from the table row (if needed)
            // ------------------------------------------------------------------
            function getMealMetadataFromRow($row) {
                const $cells = $row.find('td');
                let buffet = null, cuisine = null, childWithAge = null;
                if ($cells.length >= 2) {
                    buffet = $cells.eq(0).text().trim();
                    cuisine = $cells.eq(1).text().trim();
                }
                // child_with_age might be stored as data attribute or in a hidden field
                const mealId = $row.data('meal-id');
                if (mealId) {
                    // Try to read from a data attribute or from the PHP initial data
                    const existing = allMealData[Object.keys(allMealData)[0]]?.[mealId];
                    if (existing && existing.child_with_age) childWithAge = existing.child_with_age;
                }
                return { buffet, cuisine, childWithAge };
            }

            // ------------------------------------------------------------------
            // Update adult meal data – preserve all existing fields
            // ------------------------------------------------------------------
            function setMealData(dayKey, mealId, price, adultCount, $row) {
                if (!allMealData[dayKey]) allMealData[dayKey] = {};
                
                const existing = allMealData[dayKey][mealId] || {};
                
                // Preserve buffet, cuisine, child_with_age from existing or from DOM
                let buffet = existing.buffet;
                let cuisine = existing.cuisine;
                let childWithAge = existing.child_with_age;
                
                if ((!buffet || !cuisine) && $row && $row.length) {
                    const meta = getMealMetadataFromRow($row);
                    if (meta.buffet) buffet = meta.buffet;
                    if (meta.cuisine) cuisine = meta.cuisine;
                    if (meta.childWithAge) childWithAge = meta.childWithAge;
                }
                
                allMealData[dayKey][mealId] = {
                    ...existing,  // keep any other properties (e.g., child_groups)
                    buffet: buffet,
                    cuisine: cuisine,
                    child_with_age: childWithAge,
                    adult: {
                        price: price,
                        count: adultCount,
                        total: price * adultCount
                    }
                };
                // Ensure child_groups exists
                if (!allMealData[dayKey][mealId].child_groups) {
                    allMealData[dayKey][mealId].child_groups = [];
                }
                updateMealHidden();
            }

            // ------------------------------------------------------------------
            // Update child group data – preserve buffet, cuisine, child_with_age
            // ------------------------------------------------------------------
            function setChildGroupData(dayKey, mealId, groupRange, price, count, $row) {
                if (!allMealData[dayKey]) allMealData[dayKey] = {};
                
                const existing = allMealData[dayKey][mealId] || {};
                
                let buffet = existing.buffet;
                let cuisine = existing.cuisine;
                let childWithAge = existing.child_with_age;
                
                if ((!buffet || !cuisine) && $row && $row.length) {
                    const meta = getMealMetadataFromRow($row);
                    if (meta.buffet) buffet = meta.buffet;
                    if (meta.cuisine) cuisine = meta.cuisine;
                    if (meta.childWithAge) childWithAge = meta.childWithAge;
                }
                
                // Initialize if not exists
                if (!allMealData[dayKey][mealId]) {
                    allMealData[dayKey][mealId] = {
                        buffet: buffet,
                        cuisine: cuisine,
                        child_with_age: childWithAge,
                        adult: { price: 0, count: 0, total: 0 },
                        child_groups: []
                    };
                }
                
                let groups = allMealData[dayKey][mealId].child_groups || [];
                let existingGroup = groups.find(g => g.range === groupRange);
                
                if (existingGroup) {
                    existingGroup.price = price;
                    existingGroup.count = count;
                    existingGroup.total = price * count;
                } else {
                    groups.push({
                        range: groupRange,
                        price: price,
                        count: count,
                        total: price * count
                    });
                }
                
                allMealData[dayKey][mealId].child_groups = groups;
                allMealData[dayKey][mealId].buffet = buffet;
                allMealData[dayKey][mealId].cuisine = cuisine;
                allMealData[dayKey][mealId].child_with_age = childWithAge;
                
                updateMealHidden();
            }

            // ------------------------------------------------------------------
            // Entertainment data (no change needed)
            // ------------------------------------------------------------------
            function setEntertainmentData(dayKey, mealId, price, qty) {
                if (!allEntertainmentData[dayKey]) allEntertainmentData[dayKey] = {};
                allEntertainmentData[dayKey][mealId] = {
                    price: price,
                    qty: qty,
                    total: price * qty
                };
                updateEntertainmentHidden();
            }

            // ------------------------------------------------------------------
            // Helper functions to update row totals
            // ------------------------------------------------------------------
            function updateBellyRow($row) {
                const price = parseFloat($row.find('.meal-dance-price').val()) || 0;
                const qty = parseFloat($row.find('.meal-price-qty').val()) || 0;
                const total = price * qty;
                $row.find('.meal-total').val(total);
                return { price, qty, total };
            }

            function updateChildRow($row) {
                const price = parseFloat($row.find('.child-price').val()) || 0;
                const count = parseInt($row.find('.child-count-input').val()) || 0;
                const total = price * count;
                $row.find('.child-total').val(total);
                return { price, count, total, range: $row.data('group') };
            }

            function updateGrandTotal() {
                let grandTotal = 0;
                document.querySelectorAll('.meal-total').forEach(el => {
                    grandTotal += parseFloat(el.value) || 0;
                });
                document.querySelectorAll('.grandTotalMeal').forEach(el => {
                    if (el.tagName === 'INPUT') el.value = grandTotal;
                    else el.textContent = grandTotal.toLocaleString();
                });
                if (childMealHidden) {
                    let childTotal = 0;
                    document.querySelectorAll('.child-total').forEach(el => {
                        childTotal += parseFloat(el.value) || 0;
                    });
                    childMealHidden.value = childTotal;
                }
            }

            // ------------------------------------------------------------------
            // Event listeners
            // ------------------------------------------------------------------
            $(document).on('input', '.meal-price', function() {
                const $row = $(this).closest('tr');
                const price = parseFloat($(this).val()) || 0;
                const adultCount = parseInt($(this).data('persons')) || 0;
                const adultTotal = price * adultCount;
                $row.find('.meal-total').first().val(adultTotal);

                const match = $(this).attr('name').match(/meal_price\[(.*?)\]\[(.*?)\]/);
                if (match) {
                    const dayKey = match[1];
                    const mealId = match[2];
                    setMealData(dayKey, mealId, price, adultCount, $row);
                }
                updateGrandTotal();
            });

            $(document).on('input', '.child-price, .child-count-input', function() {
                const $row = $(this).closest('tr');
                const mealId = $row.data('meal-id');
                const groupRange = $row.data('group');
                const { price, count } = updateChildRow($row);
                const $table = $row.closest('table');
                const dayKey = $table.data('day-key');
                if (dayKey && mealId && groupRange) {
                    setChildGroupData(dayKey, mealId, groupRange, price, count, $row);
                    updateGrandTotal();
                }
            });

            $(document).on('input', '.meal-dance-price', function() {
                const $row = $(this).closest('tr');
                const { price, qty } = updateBellyRow($row);
                const match = $(this).attr('name').match(/entertainment_price\[(.*?)\]\[(.*?)\]/);
                if (match) {
                    const dayKey = match[1];
                    const mealId = match[2];
                    setEntertainmentData(dayKey, mealId, price, qty);
                }
                updateGrandTotal();
            });

            $(document).on('input', '.meal-price-qty', function() {
                const $row = $(this).closest('tr');
                const { price, qty } = updateBellyRow($row);
                let match = $(this).attr('name').match(/entertainment_qty\[(.*?)\]\[(.*?)\]/);
                if (!match) {
                    const priceInput = $row.find('.meal-dance-price');
                    match = priceInput.attr('name').match(/entertainment_price\[(.*?)\]\[(.*?)\]/);
                }
                if (match) {
                    const dayKey = match[1];
                    const mealId = match[2];
                    setEntertainmentData(dayKey, mealId, price, qty);
                }
                updateGrandTotal();
            });

            // ------------------------------------------------------------------
            // Initialization: populate allMealData from existing PHP data and DOM
            // ------------------------------------------------------------------
            // First, ensure every meal entry from PHP retains its original fields
            for (let dayKey in allMealData) {
                for (let mealId in allMealData[dayKey]) {
                    const entry = allMealData[dayKey][mealId];
                    // Ensure child_groups exists
                    if (!entry.child_groups) entry.child_groups = [];
                    // If buffet/cuisine missing, try to get from first row of that day (lazy)
                }
            }
            
            // Initialize adult meal rows
            $('.meal-price').each(function() {
                const $row = $(this).closest('tr');
                const price = parseFloat($(this).val()) || 0;
                const adultCount = parseInt($(this).data('persons')) || 0;
                const adultTotal = price * adultCount;
                $row.find('.meal-total').first().val(adultTotal);

                const match = $(this).attr('name').match(/meal_price\[(.*?)\]\[(.*?)\]/);
                if (match) {
                    const dayKey = match[1];
                    const mealId = match[2];
                    // Only set if not already present in allMealData (to avoid overwriting)
                    if (!allMealData[dayKey]?.[mealId]?.adult) {
                        setMealData(dayKey, mealId, price, adultCount, $row);
                    } else {
                        // Update totals in DOM only, keep existing data
                        const existing = allMealData[dayKey][mealId];
                        if (existing.adult) {
                            $(this).val(existing.adult.price);
                            $row.find('.meal-total').first().val(existing.adult.total);
                        }
                    }
                }
            });

            // Initialize child rows
            $('.child-price, .child-count-input').each(function() {
                const $row = $(this).closest('tr');
                const mealId = $row.data('meal-id');
                const groupRange = $row.data('group');
                const price = parseFloat($row.find('.child-price').val()) || 0;
                const count = parseInt($row.find('.child-count-input').val()) || 0;
                $row.find('.child-total').val(price * count);
                const $table = $row.closest('table');
                const dayKey = $table.data('day-key');
                if (dayKey && mealId && groupRange) {
                    // Check if already stored
                    const existingGroups = allMealData[dayKey]?.[mealId]?.child_groups;
                    const already = existingGroups?.some(g => g.range === groupRange);
                    if (!already) {
                        setChildGroupData(dayKey, mealId, groupRange, price, count, $row);
                    }
                }
            });

            // Initialize belly dance rows
            $('.meal-dance-price').each(function() {
                const $row = $(this).closest('tr');
                const { price, qty } = updateBellyRow($row);
                const match = $(this).attr('name').match(/entertainment_price\[(.*?)\]\[(.*?)\]/);
                if (match) {
                    const dayKey = match[1];
                    const mealId = match[2];
                    if (!allEntertainmentData[dayKey]?.[mealId]) {
                        setEntertainmentData(dayKey, mealId, price, qty);
                    }
                }
            });

            updateGrandTotal();
        });
    }
</script>

 <script>
        $(document).ready(function() {

        // Function to calculate and update totals for train transport
        function updateTrainTransportTotals(day) {
            let dayTotal = 0;
            let dayVehicles = [];

            // Get all rows for the specified day
            $(`.train-transport-transfer-row[data-day="${day}"]`).each(function() {
                const $row = $(this);
                const transportId = $row.data('transport-id');
                const vehicleName = $row.find('.col-md-3').text().trim();
                const multiplier = parseInt($row.data('multiplier')) || 2;   // <-- read multiplier

                // Get price and quantity values
                let price = parseFloat($row.find('.train_transport_price').val().replace(/,/g, '')) || 0;
                let qty = parseInt($row.find('.train_transport_qty').val()) || 0;

                // Calculate total for this vehicle using the multiplier
                let total = price * qty * multiplier;

                // Update total field
                $row.find('.train_transport_total').val(total.toFixed(0));

                // Add to day total
                dayTotal += total;

                // Add to vehicles array if price > 0 and vehicle name exists
                if (price >= 0 && vehicleName) {
                    dayVehicles.push({
                        transport_id: transportId,
                        vehicle_name: vehicleName,
                        price: price,
                        qty: qty,
                        total: total
                    });
                }
            });

            // Update total for this day
            $(`#dayTotalTrainTransport_${day}`).val(dayTotal.toFixed(0));

            // Update the daywise data input
            if (dayVehicles.length > 0) {
                let dayData = {
                    day: parseInt(day),
                    type: 'train',
                    vehicles: dayVehicles
                };
                $(`#daywiseTrainTransportData_${day}`).val(JSON.stringify(dayData));
            } else {
                $(`#daywiseTrainTransportData_${day}`).val('');
            }
            updateFinalTransport();

            return dayTotal;
        }

        // Function to calculate and update overall total
        function updateOverallTotal() {
            let grandTotal = 0;

            // Find all unique days
            let days = [];
            $('.train-transport-transfer-row').each(function() {
                let day = $(this).data('day');
                if (!days.includes(day)) {
                    days.push(day);
                }
            });

            // Calculate total for each day and sum them
            days.forEach(function(day) {
                let dayTotal = 0;
                $(`.train-transport-transfer-row[data-day="${day}"]`).each(function() {
                    let price = parseFloat($(this).find('.train_transport_price').val().replace(/,/g, '')) || 0;
                    let qty = parseInt($(this).find('.train_transport_qty').val()) || 0;
                    let multiplier = parseInt($(this).data('multiplier')) || 2;   // <-- read multiplier
                    dayTotal += price * qty * multiplier;
                });
                grandTotal += dayTotal;
            });

            // Update overall total input
            $('#totalTrainTansportPrice').val(grandTotal.toFixed(0));

            // Collect all days data for the main input
            let allDaysData = [];
            days.forEach(function(day) {
                let dayDataStr = $(`#daywiseTrainTransportData_${day}`).val();
                if (dayDataStr) {
                    try {
                        allDaysData.push(JSON.parse(dayDataStr));
                    } catch(e) {
                        console.error('Error parsing day data:', e);
                    }
                }
            });

            // Update the main daywise_train_transport_data input
            if (allDaysData.length > 0) {
                $('#daywise_train_transport_data').val(JSON.stringify(allDaysData));
            } else {
                $('#daywise_train_transport_data').val('');
            }
            updateFinalTransport();
        }

        // Event handlers remain unchanged (they call the updated functions)
        $(document).on('input', '.train_transport_price', function() {
            const $row = $(this).closest('.train-transport-transfer-row');
            const day = $row.data('day');

            let value = $(this).val().replace(/[^0-9.]/g, '');
            if (value) {
                value = parseFloat(value).toFixed(0);
                $(this).val(value);
            }

            updateTrainTransportTotals(day);
            updateOverallTotal();
        });

        $(document).on('input', '.train_transport_qty', function() {
            const $row = $(this).closest('.train-transport-transfer-row');
            const day = $row.data('day');

            let value = $(this).val().replace(/[^0-9]/g, '');
            if (value) {
                value = parseInt(value);
                if (value < 0) value = 0;
                $(this).val(value);
            } else {
                $(this).val(0);
            }

            updateTrainTransportTotals(day);
            updateOverallTotal();
        });

        $(document).on('blur', '.train_transport_price', function() {
            let value = $(this).val().replace(/[^0-9.]/g, '');
            if (value) {
                value = parseFloat(value);
                if (!isNaN(value)) {
                    $(this).val(value.toFixed(0));
                } else {
                    $(this).val('0.00');
                }
            } else {
                $(this).val('0.00');
            }
            $(this).trigger('input');
        });

        $(document).on('blur', '.train_transport_qty', function() {
            let value = $(this).val().replace(/[^0-9]/g, '');
            if (value) {
                value = parseInt(value);
                if (value < 0) value = 0;
                $(this).val(value);
            } else {
                $(this).val('0');
            }
            $(this).trigger('input');
        });

        // Initialisation
        function initializeTotals() {
            let days = [];
            $('.train-transport-transfer-row').each(function() {
                let day = $(this).data('day');
                if (!days.includes(day)) {
                    days.push(day);
                }
            });

            days.forEach(function(day) {
                updateTrainTransportTotals(day);
            });

            updateOverallTotal();
        }

        setTimeout(initializeTotals, 100);
    });
</script>
<script>
    
    function getTotalRoadAmount() {
        let total = 0;
        $('.road_total').each(function () {
            let val = parseFloat($(this).val()) || 0;
            total += val;
        });
        $('#totalRoadPrice').val(total.toFixed(0));
        return total;
    }

    function updateTollDisplay($row) {
        // Called when quantity changes: update visible toll = perUnit * qty
        let perUnit = parseFloat($row.find('.road_toll_perunit').val()) || 0;
        let qty = parseFloat($row.find('.road_qty').val()) || 1;
        let totalToll = perUnit * qty;
        $row.find('.road_toll').val(totalToll.toFixed(0));
        updateFinalToll();
    }

    function updatePerUnitFromToll($row) {
        // Called when user edits the visible toll: recalc per-unit
        let totalToll = parseFloat($row.find('.road_toll').val()) || 0;
        let qty = parseFloat($row.find('.road_qty').val()) || 1;
        let perUnit = qty > 0 ? totalToll / qty : 0;
        $row.find('.road_toll_perunit').val(perUnit.toFixed(2)); // store with decimals if needed
    }

    function updateRoadRowTotal($row) {
        let price = parseFloat($row.find('.road_price').val()) || 0;
        let parking = parseFloat($row.find('.road_parking').val()) || 0;
        let qty = parseFloat($row.find('.road_qty').val()) || 1;
        let total = (price + parking) * qty;
        $row.find('.road_total').val(total.toFixed(0));
        updateFinalTransport();
        updateFinalToll();
        return total;
    }

    function updateDaywiseRoadData() {
        let allDaysData = [];
        $('.daywise-road-data').each(function() {
            try {
                let value = $(this).val();
                if (value) {
                    let dayData = JSON.parse(value);
                    allDaysData.push(dayData);
                }
            } catch(e) {
                console.error('Error parsing road data:', e);
            }
        });
        $('#daywiseRoadData').val(JSON.stringify(allDaysData));
        updateFinalTransport();
        updateFinalToll();
        return allDaysData;
    }

    function updateDayRoadData($inputElement) {
        let $row = $inputElement.closest('.road-transfer-row');
        let day = $row.data('day');
        let transportId = $row.data('transport-id');
        let vehicleName = $row.find('.col-md-3').eq(1).text().trim();
        let price = parseFloat($row.find('.road_price').val()) || 0;
        let perUnitToll = parseFloat($row.find('.road_toll_perunit').val()) || 0; // from hidden
        let parking = parseFloat($row.find('.road_parking').val()) || 0;
        let qty = parseFloat($row.find('.road_qty').val()) || 1;
        let total = (price + parking) * qty;

        $row.find('.road_total').val(total.toFixed(0));

        let $dayField = $('#daywiseRoadData_' + day);
        if ($dayField.length) {
            try {
                let dayData = JSON.parse($dayField.val());
                dayData.day = parseInt(day);
                if (!dayData.vehicles) dayData.vehicles = [];

                let found = false;
                for (let i = 0; i < dayData.vehicles.length; i++) {
                    if (dayData.vehicles[i].transport_id == transportId) {
                        dayData.vehicles[i].price = price;
                        dayData.vehicles[i].toll = perUnitToll;      // store per-unit
                        dayData.vehicles[i].parking = parking;
                        dayData.vehicles[i].total = total;
                        dayData.vehicles[i].qty = qty;
                        found = true;
                        break;
                    }
                }
                if (!found) {
                    dayData.vehicles.push({
                        transport_id: transportId,
                        vehicle_name: vehicleName,
                        price: price,
                        toll: perUnitToll,
                        parking: parking,
                        qty: qty,
                        total: total
                    });
                }
                $dayField.val(JSON.stringify(dayData));
            } catch(e) {
                console.error('Error updating day data:', e);
            }
        } else {
            let newData = {
                day: parseInt(day),
                vehicles: [{
                    transport_id: transportId,
                    vehicle_name: vehicleName,
                    price: price,
                    toll: perUnitToll,
                    parking: parking,
                    qty: qty,
                    total: total
                }]
            };
            $('<input>', {
                type: 'hidden',
                id: 'daywiseRoadData_' + day,
                class: 'daywise-road-data',
                'data-day': day,
                value: JSON.stringify(newData)
            }).appendTo('form:first');
        }
        updateDaywiseRoadData();
        updateFinalTransport();
        updateFinalToll();
        return total;
    }

    function initializeRoadData() {
        // No need to multiply on load – PHP already set visible toll to total.
        // Just ensure the hidden per-unit field is present.
        $('.road-transfer-row').each(function() {
            let $row = $(this);
            let day = $row.data('day');
            if (day !== undefined) {
                // Call once to populate the day's JSON (uses hidden per-unit)
                updateDayRoadData($row.find('.road_price'));
            }
        });
        updateDaywiseRoadData();
        getTotalRoadAmount();
    }

    // Event handlers
    $(document).on('keyup change', '.road_price, .road_parking, .road_qty:not([readonly])', function () {
        let $row = $(this).closest('.road-transfer-row');
        if ($(this).hasClass('road_qty')) {
            updateTollDisplay($row);
        }
        updateRoadRowTotal($row);
        updateDayRoadData($(this));
        getTotalRoadAmount();
        updateAllTransportationData();
    });

    $(document).on('keyup change', '.road_toll', function () {
        let $row = $(this).closest('.road-transfer-row');
        updatePerUnitFromToll($row);
        updateRoadRowTotal($row);
        updateDayRoadData($(this));
        getTotalRoadAmount();
        updateFinalToll();
        updateAllTransportationData();
    });

    function getAdultChildTotal(){
        $adult = $('#totalTrainPrice').val();
        $child = $('#totalChildTrainPrice').val();
        $('#train_adult_price').val($adult);
        $('#train_child_price').val($child);
    }

    function getTotalChildTrainAmount() {
        let total = 0;
        $('.train-row[data-passenger-type="child"] .train-child-total').each(function () {
            let val = parseFloat($(this).val()) || 0;
            total += val;
        });
        $('#totalChildTrainPrice').val(total.toFixed(0));
        getAdultChildTotal();
        return total;
    }

    function getTotalTrainAmount() {
        let total = 0;
        $('.train-total').each(function () {
            let val = parseFloat($(this).val()) || 0;
            total += val;
        });

        $('#totalTrainPrice').val(total.toFixed(0));
        getAdultChildTotal();
        return total;
    }

    function updateTrainRowTotal($row) {
        let price = parseFloat($row.find('.train-price').val()) || 0;
        let qty = parseFloat($row.find('.train-qty').val()) || 1;
        let total = price * qty;
        
        $row.find('.train-total').val(total.toFixed(0));
        getAdultChildTotal();
        return total;
    }

    function updateTrainChildRowTotal($row) {
        let price = parseFloat($row.find('.train-child-price').val()) || 0;
        let qty = parseFloat($row.find('.train-child-qty').val()) || 1;
        let total = price * qty;
        
        $row.find('.train-child-total').val(total.toFixed(0));
        getAdultChildTotal();
        return total;
    }

   
    
    function updateDaywiseTrainData() {
        let allDaysData = [];
        
        $('.daywise-train-data').each(function(index) {
            try {
                let value = $(this).val();
                if (value && value !== '') {
                    let dayData = JSON.parse(value);
                    allDaysData.push(dayData);
                }
            } catch(e) {
                console.error('Error parsing train data for day:', $(this).data('day'), e);
            }
        });
        
        // Update the master hidden field with JSON string
        let jsonString = JSON.stringify(allDaysData);
        $('#daywiseTrainData').val(jsonString);
        return allDaysData;
    }

    function updateDayTrainData($input) {
        let $rowElement = $input.closest('.train-row');
        let day = $rowElement.data('day');
        if (day === undefined || day === null || day === '') {
            console.warn('Skipping train row without day:', $rowElement);
            return 0;
        }

        let trainId = $rowElement.data('train-id');
        let ticketType = $rowElement.data('train-type');
        let passengerType = $rowElement.data('passenger-type') || 'adult';
        let trainName = $rowElement.data('train-name') || '';
        let ticketTypeLabel = $rowElement.data('label') || '';

        // Get price and quantity based on passenger type
        let price, qty;
        if (passengerType === 'child') {
            price = parseFloat($rowElement.find('.train-child-price').val()) || 0;
            qty = parseFloat($rowElement.find('.train-child-qty').val()) || 1;
        } else {
            price = parseFloat($rowElement.find('.train-price').val()) || 0;
            qty = parseFloat($rowElement.find('.train-qty').val()) || 1;
        }
        let total = price * qty;

        // Update the correct total field
        if (passengerType === 'child') {
            $rowElement.find('.train-child-total').val(total.toFixed(0));
        } else {
            $rowElement.find('.train-total').val(total.toFixed(0));
        }

        // Update day's hidden JSON
        let $dayHiddenField = $('#daywiseTrainData_' + day);
        if ($dayHiddenField.length) {
            try {
                let currentValue = $dayHiddenField.val();
                let dayData = currentValue ? JSON.parse(currentValue) : { 
                    day: parseInt(day), 
                    type: 'train',
                    trains: [] 
                };
                dayData.day = parseInt(day);
                dayData.type = 'train';
                if (!dayData.trains) dayData.trains = [];

                // --- FIX: match using ticket_type_label as well ---
                let trainFound = false;
                for (let i = 0; i < dayData.trains.length; i++) {
                    if (dayData.trains[i].train_id == trainId && 
                        dayData.trains[i].ticket_type == ticketType &&
                        dayData.trains[i].passenger_type == passengerType &&
                        dayData.trains[i].ticket_type_label == ticketTypeLabel) {
                        // Update existing
                        dayData.trains[i].price = price;
                        dayData.trains[i].qty = qty;
                        dayData.trains[i].total = total;
                        trainFound = true;
                        break;
                    }
                }

                // Add new if not found
                if (!trainFound) {
                    dayData.trains.push({
                        train_id: trainId,
                        train_name: trainName,
                        ticket_type: ticketType,
                        ticket_type_label: ticketTypeLabel,
                        passenger_type: passengerType,
                        price: price,
                        qty: qty,
                        total: total
                    });
                }

                $dayHiddenField.val(JSON.stringify(dayData));
            } catch(e) {
                console.error('Error updating train data for day:', day, e);
            }
        } else {
            // Create hidden field if missing
            let newDayData = {
                day: parseInt(day),
                type: 'train',
                trains: [{
                    train_id: trainId,
                    train_name: trainName,
                    ticket_type: ticketType,
                    ticket_type_label: ticketTypeLabel,
                    passenger_type: passengerType,
                    price: price,
                    qty: qty,
                    total: total
                }]
            };
            $('<input>', {
                type: 'hidden',
                id: 'daywiseTrainData_' + day,
                class: 'daywise-train-data',
                'data-day': day,
                value: JSON.stringify(newDayData)
            }).appendTo('form:first');
        }

        // Update master JSON and totals
        updateDaywiseTrainData();
        getTotalTrainAmount();
        if (passengerType === 'child') {
            getTotalChildTrainAmount();
        }
        getAdultChildTotal();
        return total;
    }

    // Bind change events on price inputs
    $(document).on('change', '.train-price, .train-child-price', function() {
        updateDayTrainData($(this));
    });

   

    function initializeTrainData() {
        // Remove any existing daywise fields with invalid day
        $('.daywise-train-data').each(function() {
            let day = $(this).data('day');
            if (day === undefined || day === null || isNaN(parseInt(day))) {
                $(this).remove();
            }
        });

        $('.train-row').each(function() {
            let $row = $(this);
            let day = $row.data('day');
            if (day !== undefined) {
                // Find the appropriate price field
                let $priceField = $row.hasClass('child') ? 
                    $row.find('.train-child-price') : 
                    $row.find('.train-price');
                updateDayTrainData($priceField);
            }
        });
        updateDaywiseTrainData();
        getTotalTrainAmount();
        getTotalChildTrainAmount();
    }

    function updateAllTransportationData() {
        let allRoadData = updateDaywiseRoadData();
        let allTrainData = updateDaywiseTrainData();
        
        let allTransportData = {
            road: allRoadData,
            train: allTrainData
        };
        
        // Create combined master field
        $('#daywiseTransportData').val(JSON.stringify(allTransportData));
        
        return allTransportData;
    }

    function resetTransportationData() {
        // Clear existing data
        $('.daywise-road-data, .daywise-train-data').remove();
        
        // Reinitialize
        initializeRoadData();
        initializeTrainData();
        updateAllTransportationData();
    }

    function exportTransportationData() {
        return {
            road: JSON.parse($('#daywiseRoadData').val() || '[]'),
            train: JSON.parse($('#daywiseTrainData').val() || '[]'),
            totals: {
                road: getTotalRoadAmount(),
                train: getTotalTrainAmount(),
                combined: getTotalRoadAmount() + getTotalTrainAmount()
            }
        };
    }

    function loadTransportationData(data) {
        if (data.road) {
            $('#daywiseRoadData').val(JSON.stringify(data.road));
        }
        if (data.train) {
            $('#daywiseTrainData').val(JSON.stringify(data.train));
        }
        // Trigger recalculation
        initializeRoadData();
        initializeTrainData();
    }

    $(document).ready(function () {
        console.log('Document ready - Initializing transportation data...');
        
        // Initialize totals
        getTotalTrainAmount();
        getTotalRoadAmount();

        // Initialize data with a small delay to ensure DOM is fully loaded
        setTimeout(function() {
            initializeRoadData();
            initializeTrainData();
            updateAllTransportationData();
            console.log('Transportation data initialized successfully');
        }, 100);

        // Set up mutation observer to catch dynamically added rows
        const observer = new MutationObserver(function(mutations) {
            let shouldUpdate = false;
            
            mutations.forEach(function(mutation) {
                if (mutation.addedNodes.length) {
                    $(mutation.addedNodes).each(function() {
                        if ($(this).hasClass && ($(this).hasClass('road-transfer-row') || $(this).hasClass('train-row'))) {
                            shouldUpdate = true;
                        }
                    });
                }
            });
            
            if (shouldUpdate) {
                setTimeout(function() {
                    initializeRoadData();
                    initializeTrainData();
                    updateAllTransportationData();
                }, 50);
            }
        });
        
        observer.observe(document.body, {
            childList: true,
            subtree: true
        });
    });

    $(document).on('keyup change', '.train-price', function () 
    {
        let $row = $(this);
        updateTrainRowTotal($row.closest('.train-row')); 
        updateDayTrainData($row);
        updateAllTransportationData();
    });

    $(document).on('keyup change', '.train-qty:not([readonly])', function () {
        let $row = $(this).closest('.train-row');
        
        updateTrainRowTotal($row);
        updateDayTrainData($row.find('.train-price'));
        getTotalTrainAmount();
        updateAllTransportationData();
    });

    $(document).on('keyup change', '.train-child-price', function () {
        let $row = $(this).closest('.train-row');
        updateTrainChildRowTotal($row);
        updateDayTrainData($(this));
        updateAllTransportationData();
    });

    $(document).on('keyup change', '.train-child-qty:not([readonly])', function () {
        let $row = $(this).closest('.train-row');
        updateTrainChildRowTotal($row);
        updateDayTrainData($row.find('.train-child-price'));
        updateAllTransportationData();
    });

    $(document).on('submit', 'form', function() {
        // Final update before submission
        updateAllTransportationData();
        
        // Log data for debugging
        console.log('Form submission - Transportation Data:', exportTransportationData());
        
        return true;
    });

    function clearTransportationData() {
        $('.daywise-road-data, .daywise-train-data').remove();
        $('#daywiseRoadData, #daywiseTrainData, #daywiseTransportData').val('');
        console.log('All transportation data cleared');
    }
    
