    function updateTravelTotals() 
    {
        let allDaysTotal = 0;
        let allDaysToll  = 0;
        let overnightArr = [];   

        $(".outside-section").each(function() {
            let sectionTotal = 0;
            let sectionToll  = 0;
            let sectionQty   = 0;
            let day          = $(this).data("day");

            $(this).find(".travel-row").each(function() {
                let price = parseFloat($(this).find(".travel-price").val()) || 0;
                let toll  = parseFloat($(this).find(".toll-price").val())   || 0;
                let qty   = parseFloat($(this).find(".travel-qty").val())   || 0;
                let vehicle_name = $(this).data("vehicle") || "";

                let rowTotal = price * qty;
                $(this).find(".travel-total").val(rowTotal);

                sectionTotal += rowTotal;
                sectionToll  += toll; 
                sectionQty   += qty;  

                // push row wise
                overnightArr.push({
                    day: day,
                    vehicle_name: vehicle_name,
                    travel: rowTotal,
                    toll: toll,
                    qty: qty,
                    total: rowTotal
                });
            });

            $(this).find(".travel-grand").val(sectionTotal);

            allDaysTotal += sectionTotal;
            allDaysToll  += sectionToll;
        });

        // update totals
        $("#day_travel_total").val(allDaysTotal);
        $("#overnight_toll_price").val(allDaysToll);

        $("#overnight_cost").val(JSON.stringify(overnightArr));

        updateFinalTransport();
        updateFinalToll();
    }



    $(document).on("input", ".outside-section .travel-price, .outside-section .toll-price, .outside-section .travel-qty", function() {
        updateTravelTotals();
    });

    $(document).ready(function() {
        updateTravelTotals();
    });

   
    
    // 28 March 2026 updated
    function updateAllDaysFullDayTotal() {
        var allDaysTotal = 0;
        var dayMap = {}; // store data per day

        $(".alert").each(function () {
            let $alert = $(this);
            let dayNo = parseInt($alert.data("day")) || 0;
            let dayTotal = 0;
            let vehicles = [];

            // ---- Overnight city rows (different city) ----
            $alert.find(".full-transport-row").each(function () {
                let r = $(this);
                let price = parseFloat(r.find(".full_price").val()) || 0;
                let qty   = parseInt(r.find(".full_qty").val()) || 0;
                let total = price * qty;
                // update the total input field
                r.find(".full_total").val(total);

                vehicles.push({
                    vehicle_name: r.find("div.col-md-4").text().trim(),
                    price: price,
                    qty: qty,
                    total: total
                });
                dayTotal += total;
            });

            // ---- Same city rows (non‑overnight) ----
            $alert.find(".full-transport").each(function () {
                let r = $(this);
                let price = parseFloat(r.find(".full_i_price").val()) || 0;
                let qty   = parseInt(r.find(".full_i_qty").val()) || 0;
                let total = price * qty;
                r.find(".full_i_total").val(total);

                vehicles.push({
                    vehicle_name: r.find("div.col-md-4").text().trim(),
                    price: price,
                    qty: qty,
                    total: total
                });
                dayTotal += total;
            });

            // Aggregate into dayMap (combine vehicles and total for the same day)
            if (!dayMap[dayNo]) {
                dayMap[dayNo] = { day: dayNo, vehicles: [], total: 0 };
            }
            dayMap[dayNo].vehicles.push(...vehicles);
            dayMap[dayNo].total += dayTotal;

            // Update the hidden total field for this specific alert block
            $alert.find("input[type=hidden].total").val(dayTotal);
            allDaysTotal += dayTotal;
        });

        // Convert the map to an array (all days, including zero‑cost ones)
        var fullDayByDay = Object.values(dayMap);
        // Optional: sort by day number
        fullDayByDay.sort((a, b) => a.day - b.day);

        // Update the global total field
        $("#all_days_full_day_total").val(allDaysTotal);

        // Store the aggregated array in the hidden input
        $("#full_day_cost").val(JSON.stringify(fullDayByDay));

        updateFinalTransport();
    }

