    $(document).on('input', '.per-night', function() 
    {
        var $row = $(this).closest('li');
        var nights = parseFloat($(this).data('nights')) || 1;
        var rooms = parseFloat($(this).data('rooms')) || 1;
        var price = parseFloat($(this).val()) || 0;
        var type = $(this).data('type');
        
        // Check if this is PRPN pricing (no night-total field shown)
        var isPRPN = $row.find('.night-total').length === 0;
        
        if (isPRPN) {
            // For PRPN, total is just the price (room cost per night)
            var rowTotal = price;
        } else {
            // For PP, multiply by nights
            var rowTotal = nights * price;
            $row.find('.night-total').val(rowTotal);
        }

        // Calculate subtotals for adult and child separately
        var categoryTotalAdult = 0;
        var categoryTotalChild = 0;
        
        $row.closest('ul').find('li').each(function() {
            var isPRPNItem = $(this).find('.night-total').length === 0;
            var nightTotal = 0;
            
            if (isPRPNItem) {
                nightTotal = parseFloat($(this).find('.per-night').val()) || 0;
            } else {
                nightTotal = parseFloat($(this).find('.night-total').val()) || 0;
            }
            
            var roomCount = parseFloat($(this).find('.per-night').data('rooms')) || 1;
            var itemType = $(this).find('.per-night').data('type');
            
            if (itemType === 'child') {
                categoryTotalChild += nightTotal * roomCount;
            } else {
                categoryTotalAdult += nightTotal * roomCount;
            }
        });
        
        $row.closest('ul').find('.hotel-sub-total-adult').val(categoryTotalAdult);
        $row.closest('ul').find('.hotel-sub-total-child').val(categoryTotalChild);

        // Calculate grand totals for adult and child separately
        var hotelTotalAdult = 0;
        var hotelTotalChild = 0;
        
        $(this).closest('.col-md-6').find('.hotel-sub-total-adult').each(function() {
            hotelTotalAdult += parseFloat($(this).val()) || 0;
        });
        
        $(this).closest('.col-md-6').find('.hotel-sub-total-child').each(function() {
            hotelTotalChild += parseFloat($(this).val()) || 0;
        });
        
        $(this).closest('.col-md-6').find('.hotel-grand-total').val(hotelTotalAdult);
        $(this).closest('.col-md-6').find('.hotel-grand-total-child').val(hotelTotalChild);
        $(this).closest('.col-md-6').find('.hotel-grand-total-combined').val(hotelTotalAdult + hotelTotalChild);
        
