            updateFamilyHotelCostingJSON();
        <?php } ?>
    });

    // Updated 01 Feb 2026
    function updateHotelCostingJSON() 
    {
        let costingData = {};
        
        // Build a map to track hotel information
        let hotelInfoMap = {};
        
        console.log("=== STEP 1: Collecting hotel information ===");
        
        // First pass: collect all hotel data
        $(".hotel-row").each(function(index) 
        {
            var parentRow = $(this);
            var category  = parentRow.data("category");
            var hotelName = parentRow.data("hotel");
            var hotelId   = parentRow.data("hotel-id");
            var hotelCity = parentRow.data("hotel-city");
            var room      = parentRow.data("room");
            var nightNumbersAttr = parentRow.data("night-numbers");
            var hasSamePrice = parentRow.data("has-same-price");
            
            if (!category || !hotelName) return;
            
            // Create a unique key for this hotel + night group
            // This is CRITICAL: Different night groups should be treated separately
            var nightGroupKey = nightNumbersAttr || 'all';
            var hotelKey = hotelName + '_' + nightGroupKey;
            
            if (!hotelInfoMap[category]) hotelInfoMap[category] = {};
            if (!hotelInfoMap[category][hotelKey]) {
                hotelInfoMap[category][hotelKey] = {
                    hotelName: hotelName,
                    id: hotelId,
                    city: hotelCity,
                    nightGroup: nightNumbersAttr,
                    allNights: new Set(),
                    rooms: new Set(),
                    nightsByRoom: {},
                    hasSamePriceAllNights: hasSamePrice
                };
            }
            
            // Parse night numbers
            let nightNumbers = [];
            if (nightNumbersAttr !== undefined && nightNumbersAttr !== null) {
                if (Array.isArray(nightNumbersAttr)) {
                    nightNumbers = nightNumbersAttr;
                } else if (typeof nightNumbersAttr === 'string') {
                    if (nightNumbersAttr.trim() !== '') {
                        nightNumbers = nightNumbersAttr.split('_').map(n => {
                            let num = parseInt(n.trim());
                            return isNaN(num) ? null : num;
                        }).filter(n => n !== null);
                    }
                } else if (typeof nightNumbersAttr === 'number') {
                    nightNumbers = [nightNumbersAttr];
                }
            }
            
            console.log(`Row ${index}: Hotel=${hotelName}, NightGroup=${nightGroupKey}, Room=${room}, Nights=${nightNumbers.join(',')}`);
            
            // Add to sets
            nightNumbers.forEach(night => {
                if (night !== null && !isNaN(night)) {
                    hotelInfoMap[category][hotelKey].allNights.add(night);
                }
            });
            
            hotelInfoMap[category][hotelKey].rooms.add(room);
            
            // Track nights for this specific room
            if (!hotelInfoMap[category][hotelKey].nightsByRoom[room]) {
                hotelInfoMap[category][hotelKey].nightsByRoom[room] = new Set();
            }
            nightNumbers.forEach(night => {
                if (night !== null && !isNaN(night)) {
                    hotelInfoMap[category][hotelKey].nightsByRoom[room].add(night);
                }
            });
        });

        // Debug: Show collected hotel info
        console.log("=== Collected Hotel Info ===");
        for (let category in hotelInfoMap) {
            console.log(`Category: ${category}`);
            for (let hotelKey in hotelInfoMap[category]) {
                let info = hotelInfoMap[category][hotelKey];
                console.log(`  Hotel Key: ${hotelKey}`);
                console.log(`    Hotel Name: ${info.hotelName}`);
                console.log(`    Night Group: ${info.nightGroup}`);
                console.log(`    All Nights: ${Array.from(info.allNights).sort((a,b) => a-b).join(',')}`);
                console.log(`    Rooms: ${Array.from(info.rooms).join(', ')}`);
                console.log(`    Has Same Price All Nights: ${info.hasSamePriceAllNights}`);
                for (let room in info.nightsByRoom) {
                    console.log(`    Room "${room}" nights: ${Array.from(info.nightsByRoom[room]).sort((a,b) => a-b).join(',')}`);
                }
            }
        }
        
        console.log("=== STEP 2: Building costing data ===");
        
        // Second pass: build costing data
        $(".hotel-row").each(function(index) 
        {
            var parentRow = $(this);
            var category  = parentRow.data("category");
            var hotelName = parentRow.data("hotel");
            var room      = parentRow.data("room");
            var occupancy = parentRow.data("occupancy");
            var isPRPN    = parentRow.data("is-prpn") === true;
            var hasSamePrice = parentRow.data("has-same-price");
            var nightNumbersAttr = parentRow.data("night-numbers");
            
            if (!category || !hotelName || !room || !occupancy) return;

            // Find the correct hotel info by matching night group
            var hotelInfo = null;
            var hotelKey = null;
            
            if (hotelInfoMap[category]) {
                // Look for hotel with matching name AND night group
                for (let key in hotelInfoMap[category]) {
                    if (hotelInfoMap[category][key].hotelName === hotelName) {
                        // Check if night group matches
                        if (hotelInfoMap[category][key].nightGroup === nightNumbersAttr) {
                            hotelInfo = hotelInfoMap[category][key];
                            hotelKey = key;
                            break;
                        }
                    }
                }
            }
            
            if (!hotelInfo) return;
            
            // Get nights for this specific night group
            var allNights = Array.from(hotelInfo.allNights).sort((a, b) => a - b);
            var roomNights = hotelInfo.nightsByRoom[room] ? 
                Array.from(hotelInfo.nightsByRoom[room]).sort((a, b) => a - b) : 
                [];
            
            // Determine hotel identifier - use the night group from data
            var hotelIdentifier = hotelName;
            if (allNights.length > 0) {
                hotelIdentifier = hotelName + '_' + allNights.join('_');
            }
            
            // Check if we need metadata
            var needsMetadata = false;
            if (hasSamePrice === false || hasSamePrice === 'false') {
                needsMetadata = true;
            }
            
            console.log(`Row ${index}: Hotel=${hotelIdentifier}, NightGroup=${nightNumbersAttr}, NeedsMetadata=${needsMetadata}`);
            
            // Determine room category
            var roomCategory = room;
            if (needsMetadata && roomNights.length > 0) {
                roomCategory = room + '_nights_' + roomNights.join('_');
            }
            
            // Get the amount
            var amount = 0;
            if (isPRPN) {
                amount = parseFloat(parentRow.closest('li').find('.per-night').val()) || 0;
            } else {
                var $nightTotal = parentRow.closest('li').find('.night-total');
                amount = $nightTotal.length ? parseFloat($nightTotal.val()) || 0 : 0;
            }

            if (!costingData[category]) costingData[category] = {};
            if (!costingData[category][hotelIdentifier]) {
                costingData[category][hotelIdentifier] = {};
            }
            
            // Add metadata if needed
            if (needsMetadata && Object.keys(costingData[category][hotelIdentifier]).length === 0) {
                // Add metadata exactly like PHP does
                costingData[category][hotelIdentifier]['hotel_name'] = hotelName;
                costingData[category][hotelIdentifier]['hotel_id'] = hotelInfo.id;
                costingData[category][hotelIdentifier]['hotel_city'] = hotelInfo.city;
                costingData[category][hotelIdentifier]['nights'] = allNights.length > 0 ? allNights : roomNights;
                
                console.log(`Added metadata to ${hotelIdentifier}`);
            }
            
            if (!costingData[category][hotelIdentifier][roomCategory]) {
                costingData[category][hotelIdentifier][roomCategory] = [];
            }

            // Check if this occupancy already exists
            let existsIndex = -1;
            for (let i = 0; i < costingData[category][hotelIdentifier][roomCategory].length; i++) {
                if (costingData[category][hotelIdentifier][roomCategory][i].startsWith(occupancy)) {
                    existsIndex = i;
                    break;
                }
            }
            
            if (existsIndex >= 0) {
                costingData[category][hotelIdentifier][roomCategory][existsIndex] = occupancy + "__" + amount;
            } else {
                costingData[category][hotelIdentifier][roomCategory].push(occupancy + "__" + amount);
            }
        });
        
        console.log("=== FINAL COSTING DATA ===");
        console.log(JSON.stringify(costingData, null, 2));
        
        $("#hotel_costing_category_wise").val(JSON.stringify(costingData));
        $("#hotel_cost").val(JSON.stringify(costingData));
        triggerMarginTableLoad();
    }

    function updateFamilyHotelCostingJSON() {
        let costingData = {};

        $(".hotel-row").each(function() {
            var parentRow = $(this);
            var category  = parentRow.data("category");   
            var hotelId   = parentRow.data("hotel-id");
            var amount    = parseFloat(parentRow.find(".night-total").val()) || 0;

            if (!category || !hotelId) return;

            if (!costingData[category]) costingData[category] = {};
            if (!costingData[category][hotelId]) costingData[category][hotelId] = 0;

            costingData[category][hotelId] += amount;
        });

        $("#hotel_costing_category_wise").val(JSON.stringify(costingData));
    }

  
  

    function updateUpdownTotal() 
    {
        let total = 0;
        let tollTotal = 0;
        $(".transport-row_out_hotel").each(function() {
            let price   = parseFloat($(this).find(".price").val())   || 0;
            let toll    = parseFloat($(this).find(".toll").val())    || 0;
            let parking = parseFloat($(this).find(".parking").val()) || 0;
            let qty     = parseFloat($(this).find(".qty").val())     || 1;

            let oneWay = (price + parking) * qty;
            let upDown = oneWay * 2;

            $(this).find(".total").val(oneWay);
            $(this).find(".updown_total").val(upDown);

            total += upDown; 
            tollTotal += (toll); 
        });

        $("#updown_total").val(total);
        $("#outside_hotel_toll").val(tollTotal);
        updateFinalTransport();
        updateFinalToll();
    }
