    let activityCostsByDay = [];

   
    
    function recalcActivityTotals(mainRowId) {
        // --- Adult part ---
        let adultPriceEl = document.querySelector(`.activity_adult_price[data-row="${mainRowId}"]`);
        if (!adultPriceEl) {
            console.warn(`Adult price element not found for row ${mainRowId}`);
            return;
        }
        let adultPrice = parseFloat(adultPriceEl.value) || 0;
        let adultsEl = document.querySelector(`.activity_adults_count[data-row="${mainRowId}"]`);
        let adults = adultsEl ? parseInt(adultsEl.value) || 0 : 0;
        let adultTotal = adultPrice * adults;

        // Update adult total field
        let adultTotalEl = document.querySelector(`.activity_adult_total[data-row="${mainRowId}"]`);
        if (adultTotalEl) adultTotalEl.value = Math.round(adultTotal);

        // --- Child part: simple or age‑based ---
        let childTotal = 0;

        // Check for simple child price element (if present)
        let simpleChildPriceEl = document.querySelector(`.activity_child_price[data-row="${mainRowId}"]`);
        if (simpleChildPriceEl) {
            // Simple child pricing (fallback)
            let childPrice = parseFloat(simpleChildPriceEl.value) || 0;
            let childrenEl = document.querySelector(`.activity_children_count[data-row="${mainRowId}"]`);
            let children = childrenEl ? parseInt(childrenEl.value) || 0 : 0;
            childTotal = childPrice * children;
            // Update simple child total field
            let childTotalEl = document.querySelector(`.activity_child_total[data-row="${mainRowId}"]`);
            if (childTotalEl) childTotalEl.value = Math.round(childTotal);
        } else {
            // Age‑based: recalc each age row total and sum them
            let agePriceEls = document.querySelectorAll(`.activity_child_age_price`);
            agePriceEls.forEach(agePriceEl => {
                let row = agePriceEl.dataset.row;
                if (row && row.startsWith(mainRowId + '_child_')) {
                    let price = parseFloat(agePriceEl.value) || 0;
                    let count = parseInt(document.querySelector(`.activity_child_age_count[data-row="${row}"]`)?.value) || 0;
                    let total = price * count;
                    // Update the total field for this age row
                    let totalEl = document.querySelector(`.activity_child_age_total[data-row="${row}"]`);
                    if (totalEl) totalEl.value = Math.round(total);
                    childTotal += total;
                }
            });
        }

        // --- Update global daily totals ---
        let allDayAdultTotal = 0;
        let allDayChildTotal = 0;

        document.querySelectorAll('.activity_adult_total').forEach(el => {
            allDayAdultTotal += parseFloat(el.value) || 0;
        });
        document.querySelectorAll('.activity_child_total').forEach(el => {
            allDayChildTotal += parseFloat(el.value) || 0;
        });
        document.querySelectorAll('.activity_child_age_total').forEach(el => {
            allDayChildTotal += parseFloat(el.value) || 0;
        });

        // Update global inputs (adjust IDs if needed)
        let allDayAdultInput = document.getElementById('all_day_activities_total');
        if (allDayAdultInput) allDayAdultInput.value = Math.round(allDayAdultTotal);
        let allDayChildInput = document.getElementById('all_day_child_activities_total');
        if (allDayChildInput) allDayChildInput.value = Math.round(allDayChildTotal);

        // Update JSON and trigger any dependent functions
        updateActivityCostsByDay();
        if (typeof triggerMarginTableLoad === 'function') triggerMarginTableLoad();
    }

    function recalcGroupTotals(rowId) {
        // Find the group price and count fields for this row
        let priceEl = document.querySelector(`.activity_group_price[data-row="${rowId}"]`);
        let countEl = document.querySelector(`.activity_group_count[data-row="${rowId}"]`);
        if (!priceEl || !countEl) return;

        let price = parseFloat(priceEl.value) || 0;
        let groups = parseInt(countEl.value) || 0;
        let total = price * groups;

        // Update display field
        let displayEl = document.querySelector(`.activity_group_total_display[data-row="${rowId}"]`);
        if (displayEl) displayEl.value = Math.round(total);

        // Update hidden field (if needed elsewhere)
        let hiddenValEl = document.querySelector(`.activity_group_total_val[data-row="${rowId}"]`);
        if (hiddenValEl) hiddenValEl.value = Math.round(total);

        // Refresh all day totals and the hidden #hdn_group_activity_total
        updateActivityCostsByDay();
        if (typeof triggerMarginTableLoad === 'function') triggerMarginTableLoad();
    }

    function updateActivityCostsByDay() {
        // Reset global array
        activityCostsByDay = [];

        // 1. Collect unique days from adult, child-age, and group price elements
        let days = new Set();
        document.querySelectorAll('.activity_adult_price[data-day]').forEach(el => {
            days.add(parseInt(el.dataset.day));
        });
        document.querySelectorAll('.activity_group_price[data-day]').forEach(el => {
            days.add(parseInt(el.dataset.day));
        });
        let daysArray = Array.from(days).sort((a, b) => a - b);

        let totalAdultAllDays = 0;
        let totalChildAllDays = 0;
        let totalGroupAllDays = 0;

        // 2. Process each day
        daysArray.forEach(day => {
            let dayActivities = [];
            let dayTotal = 0;
            let dayAdultTotal = 0;
            let dayChildTotal = 0;
            let dayGroupTotal = 0;

            // ----- Adult & Child activities (unchanged) -----
            let adultPriceEls = document.querySelectorAll(`.activity_adult_price[data-day="${day}"]`);
            adultPriceEls.forEach(adultPriceEl => {
                let mainRowId = adultPriceEl.dataset.row;
                let activityName = adultPriceEl.dataset.activity;
                let siteId = adultPriceEl.dataset.siteId ? parseInt(adultPriceEl.dataset.siteId) : null;
                let activityId = adultPriceEl.dataset.activityId ? parseInt(adultPriceEl.dataset.activityId) : null;

                let adultPrice = parseFloat(adultPriceEl.value) || 0;
                let adults = parseInt(document.querySelector(`.activity_adults_count[data-row="${mainRowId}"]`)?.value) || 0;
                let adultTotal = adultPrice * adults;

                let childTotal = 0;
                let childAgeRanges = [];

                let simpleChildPriceEl = document.querySelector(`.activity_child_price[data-row="${mainRowId}"]`);
                if (simpleChildPriceEl) {
                    let childPrice = parseFloat(simpleChildPriceEl.value) || 0;
                    let children = parseInt(document.querySelector(`.activity_children_count[data-row="${mainRowId}"]`)?.value) || 0;
                    childTotal = childPrice * children;
                } else {
                    let agePriceEls = document.querySelectorAll('.activity_child_age_price');
                    agePriceEls.forEach(agePriceEl => {
                        let row = agePriceEl.dataset.row;
                        if (row && row.startsWith(mainRowId + '_child_')) {
                            let ageRangeId = agePriceEl.dataset.ageRangeId ? parseInt(agePriceEl.dataset.ageRangeId) : null;
                            let ageFrom = agePriceEl.dataset.ageFrom ? parseInt(agePriceEl.dataset.ageFrom) : null;
                            let ageTo = agePriceEl.dataset.ageTo ? parseInt(agePriceEl.dataset.ageTo) : null;
                            let price = parseFloat(agePriceEl.value) || 0;
                            let count = parseInt(document.querySelector(`.activity_child_age_count[data-row="${row}"]`)?.value) || 0;
                            let total = parseFloat(document.querySelector(`.activity_child_age_total[data-row="${row}"]`)?.value) || 0;
                            childTotal += total;
                            childAgeRanges.push({
                                age_range_id: ageRangeId,
                                age_from: ageFrom,
                                age_to: ageTo,
                                price: price,
                                count: count,
                                total: total
                            });
                        }
                    });
                }

                let activityTotal = adultTotal + childTotal;
                dayTotal += activityTotal;
                dayAdultTotal += adultTotal;
                dayChildTotal += childTotal;

                let activity = {
                    activity_id: activityId,
                    activity_name: activityName,
                    site_id: siteId,
                    adult_price: adultPrice,
                    adult_count: adults,
                    adult_total: Math.round(adultTotal)
                };

                if (simpleChildPriceEl) {
                    let childPrice = parseFloat(simpleChildPriceEl.value) || 0;
                    let children = parseInt(document.querySelector(`.activity_children_count[data-row="${mainRowId}"]`)?.value) || 0;
                    activity.child_price = childPrice;
                    activity.child_count = children;
                    activity.child_total = Math.round(childPrice * children);
                } else if (childAgeRanges.length > 0) {
                    activity.child_age_ranges = childAgeRanges;
                    activity.child_total = Math.round(childTotal);
                } else {
                    activity.child_total = 0;
                }

                dayActivities.push(activity);
            });

            // ----- Group activities (preserve each individually) -----
            let groupPriceEls = document.querySelectorAll(`.activity_group_price[data-day="${day}"]`);
            groupPriceEls.forEach(priceEl => {
                let rowId = priceEl.dataset.row;
                let activityId = priceEl.dataset.activityId ? parseInt(priceEl.dataset.activityId) : null;
                let siteId = priceEl.dataset.siteId ? parseInt(priceEl.dataset.siteId) : null;
                let activityName = priceEl.dataset.activity || 'Group Activity';
                let groupSize = priceEl.dataset.groupSize ? parseInt(priceEl.dataset.groupSize) : 0;
                
                let groupPrice = parseFloat(priceEl.value) || 0;
                let countEl = document.querySelector(`.activity_group_count[data-row="${rowId}"]`);
                let groups = countEl ? (parseInt(countEl.value) || 0) : 0;
                let groupTotal = groupPrice * groups;
                
                if (groupTotal > 0) {
                    dayGroupTotal += groupTotal;
                    dayTotal += groupTotal;
                    
                    dayActivities.push({
                        activity_id: activityId,
                        activity_name: activityName,
                        site_id: siteId,
                        is_group: true,
                        group_size: groupSize,
                        group_price: groupPrice,
                        group_count: groups,
                        group_total: Math.round(groupTotal)
                    });
                }
            });

            totalAdultAllDays += dayAdultTotal;
            totalChildAllDays += dayChildTotal;
            totalGroupAllDays += dayGroupTotal;

            activityCostsByDay.push({
                day: day,
                activities: dayActivities,
                day_total: Math.round(dayTotal),
                day_adult_total: Math.round(dayAdultTotal),
                day_child_total: Math.round(dayChildTotal),
                day_group_total: Math.round(dayGroupTotal)
            });
        });

        // 3. Update JSON field
        let finalArray = { activity_data: activityCostsByDay };
        let activityCostInput = document.getElementById('activity_cost');
        if (activityCostInput) {
            activityCostInput.value = JSON.stringify(finalArray);
        }

        // 4. Update global adult/child totals (excluding groups)
        let allDayAdultInput = document.getElementById('all_day_activities_total');
        if (allDayAdultInput) allDayAdultInput.value = Math.round(totalAdultAllDays);
        let allDayChildInput = document.getElementById('all_day_child_activities_total');
        if (allDayChildInput) allDayChildInput.value = Math.round(totalChildAllDays);

        // 5. Update hidden group total field
        let groupTotalHidden = document.getElementById('hdn_group_activity_total');
        if (groupTotalHidden) groupTotalHidden.value = Math.round(totalGroupAllDays);

        return finalArray;
    }

    function initializeActivityTotals() {
        // Collect all main row IDs from .activity_adult_price elements
        let mainRowIds = new Set();
        document.querySelectorAll('.activity_adult_price').forEach(el => {
            let rowId = el.getAttribute('data-row');
            if (rowId) mainRowIds.add(rowId);
        });

        // Recalculate totals for each main row
        mainRowIds.forEach(rowId => recalcActivityTotals(rowId));

        // Add event listener for adult price changes
        document.querySelectorAll('.activity_adult_price').forEach(input => {
            input.addEventListener('input', function() {
                let rowId = this.getAttribute('data-row');
                recalcActivityTotals(rowId);
            });
        });

        // Add event listener for simple child price changes (if any)
        document.querySelectorAll('.activity_child_price').forEach(input => {
            input.addEventListener('input', function() {
                let rowId = this.getAttribute('data-row');
                recalcActivityTotals(rowId);
            });
        });

        // Add event listener for age‑based child price changes
        document.querySelectorAll('.activity_child_age_price').forEach(input => {
            input.addEventListener('input', function() {
                let row = this.getAttribute('data-row');
                // Row ID format: act_row_1_1_0_child_0 → extract main part
                let mainRowId = row.split('_child_')[0];
                recalcActivityTotals(mainRowId);
            });
        });

        // Group activity: price change
        document.querySelectorAll('.activity_group_price').forEach(input => {
            input.addEventListener('input', function() {
                let rowId = this.getAttribute('data-row');
                recalcGroupTotals(rowId);
            });
        });

        // Group activity: number of groups change
        document.querySelectorAll('.activity_group_count').forEach(input => {
            input.addEventListener('input', function() {
                let rowId = this.getAttribute('data-row');
                recalcGroupTotals(rowId);
            });
        });

        let groupRowIds = new Set();
        document.querySelectorAll('.activity_group_price').forEach(el => {
            let rowId = el.getAttribute('data-row');
            if (rowId) groupRowIds.add(rowId);
        });
        groupRowIds.forEach(rowId => recalcGroupTotals(rowId));
        // Generate JSON once on load
        updateActivityCostsByDay();
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initializeActivityTotals);
    } else {
        initializeActivityTotals();
    }

    function recalcFinalTransport() {
        let bundle = parseFloat($("#final_transport_without_toll").val()) || 0;
        let toll   = parseFloat($("#final_toll_price").val()) || 0;
        let total = bundle + toll;
        $("#final_transport").val(total);
    }
    
    // New 06 Feb 2026 updated
    $(document).on('input', '.per-night', function() {
        let $input = $(this);
        let nights = parseInt($input.data('nights')) || 1;
        let indexKey = $input.data('index');
        let perNight = parseFloat($input.val()) || 0;

        console.log('=== INPUT CHANGED ===', { indexKey, nights, perNight });
        
        // Debug the current row data
        let $row = $input.closest('.hotel-row');
        let occupancyText = $row.data('occupancy') || '';
        console.log('Row data:', {
            hotelId: $row.data('hotel-id'),
            hotelName: $row.data('hotel-name'),
            category: $row.data('category'),
            occupancy: occupancyText
        });

        // Check if this is PRPN (Per Room Per Night) or PP (Per Person)
        let isPRPN = $row.data('is-prpn') === true;
        console.log('Is PRPN?', isPRPN);

        // Update the total display
        let total = perNight * nights;
        $input.closest('.hotel-row').find('.night-total').val(total);

        // Get current hotel_arr value
        let hotelArrValue = $('input[name="hotel_arr"]').val();
        if (!hotelArrValue) {
            console.log('No hotel_arr value found');
            return;
        }

        try {
            let hotelData = JSON.parse(hotelArrValue);
            console.log('Available hotels:', hotelData.map(h => ({id: h.hotel_id, night: h.night, name: h.hotel_name})));
            
            // Parse indexKey - format: "7_7_Standard Room (king Bed)_0_nights_1_5"
            let keyParts = indexKey.split('_');
            console.log('Key parts:', keyParts);
            
            if (keyParts.length < 4) {
                console.log('Invalid key format - expected at least 4 parts');
                return;
            }

            // Extract parts
            let targetHotelId = keyParts[0]; // "7"
            
            let nightsIndex = keyParts.indexOf('nights');
            if (nightsIndex === -1) {
                console.log('"nights" not found in key parts');
                return;
            }
            
            // TT index should be before "nights"
            let ttIndex = parseInt(keyParts[nightsIndex - 1]); // "0"
            
            // Category is everything between hotelId and ttIndex
            let targetCategory = keyParts.slice(1, nightsIndex - 1).join('_'); // "7_Standard Room (king Bed)"
            
            // Get ALL nights in this combination (after "nights")
            let targetNights = [];
            for (let i = nightsIndex + 1; i < keyParts.length; i++) {
                let nightNum = parseInt(keyParts[i]);
                if (!isNaN(nightNum) && nightNum > 0) {
                    targetNights.push(nightNum);
                }
            }
            
            console.log('Parsed:', {
                targetHotelId,
                targetCategory,
                ttIndex,
                targetNights: targetNights
            });

            let updated = false;
            
            // Determine group type
            let group_type = "<?= $this->input->get('hdn_group_type'); ?>";
            console.log('Group type:', group_type);
            
            // Map occupancy text to codes
            let occupancyMap = {};
            if (group_type === "individual") {
                occupancyMap = {
                    'Single Occupancy': { code: '1(A)', multiplier: 1 },
                    'Double Occupancy': { code: '2(A)', multiplier: 2 },
                    'Triple Occupancy': { code: '3(A)', multiplier: 3 },
                    'Quad Occupancy': { code: '4(A)', multiplier: 4 },
                    'Quint Occupancy': { code: '5(A)', multiplier: 5 },
                    'Sext Occupancy': { code: '6(A)', multiplier: 6 },
                    'CNB Occupancy': { code: '1(C)', suffix: 'CNB', multiplier: 1 },
                    'CWB Occupancy': { code: '1(C)', suffix: 'CWB', multiplier: 1 },
                };
            } else if (group_type === "family") {
                occupancyMap = {
                    'Single Occupancy': { code: '1(A)', multiplier: 1 },
                    'Double Occupancy': { code: '2(A)', multiplier: 1 },
                    'Triple Occupancy': { code: '3(A)', multiplier: 1 },
                    'Single Child Occupancy': { code: '1(C)', suffix: 'CNB', multiplier: 1 },
                    'Double Child Occupancy': { code: '2(C)', suffix: 'CNB', multiplier: 1 },
                    'Triple Child Occupancy': { code: '3(C)', suffix: 'CNB', multiplier: 1 }
                };
            }
            
            let occupancyInfo = occupancyMap[occupancyText.trim()];
            
            if (!occupancyInfo) {
                console.log('No occupancy mapping found for:', occupancyText);
                console.log('Available mappings:', Object.keys(occupancyMap));
                return;
            }
            
            let targetOccupancyCode = occupancyInfo.code;
            let suffix = occupancyInfo.suffix || ''; // Get suffix for CNB/CWB
            
            // IMPORTANT: Only use multiplier for PP (Per Person), NOT for PRPN
            let multiplier = isPRPN ? 1 : occupancyInfo.multiplier;
            
            console.log('Target code:', targetOccupancyCode, 'Suffix:', suffix, 'Is PRPN:', isPRPN, 'Multiplier:', multiplier);

            // Update ALL nights in the combination
            for (let i = 0; i < hotelData.length; i++) {
                let hotel = hotelData[i];
                
                // Check if this hotel entry matches our hotel ID AND is one of the target nights
                if (hotel.hotel_id == targetHotelId && targetNights.includes(hotel.night)) {
                    console.log('Found matching hotel for update:', {
                        id: hotel.hotel_id,
                        night: hotel.night,
                        name: hotel.hotel_name
                    });
                    
                    try {
                        let roomDetails = JSON.parse(hotel.hotel_room_details);
                        console.log('Room details keys for night', hotel.night, ':', Object.keys(roomDetails));
                        
                        // Check if the category exists
                        if (!roomDetails[targetCategory]) {
                            console.log('Category key not found for night', hotel.night, ':', targetCategory);
                            console.log('Available keys:', Object.keys(roomDetails));
                            
                            // Try to find a similar key (maybe different formatting)
                            let matchingKey = null;
                            for (let key of Object.keys(roomDetails)) {
                                if (key.includes(targetCategory) || targetCategory.includes(key)) {
                                    matchingKey = key;
                                    console.log('Found similar key:', key);
                                    break;
                                }
                            }
                            
                            if (!matchingKey) {
                                console.log('No matching category found for night', hotel.night);
                                continue;
                            }
                            
                            targetCategory = matchingKey;
                        }
                        
                        console.log('Using category for night', hotel.night, ':', targetCategory);
                        let categoryArray = roomDetails[targetCategory];
                        
                        if (categoryArray && categoryArray[ttIndex]) {
                            let roomObj = categoryArray[ttIndex];
                            
                            // Update room types
                            if (roomObj.room_type && Array.isArray(roomObj.room_type)) {
                                console.log('Room types before update (night', hotel.night, '):', roomObj.room_type);
                                
                                let roomTypeUpdated = false;
                                for (let j = 0; j < roomObj.room_type.length; j++) {
                                    let rt = roomObj.room_type[j];
                                    let parts = rt.trim().split(' ');
                                    
                                    if (parts.length >= 2) {
                                        let occupancyCode = parts[0];
                                        
                                        // Check if this is the matching occupancy
                                        let matches = false;
                                        
                                        // CRITICAL FIX: Handle adult occupancy (with or without suffix)
                                        if (occupancyCode === targetOccupancyCode) {
                                            // Check for CNB/CWB child occupancy
                                            if (suffix) {
                                                // For CNB/CWB, check if suffix matches
                                                if (parts.length >= 3 && parts[2] === suffix) {
                                                    matches = true;
                                                }
                                            } else {
                                                // For adult occupancy (1(A), 2(A), 3(A), etc.)
                                                // Check if it's NOT a child occupancy (doesn't have CNB/CWB suffix)
                                                // OR if it does have CNB/CWB but it's still adult occupancy code
                                                if (parts.length === 2) {
                                                    // No suffix - definitely adult
                                                    matches = true;
                                                } else if (parts.length >= 3) {
                                                    // Has suffix, check if it's not a child occupancy
                                                    // Adult occupancy might have CNB/CWB suffix in data, but we should still update it
                                                    matches = true;
                                                }
                                            }
                                        }
                                        
                                        if (matches) {
                                            // FIXED: For PRPN, use perNight directly (no multiplier)
                                            // For PP, multiply by occupancy multiplier
                                            let updatedPrice = isPRPN ? perNight : (perNight * multiplier);
                                            
                                            // Build the new price string
                                            let newPriceStr = occupancyCode + ' ' + updatedPrice;
                                            
                                            // Add suffix for CNB/CWB if it exists in our mapping
                                            if (suffix) {
                                                newPriceStr += ' ' + suffix;
                                            } else {
                                                // For adult, preserve any existing suffix from original data
                                                if (parts.length > 2) {
                                                    newPriceStr += ' ' + parts.slice(2).join(' ');
                                                }
                                            }
                                            
                                            roomObj.room_type[j] = newPriceStr;
                                            roomTypeUpdated = true;
                                            updated = true;
                                            console.log('Updated room type to (night', hotel.night, '):', roomObj.room_type[j], 
                                                    'Is PRPN:', isPRPN, 'Multiplier used:', multiplier);
                                            break;
                                        }
                                    }
                                }
                                
                                if (roomTypeUpdated) {
                                    // Update the hotel data for this specific night
                                    hotel.hotel_room_details = JSON.stringify(roomDetails);
                                    console.log('Updated hotel data for night', hotel.night);
                                } else {
                                    console.log('Room type not found for code (night', hotel.night, '):', targetOccupancyCode, 
                                            'Suffix:', suffix || 'none');
                                    console.log('Available room types:', roomObj.room_type);
                                    
                                    // DEBUG: Try to find what's available
                                    for (let j = 0; j < roomObj.room_type.length; j++) {
                                        let rt = roomObj.room_type[j];
                                        console.log('  - Checking:', rt, 'code:', rt.trim().split(' ')[0]);
                                    }
                                }
                            }
                        } else {
                            console.log('TT index not found or category array empty for night', hotel.night);
                        }
                        
                    } catch (e) {
                        console.error('Error processing room details for night', hotel.night, ':', e);
                    }
                }
            }
            
            if (updated) {
                // Update the hidden input with ALL changes
                $('input[name="hotel_arr"]').val(JSON.stringify(hotelData));
                console.log('SUCCESS: hotel_arr updated for all nights:', targetNights);
                
                // Log verification
                console.log('Verification - updated hotel_arr preview:', 
                    JSON.stringify(JSON.parse($('input[name="hotel_arr"]').val()).filter(h => 
                        h.hotel_id == targetHotelId && targetNights.includes(h.night)
                    ), null, 2));
            } else {
                console.log('No updates were made. Check debug logs above.');
            }

        } catch (error) {
            console.error('Error parsing hotel_arr:', error);
        }
    });

</script>

