<script>
    
    $(document).ready(function() {
        let cutoff_sitescene = '2026-04-15 00:00:00';
        let saved_last_quotation_date = "<?= $first_created_date ?? '' ?>";

        if (
            saved_last_quotation_date === '' ||
            new Date(saved_last_quotation_date) >= new Date(cutoff_sitescene)
        ) {
            
            function updateTicketCosts() {
                var ticketsByDay = {};

                // Find all ticket containers
                $('.alert.alert-dark').each(function() {
                    var $alert = $(this);

                    // Check if this is a ticket container (has ticket-row)
                    if ($alert.find('.ticket-row').length === 0) {
                        return;
                    }

                    var day = parseInt($alert.data('day'));
                    if (isNaN(day)) {
                        var parentWithDay = $alert.closest('[data-day]');
                        if (parentWithDay.length) {
                            day = parseInt(parentWithDay.data('day'));
                        } else {
                            day = 0;
                        }
                    }

                    // Get site info (adjust if needed)
                    var siteInfo = $alert.siblings('.site-info').first() ||
                                $alert.closest('div[style*="margin:0 0"]').find('.site-info').first();
                    var siteId = siteInfo ? siteInfo.data('site-id') : '';
                    var siteName = siteInfo ? siteInfo.data('site-name') :
                                $alert.closest('div[style*="margin:0 0"]').find('.txt-edit').text().trim();

                    var ticketRow = $alert.find('.ticket-row').first();

                    if (!ticketsByDay[day]) {
                        ticketsByDay[day] = { day: day, tickets: [] };
                    }

                    if (ticketRow.find('.adult_ticket').length) {
                        processIndividualTicket($alert, siteId, siteName, day, ticketsByDay);
                    } else if (ticketRow.find('.group_ticket').length) {
                        processGroupTicket($alert, siteId, siteName, day, ticketsByDay);
                    }
                });

                // Convert to array and sort
                var sitesceneCosts = [];
                var days = Object.keys(ticketsByDay).sort(function(a, b) {
                    return parseInt(a) - parseInt(b);
                });
                days.forEach(function(dayKey) {
                    sitesceneCosts.push(ticketsByDay[dayKey]);
                });

                $('#sitescene_cost').val(JSON.stringify(sitesceneCosts));

                // Calculate total child price across all tickets
                var totalChildPriceAll = 0;
                for (var d in ticketsByDay) {
                    if (ticketsByDay.hasOwnProperty(d)) {
                        for (var t of ticketsByDay[d].tickets) {
                            if (t.age_based && t.child_ranges) {
                                for (var r of t.child_ranges) {
                                    totalChildPriceAll += (r.subtotal || 0);
                                }
                            } else if (t.child_total !== undefined) {
                                totalChildPriceAll += t.child_total;
                            }
                        }
                    }
                }
                $('#hdn_final_child_ticket_price').val(totalChildPriceAll);
                console.log("Ticket costs by day:", sitesceneCosts);
            }

            function processIndividualTicket($alert, siteId, siteName, day, ticketsByDay) {
                // Find adult row (first .ticket-row.adult-row)
                var $adultRow = $alert.find('.ticket-row.adult-row').first();
                if (!$adultRow.length) return;

                var adultPrice = parseFloat($adultRow.find('.adult_ticket').val()) || 0;
                // var adultCount = parseInt($adultRow.find('.adult_ticket').data('adults')) || 0;
                var adultCount = <?= (int)$this->input->get('number_of_adults'); ?> || 0;

                // Check for age-based child rows
                var $childRangeRows = $alert.find('tr.child-range-row');
                var isAgeBased = ($childRangeRows.length > 0);

                var childTotal = 0;
                var totalChildCount = 0;
                var childPriceForDisplay = 0;
                var childRangesData = [];

                if (isAgeBased) {
                    // Process each age range row
                    $childRangeRows.each(function() {
                        var $row = $(this);
                        var $cells = $row.find('td');
                        if ($cells.length < 4) return;

                        // First cell: "Age X-Y"
                        var ageRangeText = $cells.eq(0).text().trim().replace('Age ', '');
                        // Second cell: input with class child_ticket_range_price
                        var price = parseFloat($cells.eq(1).find('.child_ticket_range_price').val()) || 0;
                        // Third cell: "x N"
                        var qtyText = $cells.eq(2).text().trim();
                        var qtyMatch = qtyText.match(/x\s*(\d+)/);
                        var count = qtyMatch ? parseInt(qtyMatch[1]) : 0;
                        var subtotal = price * count;

                        // Update the total field in fourth cell
                        $cells.eq(3).find('.child_ticket_range_total').val(subtotal);

                        childTotal += subtotal;
                        totalChildCount += count;

                        childRangesData.push({
                            age_range: ageRangeText,
                            price: price,
                            count: count,
                            subtotal: subtotal
                        });
                    });
                    childPriceForDisplay = (totalChildCount > 0) ? (childTotal / totalChildCount) : 0;
                } else {
                    // Simple child ticket (single row)
                    var $childRow = $alert.find('tr.child-row');
                    if ($childRow.length) {
                        var $childInput = $childRow.find('.child_ticket');
                        if ($childInput.length) {
                            childPriceForDisplay = parseFloat($childInput.val()) || 0;
                            totalChildCount = parseInt($childInput.data('children')) || 0;
                            childTotal = childPriceForDisplay * totalChildCount;
                            $childRow.find('.child_ticket_row_total').val(childTotal);
                        }
                    }
                }
                
                totalChildCount = <?= (int)$this->input->get('number_of_child'); ?> || 0;

                // Guide conditions (same as before)
                var guide = "<?php echo $this->input->get('guide'); ?>";
                var totalGuests = adultCount + totalChildCount;
                var finalAdultCount = adultCount;
                var last_quotation_date = "<?php echo $this->input->get('last_quotation_date'); ?>";
                var kok_cutoff_date = '2026-03-21 16:05:00';
                var shymbuk_cutoff_date = '2026-07-17 11:40:00';
                var saved_last_quotation_date = "<?php echo $first_created_date ?? ''; ?>";
                if (last_quotation_date == '' || last_quotation_date > kok_cutoff_date) {
                    if (guide === "yes" && siteId == 4 && totalGuests < 2) finalAdultCount = adultCount + 1;
                } else {
                    if (guide === "yes" && siteId == 4 && totalGuests < 4) finalAdultCount = adultCount + 1;
                }
                if (saved_last_quotation_date == '' || saved_last_quotation_date > shymbuk_cutoff_date) {
                    if (guide === "yes" && siteId == 1) finalAdultCount = adultCount + 1;
                }
                else{
                    if (guide === "yes" && siteId == 1 && totalGuests < 4) finalAdultCount = adultCount + 1;
                }
                if (guide === "yes" && siteId == 297 && totalGuests < 6) finalAdultCount = adultCount + 1;

                var adultTotal = finalAdultCount * adultPrice;
                var totalCost = adultTotal + childTotal;
                var ticketFor = $adultRow.find('td').eq(0).text().trim();
                $adultRow.find('.adult_ticket_row_total').val(adultTotal);

                var ticketObj = {
                    ticket_type: 'individual',
                    ticket_for: ticketFor,
                    price: adultPrice,
                    adult_count: adultCount,
                    adult_total: adultTotal,
                    total: totalCost,
                    sitescene: siteName,
                    site_id: siteId ? siteId.toString() : '',
                    age_based: isAgeBased
                };

                if (isAgeBased) {
                    ticketObj.child_ranges = childRangesData;
                } else {
                    ticketObj.child_price = childPriceForDisplay;
                    ticketObj.child_count = totalChildCount;
                    ticketObj.child_total = childTotal;
                }

                ticketsByDay[day].tickets.push(ticketObj);
            }
            
            // Helper to collect detailed range data (optional, for debugging or later use)
            function collectChildRanges(row) {
                var ranges = [];
                row.find('.child-range-row').each(function() {
                    var $rangeRow = $(this);
                    var ageText = $rangeRow.find('.col-md-6').text().trim(); // e.g., "Age 0-6"
                    var price = parseFloat($rangeRow.find('.child_ticket_range_price').val()) || 0;
                    var countText = $rangeRow.find('.col-md-1').text().trim();
                    var countMatch = countText.match(/x\s*(\d+)/);
                    var count = countMatch ? parseInt(countMatch[1]) : 0;
                    var subtotal = price * count;
                    ranges.push({
                        age_range: ageText.replace('Age ', ''),
                        price: price,
                        count: count,
                        subtotal: subtotal
                    });
                });
                return ranges;
            }
            
            function processGroupTicket(row, siteId, siteName, day, ticketsByDay) {
                var groupPrice = parseFloat(row.find('.group_ticket').val()) || 0;
                var groupCount = parseInt(row.find('.group_count').val()) || 0;
                var totalCost = groupPrice * groupCount;
                var groupSize = parseInt(row.find('.group_ticket').data('group-size')) || 0;
                // var ticketFor = row.find('.col-md-3 span').text().trim();
                var ticketFor = row.find('td:first').text().trim();
                
                // Update display field
                row.find('.ticket_total').val(totalCost);
                
                ticketsByDay[day].tickets.push({
                    ticket_type: 'group',
                    ticket_for: ticketFor,
                    price: groupPrice,
                    group_size: groupSize,
                    group_count: groupCount,
                    adult_total: totalCost,
                    child_total: 0,
                    total: totalCost,
                    sitescene: siteName,
                    site_id: siteId ? siteId.toString() : ''
                });
            }
            
            // Event handlers – include changes on age-based child price inputs
            $(document).on('change keyup', '.adult_ticket, .child_ticket, .group_ticket, .group_count, .child_ticket_range_price', function() {
                updateTicketCosts();
            });

        } else {

            function updateTicketCosts() {
                var ticketsByDay = {}; // Object to group tickets by day
                
                // Find all ticket containers
                $('.alert.alert-dark').each(function() {
                    var $alert = $(this);
                    
                    // Check if this is a ticket container (has ticket-row)
                    if ($alert.find('.ticket-row').length === 0) {
                        return; // Skip if not a ticket container
                    }
                    
                    // Get day from data-day attribute
                    var day = parseInt($alert.data('day'));
                    if (isNaN(day)) {
                        // Try to find day from parent elements
                        var parentWithDay = $alert.closest('[data-day]');
                        if (parentWithDay.length) {
                            day = parseInt(parentWithDay.data('day'));
                        } else {
                            day = 0; // Default to day 0
                        }
                    }
                    
                    // Get site information
                    var siteInfo = $alert.siblings('.site-info').first() || 
                                $alert.closest('div[style*="margin:0 0"]').find('.site-info').first();
                    
                    var siteId = siteInfo ? siteInfo.data('site-id') : '';
                    var siteName = siteInfo ? siteInfo.data('site-name') : 
                                $alert.closest('div[style*="margin:0 0"]').find('.txt-edit').text().trim();
                    
                    var ticketRow = $alert.find('.ticket-row').first();
                    
                    if (!ticketsByDay[day]) {
                        ticketsByDay[day] = {
                            day: day,
                            tickets: []
                        };
                    }
                    
                    if (ticketRow.find('.adult_ticket').length) {
                        // Individual ticket calculation
                        processIndividualTicket(ticketRow, siteId, siteName, day, ticketsByDay);
                    } else if (ticketRow.find('.group_ticket').length) {
                        // Group ticket calculation
                        processGroupTicket(ticketRow, siteId, siteName, day, ticketsByDay);
                    }
                });
                
                // Convert to array and sort
                var sitesceneCosts = [];
                var days = Object.keys(ticketsByDay).sort(function(a, b) {
                    return parseInt(a) - parseInt(b);
                });
                
                days.forEach(function(dayKey) {
                    sitesceneCosts.push(ticketsByDay[dayKey]);
                });
                
                // Store in hidden field
                $('#sitescene_cost').val(JSON.stringify(sitesceneCosts));
                console.log("Ticket costs by day:", sitesceneCosts);
            }
        
            function processIndividualTicket(row, siteId, siteName, day, ticketsByDay) {
                var adultPrice = parseFloat(row.find('.adult_ticket').val()) || 0;
                var adultCount = parseInt(row.find('.adult_ticket').data('adults')) || 0;
                
                var childPrice = 0;
                var childCount = 0;
                var childTicketInput = row.find('.child_ticket');
                if (childTicketInput.length) {
                    childPrice = parseFloat(childTicketInput.val()) || 0;
                    childCount = parseInt(childTicketInput.data('children')) || 0;
                }
                
                // Apply guide conditions
                var guide = "<?php echo $this->input->get('guide'); ?>";
                var totalGuests = adultCount + childCount;
                
                var finalAdultCount = adultCount;
                // if (guide === "yes" && (siteId === 1 || siteId === 4) && totalGuests < 4) {
                //     finalAdultCount = adultCount + 1;
                // }
                
                var last_quotation_date = "<?php echo $this->input->get('last_quotation_date'); ?>";
                var kok_cutoff_date = '2026-03-21 16:05:00';

                if(last_quotation_date =='' || last_quotation_date > kok_cutoff_date)
                {
                    if (guide === "yes" && siteId === 4 && totalGuests < 2) {
                        finalAdultCount = adultCount + 1;
                    }
                }
                else
                {
                    if (guide === "yes" && siteId === 4 && totalGuests < 4) {
                        finalAdultCount = adultCount + 1;
                    }
                }

                if (guide === "yes" && siteId === 1 && totalGuests < 4) {
                    finalAdultCount = adultCount + 1;
                }
            
                
                if (guide === "yes" && siteId === 297 && totalGuests < 6) {
                    finalAdultCount = adultCount + 1;
                }
                
                // Calculate totals
                var adultTotal = finalAdultCount * adultPrice;
                var childTotal = childCount * childPrice;
                var totalCost = adultTotal + childTotal;
                
                var ticketFor = row.find('.col-md-3 span').text().trim();
                
                // Update display fields
                row.find('.adult_ticket_row_total').val(adultTotal);
                if (childTicketInput.length) {
                    row.find('.child_ticket_row_total').val(childTotal);
                }
                
                ticketsByDay[day].tickets.push({
                    ticket_type: 'individual',
                    ticket_for: ticketFor,
                    price: adultPrice,
                    child_price: childPrice,
                    adult_count: finalAdultCount,
                    child_count: childCount,
                    adult_total: adultTotal,
                    child_total: childTotal,
                    total: totalCost,
                    sitescene: siteName,
                    site_id: siteId ? siteId.toString() : ''
                });
            }
            
            function processGroupTicket(row, siteId, siteName, day, ticketsByDay) {
                var groupPrice = parseFloat(row.find('.group_ticket').val()) || 0;
                var groupCount = parseInt(row.find('.group_count').val()) || 0;
                var totalCost = groupPrice * groupCount;
                var groupSize = parseInt(row.find('.group_ticket').data('group-size')) || 0;
                // var ticketFor = row.find('.col-md-3 span').text().trim();
                var ticketFor = row.find('td:first').text().trim();
                
                // Update display field
                row.find('.ticket_total').val(totalCost);
                
                ticketsByDay[day].tickets.push({
                    ticket_type: 'group',
                    ticket_for: ticketFor,
                    price: groupPrice,
                    group_size: groupSize,
                    group_count: groupCount,
                    adult_total: totalCost,
                    child_total: 0,
                    total: totalCost,
                    sitescene: siteName,
                    site_id: siteId ? siteId.toString() : ''
                });
            }
            
            // Event handlers
            $(document).on('change keyup', '.adult_ticket, .child_ticket, .group_ticket, .group_count', function() {
                updateTicketCosts();
            });

        }
        
        // Initialize
        setTimeout(updateTicketCosts, 500);
    });
    
    
    // ==================== ENTRANCE GROUP PRICE HANDLERS ====================
    // Update group total when group price changes
    $(document).on('input', '.entrance_group_price', function() {
        var row = $(this).data('row');
        var price = parseFloat($(this).val()) || 0;
        var count = parseFloat($('.entrance_group_count[data-row="'+row+'"]').val()) || 0;
        $('.entrance_group_total[data-row="'+row+'"]').val(price * count);
        updateEntranceGrandTotals();
        generateEntranceDataJson();
    });
    
    // Update group total when number of groups changes
    $(document).on('input', '.entrance_group_count', function() {
        var row = $(this).data('row');
        var count = parseFloat($(this).val()) || 0;
        var price = parseFloat($('.entrance_group_price[data-row="'+row+'"]').val()) || 0;
        $('.entrance_group_total[data-row="'+row+'"]').val(price * count);
        updateEntranceGrandTotals();
        generateEntranceDataJson();
    });
    
    // ==================== INDIVIDUAL ENTRANCE HANDLERS (UPDATED) ====================
    $(document).on('input', '.entrance_adult_price', function() {
        var row = $(this).data('row');
        var price = parseFloat($(this).val()) || 0;
        var count = parseFloat($('.entrance_adults_count[data-row="'+row+'"]').val()) || 0;
        $('.entrance_adult_total[data-row="'+row+'"]').val(price * count);
        updateEntranceGrandTotals();
        generateEntranceDataJson();
    });
    
    $(document).on('input', '.entrance_child_price', function() {
        var row = $(this).data('row');
        var price = parseFloat($(this).val()) || 0;
        var count = parseFloat($('.entrance_children_count[data-row="'+row+'"]').val()) || 0;
        $('.entrance_child_total[data-row="'+row+'"]').val(price * count);
        updateEntranceGrandTotals();
        generateEntranceDataJson();
    });

    // ==================== AGE-BASED CHILD HANDLERS ====================
    $(document).on('input', '.entrance_child_age_price', function() {
        console.log('Age price changed');
        var row = $(this).data('row');
        var price = parseFloat($(this).val()) || 0;
        var count = parseFloat($('.entrance_child_age_count[data-row="'+row+'"]').val()) || 0;
        var total = price * count;
        $('.entrance_child_age_total[data-row="'+row+'"]').val(total);
        console.log('Age row total:', total);
        updateEntranceGrandTotals();
        generateEntranceDataJson();
    });

    // ==================== GRAND TOTALS (UPDATED) ====================
    function updateEntranceGrandTotals() {
        var adultTotal = 0;
        var childTotal = 0;      // simple child totals
        var childAgeTotal = 0;    // age‑based child totals
        var groupTotal = 0;

        // Sum adult totals
        $('.entrance_adult_total').each(function() {
            var val = parseFloat($(this).val());
            if (!isNaN(val)) adultTotal += val;
        });

        // Sum simple child totals
        $('.entrance_child_total').each(function() {
            var val = parseFloat($(this).val());
            if (!isNaN(val)) childTotal += val;
        });

        // Sum age‑based child totals
        $('.entrance_child_age_total').each(function() {
            var val = parseFloat($(this).val());
            if (!isNaN(val)) childAgeTotal += val;
        });

        // Sum group totals
        $('.entrance_group_total').each(function() {
            var val = parseFloat($(this).val());
            if (!isNaN(val)) groupTotal += val;
        });

        var combinedChildTotal = childTotal + childAgeTotal;

        console.log('Totals: adult=' + adultTotal + ', child=' + combinedChildTotal + ', group=' + groupTotal);

        // Update UI fields – change these IDs to match your actual elements
        $('#entrance_adult_total').val(adultTotal.toFixed(0));
        $('#entrance_child_total').val(combinedChildTotal.toFixed(0));
        $('#entrance_group_total').val(groupTotal.toFixed(0));
        $('#entrance_total').val((adultTotal + combinedChildTotal + groupTotal).toFixed(0));
    }

    // ==================== JSON GENERATION (UPDATED) ====================
    function generateEntranceDataJson() {
        var entranceData = [];
        var dayMap = {};

        // Collect all unique main row IDs (from adult or group price elements)
        var mainRowIds = new Set();
        $('.entrance_adult_price').each(function() { mainRowIds.add($(this).data('row')); });
        $('.entrance_group_price').each(function() { mainRowIds.add($(this).data('row')); });

        console.log('Main rows found:', mainRowIds.size);

        mainRowIds.forEach(function(mainRow) {
            var $adultElem = $('.entrance_adult_price[data-row="'+mainRow+'"]');
            var $groupElem = $('.entrance_group_price[data-row="'+mainRow+'"]');
            var $elem = $adultElem.length ? $adultElem : $groupElem;

            if (!$elem.length) return;

            var day = $elem.data('day');
            var siteId = $elem.data('site-id');
            var entranceId = $elem.data('entrance-id');
            var entranceName = $elem.data('entrance');
            var isGroup = $('.entrance_group_price[data-row="'+mainRow+'"]').length > 0;

            var entranceItem = {
                entrance_id: entranceId,
                entrance_name: entranceName,
                site_id: siteId,
                is_group: isGroup
            };

            if (isGroup) {
                entranceItem.group_price = parseFloat($('.entrance_group_price[data-row="'+mainRow+'"]').val()) || 0;
                entranceItem.group_count = parseFloat($('.entrance_group_count[data-row="'+mainRow+'"]').val()) || 0;
                entranceItem.group_total = parseFloat($('.entrance_group_total[data-row="'+mainRow+'"]').val()) || 0;
                entranceItem.persons_per_group = parseInt($('.entrance_group_price[data-row="'+mainRow+'"]').data('group-size')) || 0;
            } else {
                // Adult data
                entranceItem.adult_price = parseFloat($('.entrance_adult_price[data-row="'+mainRow+'"]').val()) || 0;
                entranceItem.adult_count = parseFloat($('.entrance_adults_count[data-row="'+mainRow+'"]').val()) || 0;
                entranceItem.adult_total = parseFloat($('.entrance_adult_total[data-row="'+mainRow+'"]').val()) || 0;

                // Check for simple child pricing
                var $childPriceElem = $('.entrance_child_price[data-row="'+mainRow+'"]');
                if ($childPriceElem.length) {
                    entranceItem.child_price = parseFloat($childPriceElem.val()) || 0;
                    entranceItem.child_count = parseFloat($('.entrance_children_count[data-row="'+mainRow+'"]').val()) || 0;
                    entranceItem.child_total = parseFloat($('.entrance_child_total[data-row="'+mainRow+'"]').val()) || 0;
                } else {
                    // Age-based child pricing
                    var childAgeRows = [];
                    $('.entrance_child_age_price').each(function() {
                        var row = $(this).data('row');
                        if (row.indexOf(mainRow + '_child_') === 0) {
                            var ageFrom = $(this).data('age-from');
                            var ageTo = $(this).data('age-to');
                            var ageRangeId = $(this).data('age-range-id');
                            var price = parseFloat($(this).val()) || 0;
                            var count = parseFloat($('.entrance_child_age_count[data-row="'+row+'"]').val()) || 0;
                            var total = parseFloat($('.entrance_child_age_total[data-row="'+row+'"]').val()) || 0;
                            childAgeRows.push({
                                age_range_id: ageRangeId,
                                age_from: ageFrom,
                                age_to: ageTo,
                                price: price,
                                count: count,
                                total: total
                            });
                        }
                    });
                    if (childAgeRows.length) {
                        entranceItem.child_age_ranges = childAgeRows;
                    }
                }
            }

            if (!dayMap[day]) {
                dayMap[day] = { day: day, entrances: [] };
            }
            dayMap[day].entrances.push(entranceItem);
        });

        entranceData = Object.keys(dayMap)
            .sort(function(a, b) { return parseInt(a) - parseInt(b); })
            .map(function(key) { return dayMap[key]; });

        var jsonString = JSON.stringify(entranceData);
        console.log('Generated JSON:', jsonString);
        $('#entrance_data_json').val(jsonString);
        // triggerMarginTableLoad(); // Uncomment if needed
    }

    // ==================== INITIALIZATION ====================
    $(document).ready(function() {
        updateEntranceGrandTotals();
        generateEntranceDataJson();
    });

$(document).ready(function() {
    function recalcDriverTotals() {
        // 1. For each driver row, calculate row total and update driver-total field
        $('.driver-price, .driver-qty').off('input').on('input', function() {
            var $row = $(this).closest('.row'); // the row containing price and qty inputs
            var day = $(this).data('day');
            var index = $(this).data('index');

            // Find the three price inputs in this row (same day+index)
            var $food = $('.driver-price[data-day="'+day+'"][data-index="'+index+'"]').eq(0);
            var $acc = $('.driver-price[data-day="'+day+'"][data-index="'+index+'"]').eq(1);
            var $charge = $('.driver-price[data-day="'+day+'"][data-index="'+index+'"]').eq(2);
            var $qty = $('.driver-qty[data-day="'+day+'"][data-index="'+index+'"]');
            var $total = $('.driver-total[data-day="'+day+'"][data-index="'+index+'"]');

            var food = parseFloat($food.val()) || 0;
            var acc = parseFloat($acc.val()) || 0;
            var charge = parseFloat($charge.val()) || 0;
            var qty = parseFloat($qty.val()) || 0;

            var rowTotal = (food + acc + charge) * qty;
            $total.val(rowTotal.toFixed(0));

            var dayTotal = 0;
            $('.driver-total[data-day="'+day+'"]').each(function() {
                dayTotal += parseFloat($(this).val()) || 0;
            });
            $('.driver-day-total[data-day="'+day+'"]').val(dayTotal.toFixed(0));

            var grandTotal = 0;
            $('.driver-day-total').each(function() {
                grandTotal += parseFloat($(this).val()) || 0;
            });
            $('#driver_grand_total').val(grandTotal.toFixed(0));

             var driverData = collectDriverData(); // We'll define this next
            $('#driver_data_json').val(JSON.stringify(driverData));
        });

        // Trigger once on page load to set initial totals
        $('.driver-price').first().trigger('input');
        
    }

    recalcDriverTotals();
    
});

function collectDriverData() {
    var driverData = [];

    $('.driver-price[data-day]').each(function() {
        var day = $(this).data('day');
        var index = $(this).data('index');

        var exists = driverData.some(item => item.day === day && item.index === index);
        if (!exists) 
        {
            var $food   = $('.driver-price[data-day="'+day+'"][data-index="'+index+'"]').eq(0);
            var $acc    = $('.driver-price[data-day="'+day+'"][data-index="'+index+'"]').eq(1);
            var $charge = $('.driver-price[data-day="'+day+'"][data-index="'+index+'"]').eq(2);
            var $qty    = $('.driver-qty[data-day="'+day+'"][data-index="'+index+'"]');
            var $total  = $('.driver-total[data-day="'+day+'"][data-index="'+index+'"]');

            driverData.push({
                day: parseInt(day),
                index: parseInt(index),
                food: parseFloat($food.val()) || 0,
                accomodation: parseFloat($acc.val()) || 0,
                guide_charge: parseFloat($charge.val()) || 0,
                qty: parseFloat($qty.val()) || 0,
                total: parseFloat($total.val()) || 0
            });
        }
    });

    return driverData;
}    
</script>
