            var activitiesGroup = parseFloat($('#hdn_group_activity_total').val()) || 0;
            var mandatoryTotal = parseFloat($('#hdn_mandatory_grand_total').val()) || 0;
            var child_mandatoryTotal = parseFloat($('#child_mandatory_grand_total').val()) || 0;
            
            var guideTotal = parseFloat($('#hdn_guide_grand_total').val()) || 0;
            var discount_bundle_price = parseFloat($('#discount_bundle_price').val()) || 0;
            var meal_total = parseFloat($('.grandTotalMeal').val()) || 0;
            var child_meal_total = parseFloat($('.childMealCost').val()) || 0;
