            var driver_grand_total = parseFloat($('#driver_grand_total').val()) || 0;
            var entrance_group_total = parseFloat($('#entrance_group_total').val()) || 0;
            var entrance_child_total = parseFloat($('#entrance_child_total').val()) || 0;
            var entrance_adult_total = parseFloat($('#entrance_adult_total').val()) || 0;

            var db_total = parseFloat($('#saved_overall_amout').val()) || 0;

            var hotelTotal = 0;
            if (hotelCosting) {
                try {
                    var hotelData = JSON.parse(hotelCosting);

                    // Function to recursively extract and sum numeric values
                    function sumNumericValues(obj) {
                        var total = 0;

                       
                        if (typeof obj === 'object' && obj !== null) {
                            Object.values(obj).forEach(function(value) {
                    
                                if (Array.isArray(value)) {
                                    value.forEach(function(item) {
                                        if (typeof item === 'string' && item.includes('__')) {
                                            var parts = item.split('__');
                                            var numValue = parseFloat(parts[parts.length - 1]);
                                            if (!isNaN(numValue)) {
                                                total += numValue;
                                            }
                                        }
                                    });
                                }
                    
                                else if (typeof value === 'object') {
                                    total += sumNumericValues(value);
                                }
                    
                                else if (typeof value === 'string' && value.includes('__')) {
                                    var parts = value.split('__');
                                    var numValue = parseFloat(parts[parts.length - 1]);
                                    if (!isNaN(numValue)) {
                                        total += numValue;
                                    }
                                }
                    
                                // ❌ DO NOT sum plain numbers (hotel_id, nights, etc)
                            });
                        }

                        return total;
                    }

                    hotelTotal = sumNumericValues(hotelData);

                } catch(e) {
                    console.error('Error parsing hotel JSON:', e);
                }
            }

            var overall_amount = hotelTotal + final_transport + ticketAdult + ticketGroup + ticketChild + activitiesAdult + activitiesChild + activitiesGroup + mandatoryTotal + guideTotal + meal_total + train_child_price + train_adult_price + + driver_grand_total + entrance_group_total + entrance_child_total + entrance_adult_total + child_mandatoryTotal + child_meal_total;
            window.pendingEmailBodyData = data;
            // Check if amounts are different
