        // Function to store OTP data in localStorage
        function storeOTPData(response) {
            var otpData = {
                otp_id: response.otp_id,
                user_id: response.user_id || '<?php echo $this->session->userdata("id"); ?>',
                module_type: 'price_update',
                reference_id: response.reference_id || $('#reference_id').val(),
                email: '<?php echo $this->session->userdata("email"); ?>',
                generated_at: new Date().getTime()
            };
            
            localStorage.setItem('current_otp_data', JSON.stringify(otpData));
            console.log('Stored OTP Data:', otpData);
        }

        // Function to show OTP verification popup
        function showOTPVerificationPopup() {
            // Create OTP popup HTML
            var otpPopupHTML = `
                <div id="otpPopup" style="position:fixed; top:0; left:0; width:100%; height:100%; background:rgba(0,0,0,0.5); z-index:10000; display:flex; justify-content:center; align-items:center;">
                    <div style="background:white; padding:30px; border-radius:10px; width:400px; max-width:90%; box-shadow:0 5px 15px rgba(0,0,0,0.3);">
                        <h3 style="color:#333 !important; margin-top:0;">Verify with OTP</h3>
                        <p style="color:#666 !important; margin-bottom:20px;">An OTP has been sent to your registered email.</p>
                        
                        <div style="margin-bottom:25px;">
                            <label style="display:block; margin-bottom:8px; color:#555; font-weight:bold;">Enter OTP:</label>
                            <input type="text" id="otpInput" maxlength="6" style="width:100%; padding:12px; border:2px solid #ddd; border-radius:5px; font-size:18px; letter-spacing:5px; text-align:center;" placeholder="Enter 6-digit OTP">
                            <div id="otpError" style="color:#f44336 !important; font-size:14px; margin-top:5px; display:none;"></div>
                            <div id="otpSuccess" style="color:#4CAF50 !important; font-size:14px; margin-top:5px; display:none;"></div>
                        </div>
                        
                        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:20px;">
                            <button id="resendOTP" style="background:none; border:none; color:#2196F3; cursor:pointer; font-size:14px;">
                                Resend OTP
                            </button>
                            <div id="otpTimer" style="color:#666; font-size:14px;">OTP expires in: 10:00</div>
                        </div>
                        
                        <div style="display:flex; justify-content:flex-end; gap:15px;">
                            <button id="cancelOTP" style="padding:10px 25px; background:#f44336; color:white; border:none; border-radius:5px; cursor:pointer; font-weight:bold;">
                                Cancel
                            </button>
                            <button id="verifyOTP" style="padding:10px 25px; background:#2196F3; color:white; border:none; border-radius:5px; cursor:pointer; font-weight:bold;">
                                Verify & Save
                            </button>
                        </div>
                    </div>
                </div>
            `;
            
            // Add popup to body
            $('body').append(otpPopupHTML);
            
            // Start OTP timer (10 minutes)
            startOTPTimer(600);
            
            // Focus on OTP input
            setTimeout(function() {
                $('#otpInput').focus();
            }, 100);
            
            // Add event listeners for OTP popup buttons
            $('#cancelOTP').on('click', function() {
                clearOTPTimer();
                localStorage.removeItem('current_otp_data');
                window.pendingEmailBodyData = null;
                $('#otpPopup').remove();
                // $("#btn-submit-save").html("Save").removeAttr("disabled");
            });

            
            $('#verifyOTP').on('click', function() {
                verifyOTP();
            });
            
            $('#resendOTP').on('click', function() {
                resendOTP();
            });
            
            // Allow Enter key to submit OTP
            $('#otpInput').on('keypress', function(e) {
                if (e.which === 13) {
                    verifyOTP();
                }
            });
        }

      
        
        function verifyOTP() {
            var enteredOTP = $('#otpInput').val().trim();
            var storedOTPData = localStorage.getItem('current_otp_data');
            
            console.log('Verifying OTP:', enteredOTP);
            console.log('Stored Data:', storedOTPData);
            
            // Hide previous messages
            $('#otpError').hide();
            $('#otpSuccess').hide();
            
            // Validate OTP format
            if (enteredOTP.length !== 6 || !/^\d+$/.test(enteredOTP)) {
                $('#otpError').text('Please enter a valid 6-digit OTP').show();
                $('#otpInput').addClass('error').focus();
                return;
            }
            
            // Check if OTP data exists in localStorage
            if (!storedOTPData) {
                $('#otpError').text('OTP session expired. Please generate a new OTP.').show();
                return;
            }
            
            try {
                var otpData = JSON.parse(storedOTPData);
                console.log('Parsed OTP Data:', otpData); // Debug log
                
                // Show verifying state
                $('#verifyOTP').prop('disabled', true).text('Verifying...');
                
                // Send verification request to server
                $.ajax({
                    url: '<?php echo base_url("admin/quotation/verify_otp"); ?>',
                    type: 'POST',
                    data: {
                        otp_id: otpData.otp_id,
                        otp_code: enteredOTP,
                        user_id: otpData.user_id,
                        reference_id: otpData.reference_id
                    },
                    dataType: 'json',
                    success: function(response) {
                        console.log('OTP Verification Response:', response);
                        
                        if (response.success) {
                            // OTP verified successfully
                            $('#otpSuccess').text('✓ OTP verified successfully!').show();
                            
                            // Clear stored OTP data
                            localStorage.removeItem('current_otp_data');
                            clearOTPTimer();
                            
                            // First save the quotation
                            saveQuotation(function(quotationId) {
                                // After saving, save updated quotation log
                                if (quotationId && quotationId > 0) {
                                    saveUpdatedQuotationLog(quotationId);
                                }
                                
                                // After saving, redirect to email body
                                setTimeout(function() {
                                    $('#otpPopup').remove();
                                    if (window.pendingEmailBodyData) {
                                        redirectToEmailBody(window.pendingEmailBodyData);
                                    }
                                }, 1000);
                            });
                            
                        } else {
                            // OTP verification failed
                            $('#otpError').text(response.message || 'OTP does not match. Please try again.').show();
                            $('#verifyOTP').prop('disabled', false).text('Verify & Save');
                            $('#otpInput').val('').focus();
                        }
                    },
                    error: function(xhr, status, error) {
                        console.error('OTP Verification AJAX Error:', status, error);
                        $('#otpError').text('Error verifying OTP. Please try again.').show();
                        $('#verifyOTP').prop('disabled', false).text('Verify & Save');
                    }
                });
                
            } catch(e) {
                console.error('Error parsing stored OTP data:', e);
                $('#otpError').text('Error processing OTP data. Please generate a new OTP.').show();
            }
        }

        // Timer functions
        var otpTimerInterval;

        function startOTPTimer(duration) {
            var timer = duration;
            var timerDisplay = $('#otpTimer');
            
            clearInterval(otpTimerInterval);
            
            otpTimerInterval = setInterval(function() {
                var minutes = parseInt(timer / 60, 10);
                var seconds = parseInt(timer % 60, 10);
                
                minutes = minutes < 10 ? "0" + minutes : minutes;
                seconds = seconds < 10 ? "0" + seconds : seconds;
                
                timerDisplay.text('OTP expires in: ' + minutes + ":" + seconds);
                
                if (--timer < 0) {
                    clearInterval(otpTimerInterval);
                    timerDisplay.text('OTP expired');
                    $('#verifyOTP').prop('disabled', true);
                    $('#otpError').text('OTP has expired. Please generate a new one.').show();
                    localStorage.removeItem('current_otp_data');
                }
            }, 1000);
        }

        function clearOTPTimer() {
            clearInterval(otpTimerInterval);
        }

        // Function to resend OTP
        function resendOTP() {
            $('#resendOTP').prop('disabled', true).text('Resending...');
            $('#otpError').hide();
            $('#otpSuccess').hide();
            
            // Get stored OTP data
            var storedOTPData = localStorage.getItem('current_otp_data');
            
            if (storedOTPData) {
                var otpData = JSON.parse(storedOTPData);
                
                // Also check if we have form data pending
                if (!window.pendingEmailBodyData) {
                    $('#otpError').text('Form data lost. Please cancel and try again.').show();
                    $('#resendOTP').prop('disabled', false).text('Resend OTP');
                    return;
                }
                
                // Resend OTP request
                $.ajax({
                    url: '<?php echo base_url("admin/quotation/generate_otp"); ?>',
                    type: 'POST',
                    data: {
                        user_id: otpData.user_id,
                        module_type: 'price_update',
                        reference_id: otpData.reference_id,
                        email: otpData.email
                    },
                    dataType: 'json',
                    success: function(response) {
                        if (response.success) {
                            // Store new OTP data
                            storeOTPData(response);
                            
                            // Reset timer
                            startOTPTimer(600);
                            
                            // Clear input
                            $('#otpInput').val('').focus();
                            
                            // Show success message
                            $('#otpSuccess').text('New OTP sent successfully!').show();
                            setTimeout(function() {
                                $('#otpSuccess').hide();
                            }, 3000);
                            
                            // Disable resend button temporarily
                            $('#resendOTP').prop('disabled', true);
                            
                            // Enable resend button after 30 seconds
                            var resendTimeout = 30;
                            var resendInterval = setInterval(function() {
                                resendTimeout--;
                                $('#resendOTP').text(`Resend OTP (${resendTimeout}s)`);
                                
                                if (resendTimeout <= 0) {
                                    clearInterval(resendInterval);
                                    $('#resendOTP').prop('disabled', false).text('Resend OTP');
                                }
                            }, 1000);
                            
                        } else {
                            $('#otpError').text('Failed to resend OTP: ' + (response.message || 'Unknown error')).show();
                            $('#resendOTP').prop('disabled', false).text('Resend OTP');
                        }
                    },
                    error: function(xhr, status, error) {
                        console.error('Resend OTP Error:', status, error);
                        $('#otpError').text('Error resending OTP. Please try again.').show();
                        $('#resendOTP').prop('disabled', false).text('Resend OTP');
                    }
                });
            } else {
                // No stored data, check if we have form data
                if (!window.pendingEmailBodyData) {
                    $('#otpError').text('Session expired. Please cancel and try again.').show();
                    $('#resendOTP').prop('disabled', false).text('Resend OTP');
                    return;
                }
                
                // Try to regenerate OTP from scratch
                $('#resendOTP').text('Generating...');
                
                $.ajax({
                    url: '<?php echo base_url("admin/quotation/generate_otp"); ?>',
                    type: 'POST',
                    data: {
                        user_id: '<?php echo $this->session->userdata("id"); ?>',
                        module_type: 'price_update',
                        reference_id: $('#reference_id').val(),
                        email: '<?php echo $this->session->userdata("email"); ?>'
                    },
                    dataType: 'json',
                    success: function(response) {
                        if (response.success) {
                            // Store new OTP data
                            storeOTPData(response);
                            
                            // Reset timer
                            startOTPTimer(600);
                            
                            // Clear input
                            $('#otpInput').val('').focus();
                            
                            // Show success message
                            $('#otpSuccess').text('New OTP generated successfully!').show();
                            setTimeout(function() {
                                $('#otpSuccess').hide();
                            }, 3000);
                            
                            // Disable resend button temporarily
                            $('#resendOTP').prop('disabled', true);
                            
                            // Enable resend button after 30 seconds
                            var resendTimeout = 30;
                            var resendInterval = setInterval(function() {
                                resendTimeout--;
                                $('#resendOTP').text(`Resend OTP (${resendTimeout}s)`);
                                
                                if (resendTimeout <= 0) {
                                    clearInterval(resendInterval);
                                    $('#resendOTP').prop('disabled', false).text('Resend OTP');
                                }
                            }, 1000);
                            
                        } else {
                            $('#otpError').text('Failed to generate OTP: ' + (response.message || 'Unknown error')).show();
                            $('#resendOTP').prop('disabled', false).text('Resend OTP');
                        }
                    },
                    error: function(xhr, status, error) {
                        console.error('Generate OTP Error:', status, error);
                        $('#otpError').text('Error generating OTP. Please try again.').show();
                        $('#resendOTP').prop('disabled', false).text('Resend OTP');
                    }
                });
            }
        }

    
        
        function saveQuotation(callback) {
            let myForm = document.getElementById("frm-quotation");
            var data = new FormData(myForm);
            
             const markupData = collectMarkupValues();
            data.set('reduced_margins', JSON.stringify(markupData.reduced_margins));
            data.set('reduced_land_margins', JSON.stringify(markupData.reduced_land_margins));

            $("#btn-email-body").html("Saving..").attr("disabled", "disabled");
            
            $.ajax({
                url: "<?php echo site_url('admin/quotation/save_quotation'); ?>",
                type: "post",
                data: data,
                dataType: 'JSON',
                contentType: false,
                processData: false,
                success: function(data) {
                //    console.log("SAVE QUOTATION RESPONSE:");
                //    console.log(data);
                    $("#msg_div").html("").html(data.msg);
                    if (data.response === "s") {
                        $("#btn-email-body").html("<i class='fa fa-check'></i> Saved");
                        
                        // Get the quotation ID from response if available
                        var quotationId = data.quotation_id || data.id || 0;
                        if (data.quotation_id) {
                            window.lastSavedQuoteId = data.quotation_id;
                            console.log("Quotation saved with ID:", data.quotation_id);
                            $('#quotation_id').val(data.quotation_id);
                        }
                        // Save updated quotation log AFTER successful save
                        if (quotationId > 0) {
                            setTimeout(function() {
                                saveUpdatedQuotationLog(quotationId);
                            }, 500);
                        }
                        
                        if (typeof callback === 'function') {
                            callback();
                        }
                    } else if (data.response === "e") {
                        $("#btn-email-body").html("Save").removeAttr("disabled");
                    }
                },
                error: function() {
                    $("#btn-email-body").html("Save").removeAttr("disabled");
                    alert("Error saving quotation. Please try again.");
                }
            });
        }

        // Function to save updated quotation log
 function saveUpdatedQuotationLog(quotationId) {

        // ==========================================
        // GET LATEST CATEGORY/NIGHT MAPPING
        // ==========================================

        updateCategoryWiseNights();

        var categoryWiseNights = {};

        try {

            categoryWiseNights =
                JSON.parse($("#category_wise_nights").val() || "{}");

        } catch (e) {

            console.error(
                "Invalid category_wise_nights JSON",
                e
            );

            categoryWiseNights = {};

        }


        // ==========================================
        // GET NIGHT-WISE HOTEL DATA
        // ==========================================

        var hotelNightData = {};


        $(".daywise-hotels").each(function () {

            var night = $(this).data("night");
