                    function sumNumericValues(obj) {
                        var total = 0;

                        if (typeof obj === 'object' && obj !== null) {
                            Object.values(obj).forEach(function(value) {
                                if (Array.isArray(value)) {
                                    // Handle arrays like ["Single Occupancy__190000", "Double Occupancy__110000"]
                                    value.forEach(function(item) {
                                        if (typeof item === 'string') {
                                            // Split by "__" and get the last part
                                            var parts = item.split('__');
                                            if (parts.length > 1) {
                                                var numValue = parseFloat(parts[parts.length - 1]);
                                                if (!isNaN(numValue)) {
                                                    total += numValue;
                                                }
                                            }
                                        }
                                    });
                                } else if (typeof value === 'object') {
                                    // Recursively process nested objects
                                    total += sumNumericValues(value);
                                } else if (typeof value === 'string') {
                                    // Check if string contains "__" pattern
                                    if (value.includes('__')) {
                                        var parts = value.split('__');
                                        var numValue = parseFloat(parts[parts.length - 1]);
                                        if (!isNaN(numValue)) {
