<script>
$(document).ready(function() {
    function updateDayTotals() {
        $('[id^="dinner_day_total_"]').each(function() {
            var dayKey = this.id.replace('dinner_day_total_', '');
            var dayTotal = 0;
            $('.alert[data-day="' + dayKey + '"] .dinner-transfer-row .dinner-total').each(function() {
                dayTotal += parseFloat($(this).val()) || 0;
            });
            $(this).val(dayTotal.toFixed(0));
        }); 
        var grandTotal = 0;
        $('[id^="dinner_day_total_"]').each(function() {
            grandTotal += parseFloat($(this).val()) || 0;
        });
        $('#dinner_transfer_grand_total').val(grandTotal.toFixed(0));
    }

    function updateHiddenJson() {
        // Safety check: hidden input must exist
        var $hidden = $('#dinner_transfer_data_json');
        if ($hidden.length === 0) {
            console.error('Hidden input #dinner_transfer_data_json not found!');
            return;
        }

        var jsonData = {};
        $('.alert[data-day]').each(function() {
            var dayKey = $(this).data('day');
            jsonData[dayKey] = {};
            $(this).find('.dinner-transfer-row').each(function() {
                var $priceInput = $(this).find('.dinner-price');
                var $qtyInput   = $(this).find('.dinner-qty');
                var nameAttr = $priceInput.attr('name');

                // Extract vehicle ID from name, e.g. "dinner_price[Day_1][35]"
                var match = nameAttr.match(/\[(\d+)\]$/);
                if (!match) {
                    console.warn('Could not extract vehicle ID from name:', nameAttr);
                    return;
                }
                var vehicleId = match[1];

                var price = parseFloat($priceInput.val()) || 0;
                var qty   = parseFloat($qtyInput.val()) || 0;
                var total = price * qty;
                jsonData[dayKey][vehicleId] = { price: price, qty: qty, total: total };
            });
        });
        var jsonStr = JSON.stringify(jsonData);
        $hidden.val(jsonStr);
        console.log('JSON updated:', jsonStr);  // See the result in browser console
        updateFinalTransport();
    }

    function updateRowTotal(row) {
        var price = parseFloat(row.find('.dinner-price').val()) || 0;
        var qty   = parseFloat(row.find('.dinner-qty').val()) || 0;
        var total = price * qty;
        row.find('.dinner-total').val(total.toFixed(0));
        updateDayTotals();
        updateHiddenJson();   // <-- called after each change
    }

    // Event binding for price/quantity changes
    $(document).on('input', '.dinner-price, .dinner-qty', function() {
        var row = $(this).closest('.dinner-transfer-row');
        updateRowTotal(row);
    });

    // Initial calculation and JSON population
    $('.dinner-transfer-row').each(function() {
        updateRowTotal($(this));
    });
});
</script>
