function disableEmailButtons() {
    $('#btn-email-body, #btn-email-body-preview')
        .addClass('disabled')
        .css({ 'pointer-events': 'none', 'opacity': '0.6' });
}

function enableEmailButtons() {
    $('#btn-email-body, #btn-email-body-preview')
        .removeClass('disabled')
        .css({ 'pointer-events': 'auto', 'opacity': '1' });
}
    // Update loadCostingTable to send reduced margins
function loadCostingTable() 
{
    disableEmailButtons();
    let myForm = document.getElementById("frm-timeline");
    var data = new FormData(myForm);
    const markupData = collectMarkupValues();
    
    // Send reduced margins SEPARATELY
    data.set('reduced_margins', JSON.stringify(markupData.reduced_margins)); // Hotel reduced margins
    data.set('reduced_land_margins', JSON.stringify(markupData.reduced_land_margins)); // Land package reduced margins
    
    console.log("=== SENDING DATA TO SERVER ===");
    console.log("Hotel reduced margins count:", markupData.reduced_margins.length);
    console.log("Land package reduced margins count:", markupData.reduced_land_margins.length);
    console.log("=== END SENDING DATA ===");
    
    addFormDataToCostingRequest(data);
    
    $('#costing-table-container').html('<div class="text-center p-4"><i class="fa fa-spinner fa-spin fa-2x"></i> Loading costing table...</div>');
    
    $.ajax({
        url: "<?php echo site_url('admin/quotation/get_cost_table_ajax'); ?>",
        type: "POST",
        data: data,
        processData: false,
        contentType: false,
        success: function(response) {
            try {
                var result = JSON.parse(response);
                if (result.success) {
                    $('#costing-table-container').html(result.cost_html);
                    console.log("Costing table loaded successfully");
                    
                    // Initialize markup collection AFTER table loads
                    setTimeout(function() {
                        initializeMarkupListeners();
                        initializeMarginUpdateListener();
                        enableEmailButtons();
                    }, 100);
                    
                } else {
                    disableEmailButtons();
                    $('#costing-table-container').html('<div class="alert alert-danger">Error: ' + (result.error || 'Unknown error') + '</div>');
                }
            } catch(e) {
                disableEmailButtons();
                console.error("Error parsing response:", e);
                console.error("Response was:", response.substring(0, 500) + "...");
                $('#costing-table-container').html('<div class="alert alert-danger">Error loading costing table. Please check console for details.</div>');
            }
        },
        error: function(xhr, status, error) {
            disableEmailButtons();
            console.error("AJAX Error:", error);
            $('#costing-table-container').html('<div class="alert alert-danger">Failed to load costing table. Please try again.</div>');
        }
    });
}

const style = document.createElement('style');
style.textContent = `
    .readonly-markup {
        background-color: #f5f5f5 !important;
        cursor: not-allowed !important;
        opacity: 0.7 !important;
    }
    .markup-input:read-only {
        background-color: #f5f5f5;
        cursor: not-allowed;
        opacity: 0.7;
    }
`;
document.head.appendChild(style);

function setMarkupInputsReadonly() {
    const isYesSelected = $('input[name="update_margin"]:checked').val() === 'yes';
    
    // Set readonly attribute on all markup inputs
    $('.markup-input, .cnb-markup-input, .cwb-markup-input, .land-markup-input, .reduced-margin-input').each(function() {
        const $input = $(this);
        
        if (isYesSelected) {
            // Remove readonly and styling
            $input.removeAttr('readonly').removeClass('readonly-markup');
        } else {
            // Set readonly and add styling
            $input.attr('readonly', 'readonly').addClass('readonly-markup');
        }
    });
    
    // Log for debugging
    console.log(`Markup inputs set to ${isYesSelected ? 'EDITABLE' : 'READONLY'}`);
}

// Update the initializeMarkupListeners function to include reduced margin inputs
function initializeMarkupListeners() {
    console.log("Initializing markup listeners...");
    
    // Add class to all markup input fields
    $('input[type="number"]').each(function() {
        const $input = $(this);
        // Check if this is a markup input (not in readonly fields AND not a land markup)
        if (!$input.attr('readonly') && !$input.hasClass('markup-input') && 
            !$input.hasClass('land-markup-input') && !$input.hasClass('reduced-margin-input')) {
            $input.addClass('markup-input');
            
            // Add data attributes for hotel info
            const $td = $input.closest('td');
            const $tr = $input.closest('tr');
            
            // Try to extract hotel info from table structure
            extractAndSetHotelInfo($input, $td, $tr);
        }
    });
    
    // Also find and initialize land package markups
    $('input[type="number"].land-markup').each(function() {
        const $input = $(this);
        if (!$input.hasClass('land-markup-input')) {
            $input.addClass('land-markup-input');
            
            // Determine if this is adult, CNB, or CWB markup
            const label = $input.closest('tr').find('td:first-child').text().toLowerCase();
            if (label.includes('cnb') || label.includes('child')) {
                $input.attr('data-type', 'cnb');
            } else if (label.includes('cwb')) {
                $input.attr('data-type', 'cwb');
            } else {
                $input.attr('data-type', 'adult');
            }
        }
    });
    
    // Initialize reduced margin inputs
    $('input.reduced-margin-input').each(function() {
        const $input = $(this);
        if (!$input.attr('data-type')) {
            // Determine type based on context
            const label = $input.closest('tr').find('th').text().toLowerCase();
            if (label.includes('cnb') || label.includes('child')) {
                $input.attr('data-type', 'cnb');
            } else if (label.includes('cwb')) {
                $input.attr('data-type', 'cwb');
            } else {
                $input.attr('data-type', 'adult');
            }
        }
    });
    
    console.log("Markup listeners initialized. Found " + $('.markup-input').length + " markup inputs.");
    console.log("Land markup inputs found: " + $('.land-markup-input').length);
    console.log("Reduced margin inputs found: " + $('.reduced-margin-input').length);
    
    // Set the readonly state based on radio button selection
    setMarkupInputsReadonly();
}

function initializeMarginUpdateListener() {
    console.log("Initializing margin update listener...");
    
    // Remove any existing listeners to prevent duplicates
    $(document).off('change', 'input[name="update_margin"]');
    
    // Add change listener to radio buttons
    $(document).on('change', 'input[name="update_margin"]', function() {
        console.log(`Margin update option changed to: ${$(this).val()}`);
        setMarkupInputsReadonly();
    });
    
    // Set initial state based on default selection
    setTimeout(function() {
        setMarkupInputsReadonly();
    }, 100);
}

// NEW FUNCTION: Extract and set hotel info for markup inputs
function extractAndSetHotelInfo($input, $td, $tr) {
    const colIndex = $td.index();
    const $table = $input.closest('table');
    
    // Check if this is a simple rating table (without packages)
    if ($table.hasClass('rating-table')) {
        // Simple table structure
        const ratingRow = $table.find('tr:first-child');
        const hotelRow = $table.find('tr:nth-child(2)');
        const categoryRow = $table.find('tr:nth-child(3)');
        const occupancyRow = $table.find('tr:nth-child(4)');
        
        // Find which rating column this belongs to
        let rating = '';
        let hotel = '';
        let roomCategory = '';
        let occupancy = '';
        
        // Get rating from headers
        ratingRow.find('th[colspan]').each(function() {
            const $th = $(this);
            const colspan = parseInt($th.attr('colspan') || 1);
            const startCol = $th.index();
            const endCol = startCol + colspan - 1;
            
            if (colIndex >= startCol && colIndex <= endCol) {
                rating = $th.text().trim();
                return false;
            }
        });
        
        // Get hotel name
        hotelRow.find('td[colspan]').each(function() {
            const $td = $(this);
            const colspan = parseInt($td.attr('colspan') || 1);
            const startCol = $td.index();
            const endCol = startCol + colspan - 1;
            
            if (colIndex >= startCol && colIndex <= endCol) {
                hotel = $td.text().trim()
                    .replace(/\(\d+N\)/g, '')
                    .replace(/\(Guaranteed Early Check‑In Included\)/g, '')
                    .trim();
                return false;
            }
        });
        
        // Get room category
        categoryRow.find('td[colspan]').each(function() {
            const $td = $(this);
            const colspan = parseInt($td.attr('colspan') || 1);
            const startCol = $td.index();
            const endCol = startCol + colspan - 1;
            
            if (colIndex >= startCol && colIndex <= endCol) {
                roomCategory = $td.text().trim()
                    .replace(/Click to view category details/g, '')
                    .replace(/<img[^>]*>/g, '')
                    .trim();
                return false;
            }
        });
        
        // Get occupancy type
        const occupancyCell = occupancyRow.find('td').eq(colIndex);
        if (occupancyCell.length) {
            occupancy = occupancyCell.text().trim();
        }
        
        // Set data attributes
        $input.attr('data-rating', rating);
        $input.attr('data-hotel', hotel);
        $input.attr('data-room-category', roomCategory);
        $input.attr('data-occupancy', occupancy);
        $input.attr('data-col-index', colIndex);
        
        // CRITICAL FIX: Identify CNB/CWB inputs and add proper classes
        if (occupancy.includes('CNB')) {
            $input.addClass('cnb-markup-input');
            $input.attr('data-type', 'cnb');
            // Use different naming for child markups
            $input.attr('data-col-index', `cnb_${colIndex}`);
        } else if (occupancy.includes('CWB')) {
            $input.addClass('cwb-markup-input');
            $input.attr('data-type', 'cwb');
            $input.attr('data-col-index', `cwb_${colIndex}`);
        } else {
            // Adult markup
            $input.attr('data-type', 'adult');
        }
        
    } else {
        // Package table structure
        const packageName = $tr.find('td:first-child').text().trim() || 
                           $tr.prevAll('tr:has(td[rowspan])').find('td:first-child').text().trim();
        
        const hotelCell = $tr.find('td:nth-child(2)');
        let hotel = hotelCell.text().trim().split('(')[0].trim();
        
        $input.attr('data-package', packageName);
        $input.attr('data-hotel', hotel);
        $input.attr('data-col-index', colIndex);
        $input.attr('data-row-index', $tr.index());
        $input.attr('data-type', 'adult');
    }
}

  // Update collectMarkupValues to separate land package reduced margins
function collectMarkupValues() 
{
    console.log("Collecting markup values...");
    
    const markupValues = {};
    const landMarkupValues = {}; // Regular land package markups (text values)
    const packageMarkupValues = {};
    const structuredMarkupValues = {};
    const reducedMarginsArray = []; // Array for hotel reduced margins
    const reducedLandMarginsArray = []; // NEW: Separate array for land package reduced margins
    const childMarkupValues = {
        cnb: {},
        cwb: {}
    };
    
    // Collect all markup inputs (excluding reduced margins)
    $('.markup-input:not(.reduced-margin-input)').each(function(index) {
        const $input = $(this);
        
        // Skip land package markups - they're collected separately
        if ($input.hasClass('land-markup-input')) {
            return; // Skip this input
        }
        
        const value = parseFloat($input.val()) || 0;
        
        // Get data attributes
        const rating = $input.attr('data-rating') || '';
        const hotel = $input.attr('data-hotel') || '';
        const roomCategory = $input.attr('data-room-category') || '';
        const occupancy = $input.attr('data-occupancy') || '';
        const package = $input.attr('data-package') || '';
        const colIndex = $input.attr('data-col-index') || index;
        const rowIndex = $input.attr('data-row-index') || '';
        const type = $input.attr('data-type') || 'adult';
        
        // Check if this is a CNB or CWB markup
        if (type === 'cnb' || occupancy.includes('CNB') || $input.hasClass('cnb-markup-input')) {
            const key = `cnb_markup_${colIndex}`;
            childMarkupValues.cnb[key] = {
                value: value,
                hotel: hotel,
                room_category: roomCategory,
                occupancy: occupancy,
                rating: rating,
                col_index: colIndex,
                type: 'cnb'
            };
        } else if (type === 'cwb' || occupancy.includes('CWB') || $input.hasClass('cwb-markup-input')) {
            const key = `cwb_markup_${colIndex}`;
            childMarkupValues.cwb[key] = {
                value: value,
                hotel: hotel,
                room_category: roomCategory,
                occupancy: occupancy,
                rating: rating,
                col_index: colIndex,
                type: 'cwb'
            };
        } else {
            const key = `markup_${colIndex}`;
            markupValues[key] = {
                value: value,
                hotel: hotel,
                room_category: roomCategory,
                occupancy: occupancy,
                rating: rating,
                package: package,
                col_index: colIndex,
                row_index: rowIndex,
                type: 'adult'
            };
        }
    });
    
    // Collect REGULAR land package markups (text values) - separate from reduced
    $('.land-markup-input:not(.reduced-margin-input)').each(function() {
        const $input = $(this);
        const type = $input.attr('data-type') || 'adult';
        const value = parseFloat($input.val()) || 0;
        landMarkupValues[type] = value;
        console.log(`Added regular land package markup: ${type} = ${value}`);
    });
    
    // COLLECT ALL REDUCED MARGINS
    $('.reduced-margin-input').each(function() {
        const $input = $(this);
        const type = $input.attr('data-type') || 'adult';
        const value = parseFloat($input.val()) || 0;
        const hotel = $input.attr('data-hotel') || '';
        const roomCategory = $input.attr('data-room-category') || '';
        const occupancy = $input.attr('data-occupancy') || '';
        const rating = $input.attr('data-rating') || '';
        const colIndex = $input.attr('data-col-index') || '';
        const package = $input.attr('data-package') || '';
        
        // Create reduced margin object with all details
        const reducedMarginObj = {
            type: type,
            hotel: hotel,
            room_category: roomCategory,
            occupancy: occupancy,
            rating: rating,
            col_index: colIndex,
            package: package,
            value: value,
            input_name: $input.attr('name') || '',
            input_class: $input.attr('class') || ''
        };
        
        // SEPARATE LAND PACKAGE REDUCED MARGINS
        if (type.startsWith('land_')) {
            // Add to land package reduced margins array
            reducedLandMarginsArray.push(reducedMarginObj);
            console.log(`Collected LAND PACKAGE reduced margin:`, reducedMarginObj);
        } else {
            // Add to hotel reduced margins array
            reducedMarginsArray.push(reducedMarginObj);
            console.log(`Collected HOTEL reduced margin:`, reducedMarginObj);
        }
    });
    
    console.log("=== COLLECTED DATA SUMMARY ===");
    console.log("Hotel reduced margins collected:", reducedMarginsArray.length);
    console.log("Land package reduced margins collected:", reducedLandMarginsArray.length);
    console.log("Land package regular markups:", landMarkupValues);
    console.log("=== END SUMMARY ===");
    
    return {
        hotel_markups: markupValues,
        land_package_markups: landMarkupValues, // Regular land package values (text)
        package_markups: packageMarkupValues,
        structured_markups: structuredMarkupValues,
        child_markups: childMarkupValues,
        reduced_margins: reducedMarginsArray,  // Hotel reduced margins
        reduced_land_margins: reducedLandMarginsArray  // Land package reduced margins (separate)
    };
}

function addFormDataToCostingRequest(data) 
{
    
    if (typeof CKEDITOR !== 'undefined' && CKEDITOR.instances["inclusions"]) {
        data.set('inclusions', CKEDITOR.instances["inclusions"].getData());
    }
    if (typeof CKEDITOR !== 'undefined' && CKEDITOR.instances["exclusions"]) {
        data.set('exclusions', CKEDITOR.instances["exclusions"].getData());
    }
    
    // Add all the form fields
    var fields = [
        'origin_city', 'arrival_city', 'arrival_airline', 'arrival_time',
        'departure_city', 'departing_airline', 'departing_time',
        'airport_pick_drop', 'mandatory_services', 'driver_cum_guide',
        'guideyes', 'vehicless', 'roe', 'agent_name', 'fremark',
        'final_toll_price', 'early_checkin', 'luggage_vehicle',
        'hotel_total', 'hotel_total_1', 'hotel_total_2',
        'hotel_names_1', 'hotel_names_2', 'hdn_guide_grand_total',
        'hotel_nights', 'hdn_mandatory_grand_total', 'final_transport', 'child_mandatory_grand_total',
        'discount_bundle_price', 'hdn_final_ticket_price', 'entrance_group_total',
        'all_day_activities_total', 'hdn_final_group_ticket_price', 'entrance_adult_total', 'entrance_child_total',
        'all_day_child_activities_total', 'hdn_final_child_ticket_price', 'hdn_group_activity_total', 'childMealCost',
        'grandTotalMeal', 'meal_type_daywise_price', 'driver_grand_total',
        'hotel_costing_category_wise', 'hotel_costing_category_wise_child',
        'hotel_costing_category_wise_child_cwb', 'hotel_cnb_per_person',
        'hotel_cwb_per_person', 'hotel_names_category_wise', 'train_child_price', 'train_adult_price',
        'hotel_room_category_names_wise', 'markup_percentage',
        'hotel_markup_percentage', 'hdn_group_type', 'hotel_status', 'saved_reduced_margins', 'saved_reduced_land_margins'
    ];
    
    fields.forEach(function(field) {
        var element = $('#' + field);
        if (element.length > 0) {
            data.set(field, element.val());
        }
    });
    
    if (!data.get('hotel_total')) data.set('hotel_total', '0');
    if (!data.get('hotel_total_1')) data.set('hotel_total_1', '0');
    if (!data.get('hotel_total_2')) data.set('hotel_total_2', '0');
    if (!data.get('hotel_status')) data.set('hotel_status', 'yes');

}

